(1,'H5PEditor.ShowWhen','Toggle visibility of a field based on rules',1,0,9,0,0,'','h5p-show-when.js','h5p-show-when.css','','',0,NULL,0,NULL,NULL),
(2,'H5P.Image','Image',1,1,22,0,0,'','image.js','image.css','','[\n  {\n    \"name\": \"file\",\n    \"type\": \"image\",\n    \"label\": \"Image\",\n    \"importance\": \"high\",\n    \"disableCopyright\": true\n  },\n  {\n    \"name\": \"decorative\",\n    \"type\": \"boolean\",\n    \"label\": \"Decorative only\",\n    \"default\": false,\n    \"description\": \"Enable this option if the image is purely decorative and does not add any information to the content on the page. It will be ignored by screen readers and not given any alternative text.\"\n  },\n  {\n    \"name\": \"alt\",\n    \"type\": \"text\",\n    \"label\": \"Alternative text\",\n    \"importance\": \"high\",\n    \"description\": \"Required. If the browser can\'t load the image this text will be displayed instead. Also used by \\\"text-to-speech\\\" readers.\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"decorative\",\n          \"equals\": false\n        }\n      ],\n      \"nullWhenHidden\": true\n    }\n  },\n  {\n    \"name\": \"title\",\n    \"type\": \"text\",\n    \"label\": \"Hover text\",\n    \"importance\": \"low\",\n    \"description\": \"Optional. This text is displayed when the users hover their pointing device over the image.\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"contentName\",\n    \"type\": \"text\",\n    \"label\": \"Image content name\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Image\"\n  },\n  {\n    \"name\": \"expandImage\",\n    \"type\": \"text\",\n    \"label\": \"Expand Image\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Expand Image\"\n  },\n  {\n    \"name\": \"minimizeImage\",\n    \"type\": \"text\",\n    \"label\": \"Minimize Image\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Minimize Image\"\n  }\n]\n',0,NULL,0,NULL,NULL),
(3,'H5P.ImageSlide','Image Slide',1,1,2,0,0,'','image-slide.js','image-slide.css','','[\n  {\n    \"label\": \"Image\",\n    \"name\": \"image\",\n    \"type\": \"library\",\n    \"options\": [\n      \"H5P.Image 1.1\"\n    ]\n  }\n]',0,NULL,0,NULL,NULL),
(4,'H5P.ImageSlider','Image Slider',1,1,1,1,1,'iframe','image-slider.js','image-slider.css','','[\n  {\n    \"label\": \"Images\",\n    \"name\": \"imageSlides\",\n    \"type\": \"list\",\n    \"field\": {\n      \"label\": \"Image Slide\",\n      \"name\": \"imageSlide\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"label\": \"Image Slide\",\n          \"name\": \"imageSlide\",\n          \"type\": \"library\",\n          \"options\": [\n            \"H5P.ImageSlide 1.1\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"label\": \"Aspect ratio\",\n    \"name\": \"aspectRatioMode\",\n    \"type\": \"select\",\n    \"description\": \"Automatic means fixed aspect ratio automatically determined based on the images\",\n    \"default\": \"auto\",\n    \"options\": [\n      {\n        \"value\": \"auto\",\n        \"label\": \"Automatic\"\n      },\n      {\n        \"value\": \"custom\",\n        \"label\": \"Custom\"\n      },\n      {\n        \"value\": \"notFixed\",\n        \"label\": \"Not fixed\"\n      }\n    ]\n  },\n  {\n    \"label\": \"Aspect Ratio Settings\",\n    \"name\": \"aspectRatio\",\n    \"type\": \"group\",\n    \"widget\": \"showWhen\",\n    \"expanded\": true,\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"aspectRatioMode\",\n          \"equals\": \"custom\"\n        }\n      ]\n    },\n    \"fields\": [\n      {\n        \"label\": \"Aspect ratio width\",\n        \"name\": \"aspectWidth\",\n        \"type\": \"number\",\n        \"default\": 4,\n        \"description\": \"If you use 4 here, and 3 for the height the aspect ratio will be 4:3\"\n      },\n      {\n        \"label\": \"Aspect ratio height\",\n        \"name\": \"aspectHeight\",\n        \"type\": \"number\",\n        \"default\": 3,\n        \"description\": \"If you use 3 here, and 4 for the width the aspect ratio will be 4:3\"\n      }\n    ]\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"label\": \"Image slider accessibility\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"nextSlide\",\n        \"type\": \"text\",\n        \"label\": \"Label for next slide buttons\",\n        \"importance\": \"low\",\n        \"default\": \"Next Image\",\n        \"description\": \"This is only used for read-speakers. It won\'t be displayed.\"\n      },\n      {\n        \"name\": \"prevSlide\",\n        \"type\": \"text\",\n        \"label\": \"Label for previous slide buttons\",\n        \"importance\": \"low\",\n        \"default\": \"Previous Image\",\n        \"description\": \"This is only used for read-speakers. It won\'t be displayed.\"\n      },\n      {\n        \"name\": \"gotoSlide\",\n        \"type\": \"text\",\n        \"label\": \"Label for slide buttons\",\n        \"importance\": \"low\",\n        \"default\": \"Go to image %slide\",\n        \"description\": \"This is only used for read-speakers. It won\'t be displayed. %slide is a variable and will be replaced with the image number.\"\n      }\n    ]\n  }\n]',0,NULL,0,NULL,NULL),
