(36,'H5P.SingleChoiceSet','Single Choice Set',1,11,14,1,0,'iframe','scripts/stop-watch.js, scripts/sound-effects.js, scripts/xapi-event-builder.js, scripts/result-slide.js, scripts/solution-view.js, scripts/single-choice-alternative.js, scripts/single-choice.js, scripts/single-choice-set.js','styles/single-choice-set.css','','[\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"List of questions\",\n    \"importance\": \"high\",\n    \"entity\": \"question\",\n    \"min\": 1,\n    \"defaultNum\": 2,\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SingleChoiceSetTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"isSubContent\": true,\n      \"label\": \"Question & alternatives\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"question\",\n          \"type\": \"text\",\n          \"widget\": \"html\",\n          \"tags\": [\n            \"p\",\n            \"br\",\n            \"strong\",\n            \"em\",\n            \"code\"\n          ],\n          \"label\": \"Question\",\n          \"importance\": \"high\"\n        },\n        {\n          \"name\": \"answers\",\n          \"type\": \"list\",\n          \"label\": \"Alternatives - first alternative is the correct one.\",\n          \"importance\": \"medium\",\n          \"entity\": \"answer\",\n          \"min\": 2,\n          \"max\": 4,\n          \"defaultNum\": 2,\n          \"field\": {\n            \"name\": \"answer\",\n            \"type\": \"text\",\n            \"widget\": \"html\",\n            \"tags\": [\n              \"p\",\n              \"br\",\n              \"strong\",\n              \"em\",\n              \"code\"\n            ],\n            \"label\": \"Alternative\",\n            \"importance\": \"medium\"\n          }\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"autoContinue\",\n        \"type\": \"boolean\",\n        \"label\": \"Auto continue\",\n        \"description\": \"Automatically go to next question when alternative is selected\",\n        \"default\": true\n      },\n      {\n        \"name\": \"timeoutCorrect\",\n        \"type\": \"number\",\n        \"label\": \"Timeout on correct answers\",\n        \"importance\": \"low\",\n        \"description\": \"Value in milliseconds\",\n        \"default\": 2000,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"autoContinue\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"timeoutWrong\",\n        \"type\": \"number\",\n        \"label\": \"Timeout on wrong answers\",\n        \"importance\": \"low\",\n        \"description\": \"Value in milliseconds\",\n        \"default\": 3000,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"autoContinue\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"soundEffectsEnabled\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable sound effects\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable retry button\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableSolutionsButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable show solution button\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"passPercentage\",\n        \"type\": \"number\",\n        \"label\": \"Pass percentage\",\n        \"description\": \"Percentage of Total score required for passing the quiz.\",\n        \"min\": 0,\n        \"max\": 100,\n        \"step\": 1,\n        \"default\": 100\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"label\": \"Localize single choice set\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"name\": \"nextButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Next\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Next question\"\n      },\n      {\n        \"name\": \"showSolutionButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Show solution\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Show solution\"\n      },\n      {\n        \"name\": \"retryButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"name\": \"solutionViewTitle\",\n        \"type\": \"text\",\n        \"label\": \"Title for the show solution view\",\n        \"importance\": \"low\",\n        \"default\": \"Solution list\"\n      },\n      {\n        \"name\": \"correctText\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for correct answer\",\n        \"importance\": \"low\",\n        \"default\": \"Correct!\"\n      },\n      {\n        \"name\": \"incorrectText\",\n        \"type\": \"text\",\n        \"label\": \"Readspeaker text for incorrect answer\",\n        \"importance\": \"low\",\n        \"default\": \"Incorrect!\"\n      },\n      {\n        \"name\": \"muteButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"mute\\\" button, to disable feedback sound\",\n        \"importance\": \"low\",\n        \"default\": \"Mute feedback sound\"\n      },\n      {\n        \"name\": \"closeButtonLabel\",\n        \"type\": \"text\",\n        \"label\": \"Label for the \\\"Close\\\" button\",\n        \"importance\": \"low\",\n        \"default\": \"Close\"\n      },\n      {\n        \"name\": \"slideOfTotal\",\n        \"type\": \"text\",\n        \"label\": \"Slide number text\",\n        \"importance\": \"low\",\n        \"description\": \"Announces current slide and total number of slides, variables are :num and :total\",\n        \"default\": \"Slide :num of :total\"\n      },\n      {\n        \"name\": \"scoreBarLabel\",\n        \"type\": \"text\",\n        \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n        \"default\": \"You got :num out of :total points\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"solutionListQuestionNumber\",\n        \"type\": \"text\",\n        \"label\": \"Label for the question number in the solution list\",\n        \"importance\": \"low\",\n        \"description\": \"Announces current question index in solution list, variables are :num\",\n        \"default\": \"Question :num\"\n      },\n      {\n        \"name\": \"a11yShowSolution\",\n        \"type\": \"text\",\n        \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n        \"default\": \"Show the solution. The task will be marked with its correct solution.\",\n        \"importance\": \"low\"\n      },\n      {\n        \"name\": \"a11yRetry\",\n        \"type\": \"text\",\n        \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n        \"default\": \"Retry the task. Reset all responses and start the task over again.\",\n        \"importance\": \"low\"\n      }\n    ]\n  }\n]',0,NULL,0,NULL,NULL),
