(47,'H5P.GoToQuestion','Crossroads',1,3,13,0,0,'','scripts/go-to-question.js','styles/go-to-question.css','','[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"label\": \"Question Text\",\n    \"importance\": \"high\",\n    \"description\": \"The question that the user will make a choice based upon.\"\n  },\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"Choices\",\n    \"importance\": \"high\",\n    \"entity\": \"choice\",\n    \"min\": 2,\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Choice Text\",\n          \"importance\": \"high\",\n          \"description\": \"The label that will displayed on the choice button.\"\n        },\n        {\n          \"name\": \"goTo\",\n          \"type\": \"number\",\n          \"widget\": \"timecode\",\n          \"label\": \"Go To\",\n          \"importance\": \"high\",\n          \"description\": \"The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS.\"\n        },\n        {\n          \"name\": \"ifChosenText\",\n          \"type\": \"text\",\n          \"optional\": true,\n          \"label\": \"If Chosen Text\",\n          \"importance\": \"low\",\n          \"description\": \"An optional confirmation text that will be displayed after the user has pressed the choice button.\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"continueButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Continue Button Label\",\n    \"importance\": \"low\",\n    \"default\": \"Continue\",\n    \"common\": true\n  }\n]',0,NULL,0,NULL,NULL),
