(53,'H5P.OpenEndedQuestion','Open Ended Question',1,0,20,0,0,'','dist/dist.js','dist/styles.css','','[\n  {\n    \"name\": \"question\",\n    \"label\": \"Question or description\",\n    \"importance\": \"high\",\n    \"type\": \"text\"\n  },\n  {\n    \"name\": \"placeholderText\",\n    \"label\": \"Placeholder text\",\n    \"default\": \"Start writing...\",\n    \"importance\": \"low\",\n    \"description\": \"Text that initially will be shown in the input field. Will be removed automatically when the user starts writing.\",\n    \"type\": \"text\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"inputRows\",\n    \"label\": \"Input rows\",\n    \"type\": \"select\",\n    \"importance\": \"high\",\n    \"description\": \"Determines the height of the input field.\",\n    \"options\": [\n      {\n        \"value\": \"1\",\n        \"label\": \"1 line\"\n      },\n      {\n        \"value\": \"2\",\n        \"label\": \"2 lines\"\n      },\n      {\n        \"value\": \"3\",\n        \"label\": \"3 lines\"\n      },\n      {\n        \"value\": \"10\",\n        \"label\": \"10 lines\"\n      }\n    ],\n    \"default\": \"1\"\n  }\n]',0,NULL,0,NULL,NULL),
(54,'H5P.Questionnaire','Questionnaire',1,3,2,1,0,'iframe','dist/dist.js','dist/styles.css','','[\n  {\n    \"name\": \"questionnaireElements\",\n    \"label\": \"Questionnaire elements\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\",\n        \"importance\": \"high\"\n      }\n    ],\n    \"entity\": \"element\",\n    \"min\": 1,\n    \"defaultNum\": 1,\n    \"field\": {\n      \"name\": \"libraryGroup\",\n      \"label\": \"Choose library\",\n      \"importance\": \"high\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"library\",\n          \"type\": \"library\",\n          \"label\": \"Library\",\n          \"importance\": \"high\",\n          \"description\": \"Choose a library\",\n          \"options\": [\n            \"H5P.OpenEndedQuestion 1.0\",\n            \"H5P.SimpleMultiChoice 1.1\"\n          ]\n        },\n        {\n          \"name\": \"requiredField\",\n          \"type\": \"boolean\",\n          \"label\": \"Required field\",\n          \"importance\": \"low\",\n          \"default\": false\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"successScreenOptions\",\n    \"label\": \"Success screen options\",\n    \"importance\": \"low\",\n    \"type\": \"group\",\n    \"fields\": [\n      {\n        \"name\": \"enableSuccessScreen\",\n        \"label\": \"Enable success screen\",\n        \"importance\": \"low\",\n        \"type\": \"boolean\",\n        \"default\": true\n      },\n      {\n        \"name\": \"successScreenImage\",\n        \"label\": \"Add success screen image\",\n        \"importance\": \"low\",\n        \"type\": \"group\",\n        \"fields\": [\n          {\n            \"name\": \"successScreenImage\",\n            \"label\": \"Replace success icon with image\",\n            \"importance\": \"low\",\n            \"type\": \"library\",\n            \"optional\": true,\n            \"options\": [\n              \"H5P.Image 1.1\"\n            ]\n          }\n        ]\n      },\n      {\n        \"name\": \"successMessage\",\n        \"type\": \"text\",\n        \"label\": \"Text to display on submit\",\n        \"importance\": \"low\",\n        \"default\": \"You have completed the questionnaire.\"\n      }\n    ]\n  },\n  {\n    \"name\": \"uiElements\",\n    \"label\": \"UI Elements\",\n    \"importance\": \"low\",\n    \"type\": \"group\",\n    \"fields\": [\n      {\n        \"name\": \"buttonLabels\",\n        \"type\": \"group\",\n        \"label\": \"Button labels\",\n        \"importance\": \"low\",\n        \"fields\": [\n          {\n            \"name\": \"prevLabel\",\n            \"type\": \"text\",\n            \"label\": \"Previous button label\",\n            \"importance\": \"low\",\n            \"default\": \"Back\"\n          },\n          {\n            \"name\": \"continueLabel\",\n            \"type\": \"text\",\n            \"label\": \"Continue button label\",\n            \"importance\": \"low\",\n            \"default\": \"Continue\"\n          },\n          {\n            \"name\": \"nextLabel\",\n            \"type\": \"text\",\n            \"label\": \"Next button label\",\n            \"importance\": \"low\",\n            \"default\": \"Next\"\n          },\n          {\n            \"name\": \"submitLabel\",\n            \"type\": \"text\",\n            \"label\": \"Submit button label\",\n            \"importance\": \"low\",\n            \"default\": \"Submit\"\n          }\n        ]\n      },\n      {\n        \"name\": \"accessibility\",\n        \"type\": \"group\",\n        \"label\": \"Accessibility\",\n        \"importance\": \"low\",\n        \"fields\": [\n          {\n            \"name\": \"requiredTextExitLabel\",\n            \"type\": \"text\",\n            \"label\": \"Required message exit button label\",\n            \"importance\": \"low\",\n            \"default\": \"Close error message\"\n          },\n          {\n            \"name\": \"progressBarText\",\n            \"type\": \"text\",\n            \"label\": \"Progress bar text\",\n            \"importance\": \"low\",\n            \"default\": \"Question %current of %max\",\n            \"description\": \"Used to tell assistive technologies what question it is. Variables: [ %current, %max ]\"\n          }\n        ]\n      },\n      {\n        \"name\": \"requiredMessage\",\n        \"type\": \"text\",\n        \"label\": \"Required message\",\n        \"importance\": \"low\",\n        \"default\": \"This question requires an answer\",\n        \"description\": \"Will display if this field is unanswered and required by a wrapper content type\"\n      },\n      {\n        \"name\": \"requiredText\",\n        \"type\": \"text\",\n        \"label\": \"Required symbol text\",\n        \"importance\": \"low\",\n        \"default\": \"required\",\n        \"description\": \"Text that will accompany an asterisk to signal that a question is required\"\n      },\n      {\n        \"name\": \"submitScreenTitle\",\n        \"type\": \"text\",\n        \"label\": \"Title for the submit screen\",\n        \"importance\": \"low\",\n        \"default\": \"You successfully answered all of the questions\"\n      },\n      {\n        \"name\": \"submitScreenSubtitle\",\n        \"type\": \"text\",\n        \"label\": \"Subtitle for the submit screen\",\n        \"importance\": \"low\",\n        \"default\": \"Click below to submit your answers\"\n      }\n    ]\n  }\n]',0,NULL,0,NULL,NULL),
(55,'H5P.SimpleMultiChoice','Simple Multi Choice',1,1,15,0,0,'','dist/dist.js','dist/styles.css','','[\n  {\n    \"name\": \"question\",\n    \"label\": \"Question\",\n    \"importance\": \"high\",\n    \"type\": \"text\"\n  },\n  {\n    \"name\": \"inputType\",\n    \"label\": \"Multiple choice type\",\n    \"importance\": \"high\",\n    \"type\": \"select\",\n    \"options\": [\n      {\n        \"label\": \"Multiple answers\",\n        \"value\": \"checkbox\"\n      },\n      {\n        \"label\": \"Single answer\",\n        \"value\": \"radio\"\n      }\n    ],\n    \"default\": \"checkbox\"\n  },\n  {\n    \"name\": \"alternatives\",\n    \"label\": \"Answer alternatives\",\n    \"type\": \"list\",\n    \"importance\": \"high\",\n    \"entity\": \"Alternative\",\n    \"min\": 2,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"alternative\",\n      \"label\": \"Alternative\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"label\": \"Text\",\n          \"importance\": \"high\",\n          \"type\": \"text\"\n        },\n        {\n          \"name\": \"feedback\",\n          \"type\": \"group\",\n          \"label\": \"Feedback\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"chosenFeedback\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Message displayed if answer is selected\",\n              \"importance\": \"low\",\n              \"description\": \"Message will appear below the answer on \\\"continue\\\" if this answer is selected.\",\n              \"optional\": true,\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"sub\",\n                \"sup\",\n                \"a\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"notChosenFeedback\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Message displayed if answer is not selected\",\n              \"importance\": \"low\",\n              \"description\": \"Message will appear below the answer on \\\"continue\\\" if this answer is not selected.\",\n              \"optional\": true,\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"sub\",\n                \"sup\",\n                \"a\",\n                \"code\"\n              ]\n            }\n          ]\n        }\n      ]\n    }\n  }\n]\n',0,NULL,0,NULL,NULL),
(56,'H5P.Summary','Summary',1,10,11,1,0,'iframe','js/stop-watch.js, js/xapi-event-builder.js, js/summary.js','css/summary.css','','[\n  {\n    \"name\": \"intro\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introduction text\",\n    \"importance\": \"high\",\n    \"default\": \"Choose the correct statement.\",\n    \"description\": \"Will be displayed above the summary task.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"common\": false\n  },\n  {\n    \"name\": \"summaries\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SummaryTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"label\": \"Summary\",\n    \"entity\": \"statements\",\n    \"max\": 100,\n    \"min\": 1,\n    \"field\": {\n      \"name\": \"statements\",\n      \"type\": \"group\",\n      \"label\": \"Set of statements\",\n      \"importance\": \"high\",\n      \"isSubContent\": true,\n      \"fields\": [\n        {\n          \"name\": \"summary\",\n          \"type\": \"list\",\n          \"label\": \"List of statements for the summary - the first statement is correct.\",\n          \"entity\": \"statement\",\n          \"importance\": \"medium\",\n          \"min\": 2,\n          \"field\": {\n            \"name\": \"text\",\n            \"type\": \"text\",\n            \"label\": \"Statement\",\n            \"importance\": \"medium\",\n            \"widget\": \"html\",\n            \"enterMode\": \"p\",\n            \"tags\": []\n          }\n        },\n        {\n          \"name\": \"tip\",\n          \"type\": \"group\",\n          \"label\": \"Tip\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"tip\",\n              \"label\": \"Tip text\",\n              \"importance\": \"low\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"tags\": [\n                \"p\",\n                \"br\",\n                \"strong\",\n                \"em\",\n                \"code\"\n              ],\n              \"optional\": true\n            }\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"solvedLabel\",\n    \"type\": \"text\",\n    \"label\": \"Text displayed before number of statements solved in the summary task.\",\n    \"importance\": \"low\",\n    \"default\": \"Progress:\",\n    \"description\": \"Will be displayed above the statements. Example: \'Progress: 2/5\'\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreLabel\",\n    \"type\": \"text\",\n    \"label\": \"Text displayed before number of wrong statements selected in the summary task.\",\n    \"importance\": \"low\",\n    \"default\": \"Wrong answers:\",\n    \"description\": \"Will be displayed above the statements. Example: \'Wrong answers: 4\'\",\n    \"common\": true\n  },\n  {\n    \"name\": \"resultLabel\",\n    \"type\": \"text\",\n    \"label\": \"Summary feedback header\",\n    \"importance\": \"low\",\n    \"default\": \"Your result\",\n    \"description\": \"Will be displayed above the summary feedback.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelCorrect\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for correct answer\",\n    \"importance\": \"low\",\n    \"default\": \"Correct.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelIncorrect\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker text for announcing incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect! Please try again.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"alternativeIncorrectLabel\",\n    \"type\": \"text\",\n    \"label\": \"Readspeaker label for incorrect answer\",\n    \"importance\": \"low\",\n    \"default\": \"Incorrect\",\n    \"common\": true\n  },\n  {\n    \"name\": \"labelCorrectAnswers\",\n    \"type\": \"text\",\n    \"label\": \"Label list of correct answers\",\n    \"importance\": \"low\",\n    \"default\": \"Correct answers.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"tipButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Label for the show tip button\",\n    \"importance\": \"low\",\n    \"default\": \"Show tip\",\n    \"common\": true\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"description\": \":num and :total are special keywords which are programmatically updated\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"progressText\",\n    \"type\": \"text\",\n    \"label\": \"Text used for readspeakers to communicate progress\",\n    \"description\": \":num and :total are special keywords which are programmatically updated\",\n    \"default\": \"Progress :num of :total\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]\n',0,NULL,0,NULL,NULL),
