(76,'H5P.ImageHotspotQuestion','Find the Hotspot',1,8,12,1,0,'','image-hotspot-question.js','image-hotspot-question.css','','[\n  {\n    \"name\": \"imageHotspotQuestion\",\n    \"type\": \"group\",\n    \"widget\": \"wizard\",\n    \"label\": \"Image Hotspot Question Editor\",\n    \"importance\": \"high\",\n    \"fields\": [\n      {\n        \"name\": \"backgroundImageSettings\",\n        \"type\": \"group\",\n        \"label\": \"Background image\",\n        \"importance\": \"high\",\n        \"fields\": [\n          {\n            \"name\": \"backgroundImage\",\n            \"type\": \"image\",\n            \"label\": \"Background image\",\n            \"importance\": \"high\",\n            \"description\": \"Select an image to use as background the image hotspot question.\"\n          }\n        ]\n      },\n      {\n        \"name\": \"hotspotSettings\",\n        \"type\": \"group\",\n        \"label\": \"Hotspots\",\n        \"importance\": \"high\",\n        \"widget\": \"imageHotspotQuestion\",\n        \"description\": \"Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.\",\n        \"fields\": [\n          {\n            \"name\": \"taskDescription\",\n            \"type\": \"text\",\n            \"label\": \"Task description\",\n            \"importance\": \"high\",\n            \"description\": \"Instructions to the user.\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"hotspot\",\n            \"type\": \"list\",\n            \"label\": \"Hotspot\",\n            \"importance\": \"high\",\n            \"entity\": \"Hotspot\",\n            \"field\": {\n              \"type\": \"group\",\n              \"label\": \"Hotspot\",\n              \"importance\": \"high\",\n              \"fields\": [\n                {\n                  \"name\": \"userSettings\",\n                  \"type\": \"group\",\n                  \"label\": \"userSettings\",\n                  \"importance\": \"low\",\n                  \"fields\": [\n                    {\n                      \"name\": \"correct\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Correct\",\n                      \"importance\": \"low\",\n                      \"description\": \"There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click.\"\n                    },\n                    {\n                      \"name\": \"feedbackText\",\n                      \"type\": \"text\",\n                      \"label\": \"Feedback\",\n                      \"importance\": \"low\",\n                      \"optional\": true\n                    }\n                  ]\n                },\n                {\n                  \"name\": \"computedSettings\",\n                  \"type\": \"group\",\n                  \"label\": \"computedSettings\",\n                  \"importance\": \"low\",\n                  \"fields\": [\n                    {\n                      \"name\": \"x\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"y\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"width\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"height\",\n                      \"type\": \"number\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"figure\",\n                      \"type\": \"text\",\n                      \"optional\": true\n                    }\n                  ]\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"noneSelectedFeedback\",\n            \"type\": \"text\",\n            \"label\": \"Feedback if the user selects an empty spot:\",\n            \"importance\": \"low\",\n            \"placeholder\": \"You didn\'t locate any hotspots, try again!\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"showFeedbackAsPopup\",\n            \"type\": \"boolean\",\n            \"label\": \"Show feedback as a popup\",\n            \"importance\": \"low\",\n            \"default\": true,\n            \"optional\": true\n          },\n          {\n            \"label\": \"Localization\",\n            \"name\": \"l10n\",\n            \"type\": \"group\",\n            \"fields\": [\n              {\n                \"name\": \"retryText\",\n                \"label\": \"Retry button text\",\n                \"type\": \"text\",\n                \"default\": \"Retry\",\n                \"optional\": true\n              },\n              {\n                \"name\": \"closeText\",\n                \"label\": \"Close button text\",\n                \"type\": \"text\",\n                \"default\": \"Close\",\n                \"optional\": true\n              }\n            ]\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"scoreBarLabel\",\n    \"type\": \"text\",\n    \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n    \"default\": \"You got :num out of :total points\",\n    \"importance\": \"low\",\n    \"common\": true\n  },\n  {\n    \"name\": \"a11yRetry\",\n    \"type\": \"text\",\n    \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n    \"default\": \"Retry the task. Reset all responses and start the task over again.\",\n    \"importance\": \"low\",\n    \"common\": true\n  }\n]',0,NULL,0,NULL,NULL),
