(78,'H5P.Accordion','Accordion',1,0,26,1,0,'iframe','h5p-accordion.js','h5p-accordion.css','','[\n  {\n    \"name\": \"panels\",\n    \"type\": \"list\",\n    \"label\": \"Panels\",\n    \"entity\": \"panel\",\n    \"max\": 100,\n    \"min\": 1,\n    \"field\": {\n      \"name\": \"content\",\n      \"type\": \"group\",\n      \"label\": \"Content\",\n      \"importance\": \"high\",\n      \"entity\": \"content\",\n      \"fields\": [\n        {\n          \"name\": \"title\",\n          \"type\": \"text\",\n          \"label\": \"Title\",\n          \"importance\": \"high\"\n        },\n        {\n          \"name\": \"content\",\n          \"type\": \"library\",\n          \"label\": \"Content type\",\n          \"importance\": \"medium\",\n          \"entity\": \"content\",\n          \"options\": [\n            \"H5P.AdvancedText 1.1\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"hTag\",\n    \"type\": \"select\",\n    \"label\": \"H tags for labels (does not affect the size of the label)\",\n    \"importance\": \"low\",\n    \"description\": \"The h tag used on the labels. Normally H2 but if this belongs under an H2 heading use H3. Does not affect the size of the labels, only used for semantical purposes.\",\n    \"options\": [\n      {\n        \"value\": \"h2\",\n        \"label\": \"H2\"\n      },\n      {\n        \"value\": \"h3\",\n        \"label\": \"H3\"\n      },\n      {\n        \"value\": \"h4\",\n        \"label\": \"H4\"\n      }\n    ],\n    \"default\": \"h2\"\n  }\n]\n',0,NULL,0,NULL,NULL),
(79,'H5P.Agamotto','Agamotto',1,5,2,1,0,'iframe','dist/h5p-agamotto.js','dist/h5p-agamotto.css','','[\n  {\n    \"name\": \"title\",\n    \"label\": \"Heading\",\n    \"importance\": \"high\",\n    \"type\": \"text\",\n    \"optional\": true,\n    \"placeholder\": \"Here you can add an optional heading.\",\n    \"description\": \"The heading you\'d like to show above the image\"\n  },\n  {\n    \"name\": \"items\",\n    \"type\": \"list\",\n    \"label\": \"Items\",\n    \"entity\": \"item\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"importance\": \"medium\",\n    \"min\": 2,\n    \"max\": 50,\n    \"field\": {\n      \"name\": \"item\",\n      \"type\": \"group\",\n      \"label\": \"Item\",\n      \"importance\": \"low\",\n      \"expanded\": true,\n      \"fields\": [\n        {\n          \"name\": \"image\",\n          \"type\": \"library\",\n          \"label\": \"Image\",\n          \"importance\": \"low\",\n          \"options\": [\n            \"H5P.Image 1.1\"\n          ],\n          \"optional\": false\n        },\n        {\n          \"name\": \"labelText\",\n          \"label\": \"Label\",\n          \"importance\": \"low\",\n          \"type\": \"text\",\n          \"optional\": true,\n          \"description\": \"Optional label for a tick. Please make sure it\'s not too long, or it will be hidden.\"\n        },\n        {\n          \"name\": \"description\",\n          \"type\": \"text\",\n          \"importance\": \"low\",\n          \"widget\": \"html\",\n          \"label\": \"Description\",\n          \"optional\": true,\n          \"placeholder\": \"My image description ...\",\n          \"description\": \"Optional description for the image\",\n          \"enterMode\": \"p\",\n          \"tags\": [\n            \"strong\",\n            \"em\",\n            \"sub\",\n            \"sup\",\n            \"h3\",\n            \"h4\",\n            \"ul\",\n            \"ol\",\n            \"a\",\n            \"pre\",\n            \"code\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"fields\": [\n      {\n        \"name\": \"startImage\",\n        \"importance\": \"medium\",\n        \"type\": \"number\",\n        \"label\": \"Start image\",\n        \"description\": \"Set the number of the image to start with.\",\n        \"default\": 1,\n        \"min\": 1,\n        \"max\": 50\n      },\n      {\n        \"name\": \"snap\",\n        \"importance\": \"medium\",\n        \"type\": \"boolean\",\n        \"label\": \"Snap slider\",\n        \"description\": \"If activated, the slider will snap to an image\'s position.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"ticks\",\n        \"importance\": \"medium\",\n        \"type\": \"boolean\",\n        \"label\": \"Display tick marks\",\n        \"description\": \"If activated, the slider bar will display a tick mark for each image.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"labels\",\n        \"importance\": \"medium\",\n        \"type\": \"boolean\",\n        \"label\": \"Display labels\",\n        \"description\": \"If activated, the slider bar will display a label instead of/in addition to tick marks.\",\n        \"default\": false\n      },\n      {\n        \"name\": \"transparencyReplacementColor\",\n        \"importance\": \"medium\",\n        \"type\": \"text\",\n        \"label\": \"Transparency Replacement Color\",\n        \"description\": \"Set the color that will replace transparent areas of the images.\",\n        \"optional\": true,\n        \"default\": \"#000000\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"a11y\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"label\": \"Readspeaker\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"image\",\n        \"type\": \"text\",\n        \"label\": \"Image\",\n        \"importance\": \"low\",\n        \"default\": \"Image\"\n      },\n      {\n        \"name\": \"imageSlider\",\n        \"type\": \"text\",\n        \"label\": \"Image Slider\",\n        \"importance\": \"low\",\n        \"default\": \"Image Slider\"\n      }\n    ]\n  }\n]\n',0,NULL,0,NULL,NULL),
(80,'H5P.Collage','Collage',0,3,16,1,0,'','collage.js, template.js, clip.js','collage.css','','[\n  {\n    \"name\": \"collage\",\n    \"label\": \"Preview\",\n    \"importance\": \"high\",\n    \"type\": \"group\",\n    \"widget\": \"collage\",\n    \"description\": \"You can move(pan) the images around by dragging them. You can also select an image and then use the + or - keys on your keyboard to zoom or simply hold down the Z key while moving your mouse wheel.\",\n    \"fields\": [\n      {\n        \"name\": \"template\",\n        \"label\": \"Layout\",\n        \"importance\": \"high\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"value\": \"1\",\n            \"label\": \"1\"\n          },\n          {\n            \"value\": \"1-1\",\n            \"label\": \"1-1\"\n          },\n          {\n            \"value\": \"2\",\n            \"label\": \"2\"\n          },\n          {\n            \"value\": \"2-1\",\n            \"label\": \"2-1\"\n          },\n          {\n            \"value\": \"1-2\",\n            \"label\": \"1-2\"\n          },\n          {\n            \"value\": \"2-2\",\n            \"label\": \"2-2\"\n          },\n          {\n            \"value\": \"3-1\",\n            \"label\": \"3-1\"\n          },\n          {\n            \"value\": \"1-3\",\n            \"label\": \"1-3\"\n          },\n          {\n            \"value\": \"2-3\",\n            \"label\": \"2-3\"\n          },\n          {\n            \"value\": \"3-2\",\n            \"label\": \"3-2\"\n          },\n          {\n            \"value\": \"3-3\",\n            \"label\": \"3-3\"\n          }\n        ],\n        \"default\": \"2-1\"\n      },\n      {\n        \"name\": \"options\",\n        \"label\": \"Display options\",\n        \"importance\": \"low\",\n        \"type\": \"group\",\n        \"fields\": [\n          {\n            \"name\": \"heightRatio\",\n            \"label\": \"Height\",\n            \"importance\": \"lo