(91,'H5P.ImageHotspots','Image Hotspots',1,8,3,1,1,'iframe','scripts/image-hotspots.js, scripts/hotspot.js, scripts/popup.js','styles/image-hotspots.css','','[\n  {\n    \"label\": \"Background image\",\n    \"importance\": \"high\",\n    \"name\": \"image\",\n    \"type\": \"image\",\n    \"description\": \"Image shown on background.\"\n  },\n  {\n    \"name\": \"backgroundImageAltText\",\n    \"type\": \"text\",\n    \"label\": \"Alternative text for background image\",\n    \"description\": \"If the browser can\'t load the image this text will be displayed instead. Also used by assistive technologies.\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"iconType\",\n    \"type\": \"select\",\n    \"label\": \"Hotspot Icon\",\n    \"options\": [\n      {\n        \"value\": \"icon\",\n        \"label\": \"Predefined icon\"\n      },\n      {\n        \"value\": \"image\",\n        \"label\": \"Uploaded image\"\n      }\n    ],\n    \"default\": \"icon\"\n  },\n  {\n    \"name\": \"icon\",\n    \"type\": \"select\",\n    \"label\": \"Predefined icon\",\n    \"importance\": \"medium\",\n    \"description\": \"Using a predefined icon for the hotspot.\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"iconType\",\n          \"equals\": [\n            \"icon\"\n          ]\n        }\n      ]\n    },\n    \"options\": [\n      {\n        \"value\": \"plus\",\n        \"label\": \"Plus\"\n      },\n      {\n        \"value\": \"minus\",\n        \"label\": \"Minus\"\n      },\n      {\n        \"value\": \"times\",\n        \"label\": \"Times\"\n      },\n      {\n        \"value\": \"check\",\n        \"label\": \"Check\"\n      },\n      {\n        \"value\": \"question\",\n        \"label\": \"Question\"\n      },\n      {\n        \"value\": \"info\",\n        \"label\": \"Info\"\n      },\n      {\n        \"value\": \"exclamation\",\n        \"label\": \"Exclamation\"\n      }\n    ],\n    \"default\": \"plus\"\n  },\n  {\n    \"name\": \"iconImage\",\n    \"type\": \"image\",\n    \"label\": \"Uploaded image\",\n    \"optional\": false,\n    \"description\": \"Use your own image for the hotspot icon.<br>75px by 75px is recommended for your image.\",\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"iconType\",\n          \"equals\": [\n            \"image\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"color\",\n    \"type\": \"text\",\n    \"label\": \"Hotspot color\",\n    \"importance\": \"medium\",\n    \"description\": \"The color of the hotspots\",\n    \"optional\": true,\n    \"default\": \"#981d99\",\n    \"widget\": \"showWhen\",\n    \"spectrum\": {\n      \"showInput\": true\n    },\n    \"showWhen\": {\n      \"widget\": \"colorSelector\",\n      \"rules\": [\n        {\n          \"field\": \"iconType\",\n          \"equals\": [\n            \"icon\"\n          ]\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"hotspots\",\n    \"type\": \"list\",\n    \"entity\": \"hotspot\",\n    \"label\": \"Hotspots\",\n    \"importance\": \"high\",\n    \"min\": 1,\n    \"defaultNum\": 1,\n    \"field\": {\n      \"name\": \"hotspot\",\n      \"type\": \"group\",\n      \"label\": \"Hotspot\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"position\",\n          \"type\": \"group\",\n          \"widget\": \"imageCoordinateSelector\",\n          \"imageFieldPath\": \"../../image\",\n          \"label\": \"Hotspot position\",\n          \"importance\": \"high\",\n          \"description\": \"Click on the thumbnail image to place the hotspot\",\n          \"fields\": [\n            {\n              \"name\": \"x\",\n              \"type\": \"number\"\n            },\n            {\n              \"name\": \"y\",\n              \"type\": \"number\"\n            },\n            {\n              \"name\": \"legacyPositioning\",\n              \"type\": \"boolean\"\n            }\n          ]\n        },\n        {\n          \"name\": \"alwaysFullscreen\",\n          \"type\": \"boolean\",\n          \"label\": \"Cover entire background image\",\n          \"importance\": \"low\",\n          \"description\": \"When the user clicks the hotspot the popup will cover the entire background image\"\n        },\n        {\n          \"name\": \"header\",\n          \"type\": \"text\",\n          \"label\": \"Header\",\n          \"importance\": \"low\",\n          \"description\": \"Optional header for the popup\",\n          \"optional\": true\n        },\n        {\n          \"name\": \"content\",\n          \"type\": \"list\",\n          \"label\": \"Popup content\",\n          \"importance\": \"medium\",\n          \"field\": {\n            \"name\": \"action\",\n            \"type\": \"library\",\n            \"label\": \"Content Item\",\n            \"options\": [\n              \"H5P.Text 1.1\",\n              \"H5P.Video 1.5\",\n              \"H5P.Image 1.1\"\n            ]\n          }\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"hotspotNumberLabel\",\n    \"type\": \"text\",\n    \"label\": \"Hotspot label for assistive technologies\",\n    \"default\": \"Hotspot #num\",\n    \"description\": \"Will help announce what hotspot element has been navigated to if there is no header specified for a hotspot. #num can be used to replace the hotspot number.\",\n    \"common\": true\n  },\n  {\n    \"name\": \"closeButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Close button label for assistive technologies\",\n    \"default\": \"Close\",\n    \"common\": true\n  }\n]\n',0,NULL,0,NULL,NULL),
(92,'H5P.MemoryGame','Memory Game',1,3,29,1,0,'','memory-game.js, card.js, counter.js, popup.js, timer.js, aria-live-region.js','memory-game.css','','[\n  {\n    \"name\": \"cards\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"VerticalTabs\",\n        \"label\": \"Default\"\n      }\n    ],\n    \"label\": \"Cards\",\n    \"importance\": \"high\",\n    \"entity\": \"card\",\n    \"min\": 2,\n    \"max\": 100,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"card\",\n      \"label\": \"Card\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"image\",\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"importance\": \"high\",\n          \"ratio\": 1\n        },\n        {\n          \"name\": \"imageAlt\",\n          \"type\": \"text\",\n          \"label\": \"Alternative text for Image\",\n          \"importance\": \"high\",\n          \"description\": \"Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users.\"\n        },\n        {\n          \"name\": \"audio\",\n          \"type\": \"audio\",\n          \"importance\": \"high\",\n          \"label\": \"Audio Track\",\n          \"description\": \"An optional sound that plays when the card is turned.\",\n          \"optional\": true,\n          \"widgetExtensions\": [\n            \"AudioRecorder\"\n          ]\n        },\n        {\n          \"name\": \"match\",\n          \"type\": \"image\",\n          \"label\": \"Matching Image\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"description\": \"An optional image to match against instead of using two cards with the same image.\",\n          \"ratio\": 1\n        },\n        {\n          \"name\": \"matchAlt\",\n          \"type\": \"text\",\n          \"label\": \"Alternative text for Matching Image\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"description\": \"Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users.\"\n        },\n        {\n          \"name\": \"matchAudio\",\n          \"type\": \"audio\",\n          \"importance\": \"low\",\n          \"label\": \"Matching Audio Track\",\n          \"description\": \"An optional sound that plays when the second card is turned.\",\n          \"optional\": true,\n          \"widgetExtensions\": [\n            \"AudioRecorder\"\n          ]\n        },\n        {\n          \"name\": \"description\",\n          \"type\": \"text\",\n          \"label\": \"Description\",\n          \"importance\": \"low\",\n          \"maxLength\": 150,\n          \"optional\": true,\n          \"description\": \"An optional short text that will pop up once the two matching cards are found.\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the game behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"useGrid\",\n        \"type\": \"boolean\",\n        \"label\": \"Position the cards in a square\",\n        \"description\": \"Will try to match the number of columns and rows when laying out the cards. Afterward, the cards will be scaled to fit the container.\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"numCardsToUse\",\n        \"type\": \"number\",\n        \"label\": \"Number of cards to use\",\n        \"description\": \"Setting this to a number greater than 2 will make the game pick random cards from the list of cards.\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"min\": 2\n      },\n      {\n        \"name\": \"allowRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Add button for retrying when the game is over\",\n        \"importance\": \"low\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"lookNFeel\",\n    \"type\": \"group\",\n    \"label\": \"Look and feel\",\n    \"importance\": \"low\",\n    \"description\": \"Control the visuals of the game.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"themeColor\",\n        \"type\": \"text\",\n        \"label\": \"Theme Color\",\n        \"importance\": \"low\",\n        \"description\": \"Choose a color to create a theme for your card game.\",\n        \"optional\": true,\n        \"default\": \"#707070\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true\n        }\n      },\n      {\n        \"name\": \"cardBack\",\n        \"type\": \"image\",\n        \"label\": \"Card Back\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"Use a custom back for your cards.\",\n        \"ratio\": 1\n      }\n    ]\n  },\n  {\n    \"label\": \"Localization\",\n    \"importance\": \"low\",\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Card turns text\",\n        \"importance\": \"low\",\n        \"name\": \"cardTurns\",\n        \"type\": \"text\",\n        \"default\": \"Card turns\"\n      },\n      {\n        \"label\": \"Time spent text\",\n        \"importance\": \"low\",\n        \"name\": \"timeSpent\",\n        \"type\": \"text\",\n        \"default\": \"Time spent\"\n      },\n      {\n        \"label\": \"Feedback text\",\n        \"importance\": \"low\",\n        \"name\": \"feedback\",\n        \"type\": \"text\",\n        \"default\": \"Good work!\"\n      },\n      {\n        \"label\": \"Try again button text\",\n        \"importance\": \"low\",\n        \"name\": \"tryAgain\",\n        \"type\": \"text\",\n        \"default\": \"Reset\"\n      },\n      {\n        \"label\": \"Close button label\",\n        \"importance\": \"low\",\n        \"name\": \"closeLabel\",\n        \"type\": \"text\",\n        \"default\": \"Close\"\n      },\n      {\n        \"label\": \"Game label\",\n        \"importance\": \"low\",\n        \"name\": \"label\",\n        \"type\": \"text\",\n        \"default\": \"Memory Game. Find the matching cards.\"\n      },\n      {\n        \"label\": \"Game instructions\",\n        \"importance\": \"low\",\n        \"name\": \"label\",\n        \"type\": \"text\",\n        \"default\": \"Use arrow keys left and right to navigate cards. Use space or enter key to turn card.\"\n      },\n      {\n        \"label\": \"Game finished label\",\n        \"importance\": \"low\",\n        \"name\": \"done\",\n        \"type\": \"text\",\n        \"default\": \"All of the cards have been found.\"\n      },\n      {\n        \"label\": \"Card indexing label\",\n        \"description\": \"%num and %total are placeholders and will be replaced with the respective values for the card.\",\n        \"importance\": \"low\",\n        \"name\": \"cardPrefix\",\n        \"type\": \"text\",\n        \"default\": \"Card %num of %total:\"\n      },\n      {\n        \"label\": \"Card unturned label\",\n        \"importance\": \"low\",\n        \"name\": \"cardUnturned\",\n        \"type\": \"text\",\n        \"default\": \"Unturned. Click to turn.\"\n      },\n      {\n        \"label\": \"Card turned label\",\n        \"importance\": \"low\",\n        \"name\": \"cardTurned\",\n        \"type\": \"text\",\n        \"default\": \"Turned.\"\n      },\n      {\n        \"label\": \"Card matched label\",\n        \"importance\": \"low\",\n        \"name\": \"cardMatched\",\n        \"type\": \"text\",\n        \"default\": \"Match found.\"\n      },\n      {\n        \"label\": \"Card matched announcement\",\n        \"importance\": \"low\",\n        \"name\": \"cardMatchedA11y\",\n        \"type\": \"text\",\n        \"default\": \"Your cards match!\"\n      },\n      {\n        \"label\": \"Card not matched announcement\",\n        \"importance\": \"low\",\n        \"name\": \"cardNotMatchedA11y\",\n        \"type\": \"text\",\n        \"default\": \"Your chosen cards do not match. Turn other cards to try again.\"\n      }\n    ]\n  }\n]\n',0,NULL,0,NULL,NULL),
(93,'H5P.StandardPage','Standard page',1,5,5,0,0,'','standard-page.js','standard-page.css','','[\n  {\n    \"name\": \"elementList\",\n    \"label\": \"Elements\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"entity\": \"element\",\n    \"field\": {\n      \"name\": \"element\",\n      \"type\": \"library\",\n      \"label\": \"Element type\",\n      \"importance\": \"high\",\n      \"description\": \"Library for this page.\",\n      \"options\": [\n        \"H5P.Text 1.1\",\n        \"H5P.TextInputField 1.2\",\n        \"H5P.Image 1.1\"\n      ]\n    }\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional information for the user, which will be available when clicked.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  }\n]\n',0,NULL,0,NULL,NULL),
(94,'H5P.TextInputField','Text input field editor element',1,2,6,0,0,'','text-input-field.js, xapi-generator.js','text-input-field.css','','[\n  {\n    \"name\": \"taskDescription\",\n    \"label\": \"Description of inputfield\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"importance\": \"high\",\n    \"description\": \"Description of what the user should input.\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"placeholderText\",\n    \"label\": \"Placeholder text\",\n    \"type\": \"text\",\n    \"description\": \"A placeholder text for the user.\",\n    \"importance\": \"low\",\n    \"optional\": true\n  },\n  {\n    \"name\": \"maximumLength\",\n    \"label\": \"Maximum text length\",\n    \"type\": \"number\",\n    \"description\": \"Maximum number of characters for the text.\",\n    \"importance\": \"low\",\n    \"optional\": true,\n    \"min\": \"0\"\n  },\n  {\n    \"name\": \"inputFieldSize\",\n    \"label\": \"Input field size\",\n    \"type\": \"select\",\n    \"importance\": \"low\",\n    \"description\": \"The size of the input field in amount of lines it will cover.\",\n    \"options\": [\n      {\n        \"value\": \"1\",\n        \"label\": \"1 line\"\n      },\n      {\n        \"value\": \"3\",\n        \"label\": \"3 lines\"\n      },\n      {\n        \"value\": \"10\",\n        \"label\": \"10 lines\"\n      }\n    ],\n    \"default\": \"1\"\n  },\n  {\n    \"name\": \"requiredField\",\n    \"label\": \"Required field\",\n    \"type\": \"boolean\",\n    \"importance\": \"low\",\n    \"default\": false,\n    \"optional\": true,\n    \"description\": \"Check to make this field required, the user must answer all required fields to be able to export a document.\"\n  },\n  {\n    \"name\": \"remainingChars\",\n    \"type\": \"text\",\n    \"label\": \"Remaining characters\",\n    \"importance\": \"low\",\n    \"common\": true,\n    \"default\": \"Remaining characters: @chars\",\n    \"description\": \"Message for remaining characters. You can use @chars which will be replaced by the corresponding number.\"\n  }\n]\n',0,NULL,0,NULL,NULL),
(95,'H5P.Timeline','Timeline',1,1,21,1,1,'iframe','timeline.js','timeline.css','','[\n  {\n    \"name\": \"timeline\",\n    \"label\": \"Timeline\",\n    \"importance\": \"high\",\n    \"type\": \"group\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"headline\",\n        \"type\": \"text\",\n        \"label\": \"Headline\",\n        \"importance\": \"high\",\n        \"description\": \"Main timeline heading goes here (first page)\"\n      },\n      {\n        \"name\": \"text\",\n        \"type\": \"text\",\n        \"label\": \"Body Text\",\n        \"importance\": \"medium\",\n        \"widget\": \"html\",\n        \"description\": \"The main timeline body goes here (first page).\",\n        \"optional\": true,\n        \"tags\": [\n          \"strong\",\n          \"em\",\n          \"del\",\n          \"a\",\n          \"ul\",\n          \"ol\",\n          \"hr\",\n          \"code\"\n        ]\n      },\n      {\n        \"name\": \"defaultZoomLevel\",\n        \"type\": \"text\",\n        \"label\": \"Default zoom level\",\n        \"importance\": \"low\",\n        \"default\": \"0\",\n        \"optional\": true,\n        \"description\": \"This will tweak the default zoom level. Equivilent to pressing the zoom in or zoom out button the specified number of times. Negative numbers zoom out. default is 0\"\n      },\n      {\n        \"name\": \"backgroundImage\",\n        \"type\": \"image\",\n        \"label\": \"Background image\",\n        \"importance\": \"low\",\n        \"optional\": true,\n        \"description\": \"An image to display as background.\"\n      },\n      {\n        \"name\": \"height\",\n        \"type\": \"number\",\n        \"label\": \"Height\",\n        \"importance\": \"low\",\n        \"description\": \"The height in pixels\",\n        \"default\": 600\n      },\n      {\n        \"name\": \"asset\",\n        \"type\": \"group\",\n        \"label\": \"Asset\",\n        \"importance\": \"low\",\n        \"description\": \"Here you can add an asset to your timeline \\\"front page\\\"\",\n        \"optional\": true,\n        \"fields\": [\n          {\n            \"name\": \"media\",\n            \"type\": \"text\",\n            \"label\": \"Media\",\n            \"importance\": \"low\",\n            \"description\": \"Link to media URL (Twitter, YouTube, Flickr, Vimeo, Google Maps and SoundCloud are currently supported)\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"credit\",\n            \"type\": \"text\",\n            \"label\": \"Credits\",\n            \"importance\": \"low\",\n            \"description\": \"Credits to the media\",\n            \"optional\": true\n          },\n          {\n            \"name\": \"caption\",\n            \"type\": \"text\",\n            \"label\": \"Caption\",\n            \"importance\": \"low\",\n            \"description\": \"Caption description goes here\",\n            \"optional\": true\n          }\n        ]\n      },\n      {\n        \"name\": \"date\",\n        \"type\": \"list\",\n        \"label\": \"Dates\",\n        \"importance\": \"medium\",\n        \"min\": 1,\n        \"description\": \"Add some dates to your timeline!\",\n        \"field\": {\n          \"name\": \"adate\",\n          \"type\": \"group\",\n          \"label\": \"Date\",\n          \"importance\": \"medium\",\n          \"description\": \"Date\",\n          \"fields\": [\n            {\n              \"name\": \"startDate\",\n              \"type\": \"text\",\n              \"label\": \"Start date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"endDate\",\n              \"type\": \"text\",\n              \"label\": \"End date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Headline for the date entry\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Body text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Body for the date entry\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"h2\",\n                \"h3\",\n                \"hr\",\n                \"pre\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tags\",\n              \"importance\": \"medium\",\n              \"description\": \"Enter Tags (categories)\",\n              \"optional\": true\n            },\n            {\n              \"name\": \"asset\",\n              \"type\": \"group\",\n              \"label\": \"Asset\",\n              \"importance\": \"low\",\n              \"description\": \"\",\n              \"optional\": true,\n              \"fields\": [\n                {\n                  \"name\": \"media\",\n                  \"type\": \"text\",\n                  \"label\": \"Media\",\n                  \"importance\": \"low\",\n                  \"description\": \"URL to the media (Twitter, YouTube, Flickr, Vimeo, Wikipedia, Google Maps and SoundCloud are currently supported).\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"thumbnail\",\n                  \"type\": \"image\",\n                  \"label\": \"Thumbnail\",\n                  \"importance\": \"low\",\n                  \"description\": \"Add a thumbnail if needed, 32x32\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"credit\",\n                  \"type\": \"text\",\n                  \"label\": \"Credit\",\n                  \"importance\": \"low\",\n                  \"description\": \"Credits to the media\",\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"caption\",\n                  \"type\": \"text\",\n                  \"label\": \"Caption\",\n                  \"importance\": \"low\",\n                  \"description\": \"Caption text\",\n                  \"optional\": true\n                }\n              ]\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"era\",\n        \"type\": \"list\",\n        \"label\": \"Eras\",\n        \"importance\": \"medium\",\n        \"description\": \"Add an era to your timeline\",\n        \"min\": 0,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"anera\",\n          \"type\": \"group\",\n          \"label\": \"Era\",\n          \"importance\": \"medium\",\n          \"description\": \"\",\n          \"fields\": [\n            {\n              \"name\": \"startDate\",\n              \"type\": \"text\",\n              \"label\": \"Start date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"endDate\",\n              \"type\": \"text\",\n              \"label\": \"End date\",\n              \"importance\": \"medium\",\n              \"description\": \"YYYY,MM,DD (Minimum YYYY required)\",\n              \"optional\": true,\n              \"regexp\": {\n                \"pattern\": \"^-?\\\\d{1,}(,(1[012]|[0]?[1-9])(,([12][0-9]|3[01]|[0]?[1-9]))?)?$\"\n              }\n            },\n            {\n              \"name\": \"headline\",\n              \"type\": \"text\",\n              \"label\": \"Headline\",\n              \"importance\": \"medium\",\n              \"description\": \"Era headline\"\n            },\n            {\n              \"name\": \"text\",\n              \"type\": \"text\",\n              \"label\": \"Text\",\n              \"importance\": \"medium\",\n              \"widget\": \"html\",\n              \"optional\": true,\n              \"description\": \"Era body\",\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"del\",\n                \"a\",\n                \"ul\",\n                \"ol\",\n                \"hr\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"tag\",\n              \"type\": \"text\",\n              \"label\": \"Tag\",\n              \"importance\": \"medium\",\n              \"description\": \"Era tags (categories)\",\n              \"optional\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"language\",\n        \"type\": \"select\",\n        \"label\": \"Language\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"description\": \"The language of the user interface\",\n        \"options\": [\n          {\n            \"value\": \"af\",\n            \"label\": \"Afrikaans\"\n          },\n          {\n            \"value\": \"ar\",\n            \"label\": \"Arabic\"\n          },\n          {\n            \"value\": \"hy\",\n            \"label\": \"Armenian\"\n          },\n          {\n            \"value\": \"eu\",\n            \"label\": \"Basque\"\n          },\n          {\n            \"value\": \"bg\",\n            \"label\": \"Bulgarian\"\n          },\n          {\n            \"value\": \"ca\",\n            \"label\": \"Catalan\"\n          },\n          {\n            \"value\": \"zh-cn\",\n            \"label\": \"Chinese\"\n          },\n          {\n            \"value\": \"hr\",\n            \"label\": \"Croatian / Hrvatski\"\n          },\n          {\n            \"value\": \"cz\",\n            \"label\": \"Czech\"\n          },\n          {\n            \"value\": \"da\",\n            \"label\": \"Danish\"\n          },\n          {\n            \"value\": \"nl\",\n            \"label\": \"Dutch\"\n          },\n          {\n            \"value\": \"en\",\n            \"label\": \"English\"\n          },\n          {\n            \"value\": \"en-24hr\",\n            \"label\": \"English (24-hour time)\"\n          },\n          {\n            \"value\": \"eo\",\n            \"label\": \"Esperanto\"\n          },\n          {\n            \"value\": \"et\",\n            \"label\": \"Estonian\"\n          },\n          {\n            \"value\": \"fo\",\n            \"label\": \"Faroese\"\n          },\n          {\n            \"value\": \"fa\",\n            \"label\": \"Farsi\"\n          },\n          {\n            \"value\": \"fi\",\n            \"label\": \"Finnish\"\n          },\n          {\n            \"value\": \"fr\",\n            \"label\": \"French\"\n          },\n          {\n            \"value\": \"gl\",\n            \"label\": \"Galician\"\n          },\n          {\n            \"value\": \"ka\",\n            \"label\": \"Georgian\"\n          },\n          {\n            \"value\": \"de\",\n            \"label\": \"German / Deutsch\"\n          },\n          {\n            \"value\": \"el\",\n            \"label\": \"Gr