(485,26,'nl','{\n  \"semantics\": [\n    {\n      \"label\": \"Media\",\n      \"fields\": [\n        {\n          \"label\": \"Type\",\n          \"description\": \"Optionele media, die boven de vragen worden getoond\"\n        },\n        {\n          \"label\": \"Deactiveer zoomen van een afbeelding bij een vraag afbeelding\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Vraag\"\n    },\n    {\n      \"label\": \"Beschikbare opties\",\n      \"entity\": \"optie\",\n      \"field\": {\n        \"label\": \"Optie\",\n        \"fields\": [\n          {\n            \"label\": \"Tekst\"\n          },\n          {\n            \"label\": \"Juist\"\n          },\n          {\n            \"label\": \"Tips en feedback\",\n            \"fields\": [\n              {\n                \"label\": \"Tekst voor tip\",\n                \"description\": \"Tip voor de gebruiker. Deze zal verschijnen voordat de gebruiker zijn antwoord(en) controleert.\"\n              },\n              {\n                \"label\": \"Weer te geven bericht als het antwoord is geselecteerd\",\n                \"description\": \"Bericht zal onder het antwoord verschijnen bij controleren als dit antwoord is geselecteerd.\"\n              },\n              {\n                \"label\": \"Weer te geven bericht als het antwoord niet is geselecteerd\",\n                \"description\": \"Bericht zal onder het antwoord verschijnen bij controleren als dit antwoord niet is geselecteerd.\"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Algehele Feedback\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Standaard\"\n            }\n          ],\n          \"label\": \"Defineer aangepaste feedback voor elke score\",\n          \"description\": \"Voorbeeld: 0-20% Slechte score, 21-91% Gemiddelde Score, 91-100% Schitterende Score!\",\n          \"entity\": \"reeks\",\n          \"field\": {\n        