(557,31,'fa','{\n  \"semantics\": [\n    {\n      \"label\": \"رسانه\",\n      \"fields\": [\n        {\n          \"label\": \"نوع\",\n          \"description\": \"با استفاده از این گزینه، رسانه‌ای را به‌صورت اختیاری برای نمایش در بالای این سؤال مشخص می‌کنید.\"\n        },\n        {\n          \"label\": \"Disable image zooming\"\n        }\n      ]\n    },\n    {\n      \"label\": \"سؤال\"\n    },\n    {\n      \"label\": \"پاسخ درست\",\n      \"options\": [\n        {\n          \"label\": \"درست\"\n        },\n        {\n          \"label\": \"غلط\"\n        }\n      ]\n    },\n    {\n      \"label\": \"ترجمه‌های رابط کاربری برای سؤالات درست / نادرست\",\n      \"fields\": [\n        {\n          \"label\": \"برچسبی برای دکمۀ درست\",\n          \"default\": \"درست\"\n        },\n        {\n          \"label\": \"برچسبی برای دکمۀ غلط\",\n          \"default\": \"غلط\"\n        },\n        {\n          \"label\": \"متن بازخورد\",\n          \"default\": \"شما @scoreاز مجموع  @total دریافت کرده‌اید\",\n          \"description\": \"متن بازخورد، متغیرهای در دسترس: @score and @total.مثلاً:  \'You got @score of @total possible points\'\"\n        },\n        {\n          \"label\": \"متنی برای دکمۀ «بررسی»\",\n          \"default\": \"بررسی\"\n        },\n        {\n          \"label\": \"متنی برای دکمۀ «نمایش راه‌حل»\",\n          \"default\": \"نمایش راه‌حل\"\n        },\n        {\n          \"label\": \"متنی برای دکمۀ «تلاش دوباره»\",\n          \"default\": \"تلاش دوباره\"\n        },\n        {\n          \"label\": \"پاسخ نادرست\",\n          \"default\": \"پاسخ نادرست\"\n        },\n        {\n          \"label\": \"پاسخ درست\",\n          \"default\": \"پاسخ درست\"\n        },\n        {\n          \"label\": \"نمایش متنی نوارنمره برای افرادی که از نرم‌افزار مبدل متن به صدا استفاده می‌کنند\",\n          \"default\": \"شما  :num از مجموع  :total امتیاز دریافت کرده‌اید\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Check\\\" button\",\n          \"default\": \"Check the answers. The responses will be marked as correct, incorrect, or unanswered.\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n          \"default\": \"Show the solution. The task will be marked with its correct solution.\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n          \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"تنظیمات بعد از آزمون\",\n      \"description\": \"این گزینه‌ها به شما این امکان را می‌دهد تا چگونگی رفتار این محتوا را کنترل کنید.\",\n      \"fields\": [\n        {\n          \"label\": \"فعالسازی دکمۀ «تلاش دوباره»\"\n        },\n        {\n          \"label\": \"فعالسازی دکمۀ «نمایش راه‌حل»\"\n        },\n        {\n          \"label\": \"فعالسازی دکمۀ «بررسی»\"\n        },\n        {\n          \"label\": \"نمایش پیام تأیید بر روی دکمۀ «بررسی»\"\n        },\n        {\n          \"label\": \"نمایش پیام تأیید بر روی «تلاش دوباره»\"\n        },\n        {\n          \"label\": \"کنترل پاسخ خودکار\",\n          \"description\": \"در نظر بگیرید که با فعالسازی این گزینه، دسترس‌پذیری تحت تأثیر قرار می‌گیرد.\"\n        },\n        {\n          \"label\": \"بازخورد پاسخ درست\",\n          \"description\": \"این گزینه، متن پیش‌فرض بازخورد را حذف خواهد کرد. متغیرهای در دسترس@score و @total \"\n        },\n        {\n          \"label\": \"بازخورد پاسخ نادرست\",\n          \"description\": \"این گزینه، متن پیش‌فرض بازخورد را حذف خواهد کرد. متغیرهای در دسترس@score و @total \"\n        }\n      ]\n    },\n    {\n      \"label\": \"پیام بررسی تأیید\",\n      \"fields\": [\n        {\n          \"label\": \"متن سرصفحه\",\n          \"default\": \"به پایان رسید؟\"\n        },\n        {\n          \"label\": \"بدنۀ متن\",\n          \"default\": \"آیا از خاتمۀ کار اطمینان دارید؟\"\n        },\n        {\n          \"label\": \"برچسب دکمۀ لغو\",\n          \"default\": \"لغو\"\n        },\n        {\n          \"label\": \"برچسب دکمۀ تأیید\",\n          \"default\": \"پایان\"\n        }\n      ]\n    },\n    {\n      \"label\": \"پیام تأیید تلاش دوباره\",\n      \"fields\": [\n        {\n          \"label\": \"متن سرصفحه\",\n          \"default\": \"دوباره تلاش می‌کنید؟\"\n        },\n        {\n          \"label\": \"بدنۀ متن\",\n          \"default\": \"آیا دوباره تلاش می‌کنید؟\"\n        },\n        {\n          \"label\": \"برچسب دکمۀ لغو\",\n          \"default\": \"لغو\"\n        },\n        {\n          \"label\": \"برچسب دکمۀ تأیید\",\n          \"default\": \"تأیید\"\n        }\n      ]\n    }\n  ]\n}'),
