(654,36,'et','{\n  \"semantics\": [\n    {\n      \"label\": \"Küsimuste loetelu\",\n      \"entity\": \"küsimus\",\n      \"widgets\": [\n        {\n          \"label\": \"Vaikimisi\"\n        },\n        {\n          \"label\": \"Tekstiline\"\n        }\n      ],\n      \"field\": {\n        \"label\": \"Küsimus ja alternatiivid\",\n        \"fields\": [\n          {\n            \"label\": \"Küsimus\"\n          },\n          {\n            \"label\": \"Alternatiivid - esimene alternatiiv on õige.\",\n            \"entity\": \"vastus\",\n            \"field\": {\n              \"label\": \"Alternatiiv\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Üldine tagasiside\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Vaikimisi\"\n            }\n          ],\n          \"label\": \"Määratle iga punktisummavahemiku jaoks kohandatud tagasiside\",\n          \"description\": \"Vajuta \\\"Lisa vahemik\\\" nuppu, et lisada vajalikud vahemikud. Näiteks: 0-20% halb tulemus, 21-91% keskmine tulemus, 91-100% suurepärane tulemus!\",\n          \"entity\": \"vahemik\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"Punktisumma vahemik\"\n              },\n              {},\n              {\n                \"label\": \"Määratletud punktisumma vahemiku tagasiside\",\n                \"placeholder\": \"Sisesta tagasiside\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Käitumise seaded\",\n      \"fields\": [\n        {\n          \"label\": \"Automaatne jätkamine\",\n          \"description\": \"Automaatselt liigu järgmisele küsimusele, kui alternatiiv on valitud\"\n        },\n        {\n          \"label\": \"Õige vastuse timeout\",\n          \"description\": \"Väärtus millisekundites\"\n        },\n        {\n          \"label\": \"Valede vastuste timeout\",\n          \"description\": \"Väärtus millisekundites\"\n        },\n        {\n          \"label\": \"Luba heliefektid\"\n        },\n        {\n          \"label\": \"Luba Proovi uuesti nupp\"\n        },\n        {\n          \"label\": \"Luba Näita lahendust nupp\"\n        },\n        {\n          \"label\": \"Edenemise protsent\",\n          \"description\": \"Protsent kogupunktisummast, mis on viktoriini läbimiseks vajalik.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Kohanda ühe valiku kogum\",\n      \"fields\": [\n        {\n          \"label\": \"\\\"Järgmine\\\" nupu silt\",\n          \"default\": \"Järgmine küsimus\"\n        },\n        {\n          \"label\": \"\\\"Näita lahendust\\\" nupu silt\",\n          \"default\": \"Näita lahendust\"\n        },\n        {\n          \"label\": \"\\\"Proovi uuesti\\\" nupu silt\",\n          \"default\": \"Proovi uuesti\"\n        },\n        {\n          \"label\": \"Näita lahendust vaate pealkiri\",\n          \"default\": \"Lahendus\"\n        },\n        {\n          \"label\": \"Õige vastuse tekstilugeri tekst\",\n          \"default\": \"Õige!\"\n        },\n        {\n          \"label\": \"Vale vastuse tekstilugeri tekst\",\n          \"default\": \"Vale!\"\n        },\n        {\n          \"label\": \"\\\"Vaigista\\\" nupu silt, keelamaks tagasiside heli\",\n          \"default\": \"Vaigista tagasiside heli\"\n        },\n        {\n          \"label\": \"\\\"Sulge\\\" nupu silt\",\n          \"default\": \"Sulge\"\n        },\n        {\n          \"label\": \"Leheküljenumbri tekst\",\n          \"description\": \"Teavitab jooksva lehekülje numbri ja lehekülgede koguarvu. Kasutatavad muutujad on :num ja :total\",\n          \"default\": \"Lehekülg :num kokku :total leheküljest\"\n        },\n        {\n          \"label\": \"Punktisumma riba tekstiline esitamine tekstilugeri kasutajaile\",\n          \"default\": \"Sa said :num punkti :total punktist\"\n        },\n        {\n          \"label\": \"Label for the question number in the solution list\",\n          \"description\": \"Announces current question index in solution list, variables are :num\",\n          \"default\": \"Question :num\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n          \"default\": \"Show the solution. The task will be marked with its correct solution.\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n          \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(655,36,'eu','{\n  \"semantics\": [\n    {\n      \"label\": \"Galderen zerrenda\",\n      \"entity\": \"galdera\",\n      \"widgets\": [\n        {\n          \"label\": \"Lehenetsia\"\n        },\n        {\n          \"label\": \"Testuala\"\n        }\n      ],\n      \"field\": {\n        \"label\": \"Galdera eta aukerak\",\n        \"fields\": [\n          {\n            \"label\": \"Galdera\"\n          },\n          {\n            \"label\": \"Aukerak – lehen aukera da egokia.\",\n            \"entity\": \"erantzuna\",\n            \"field\": {\n              \"label\": \"Aukera\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Feedback Orokorra\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Lehenetsia\"\n            }\n          ],\n          \"label\": \"Definitu feedback pertsonalizatua edozein puntuazio tarterako\",\n          \"description\": \"Klikatu \\\"Gehitu tartea\\\" botoia gehitzeko behar haina tarte. Adibidez: 0-%20 Puntuazio txarra, %21-%90 Tarteko puntuazioa, %91-%100 Puntuazio bikaina!\",\n          \"entity\": \"tartea\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"Puntuazio tartea\"\n              },\n              {},\n              {\n                \"label\": \"Definitutako puntuazio tarterako feedbacka\",\n                \"placeholder\": \"Bete feedbacka\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Portaera-ezarpenak\",\n      \"fields\": [\n        {\n          \"label\": \"Jarraitu automatikoki\",\n          \"description\": \"Joan automatikoki hurrengo galderara aukera bat hautatzen denean\"\n        },\n        {\n          \"label\": \"Erantzun zuzenen debora-muga\",\n          \"description\": \"Balioa milisegundotan\"\n        },\n        {\n          \"label\": \"Erantzun okerren debora-muga\",\n          \"description\": \"Balioa milisegundotan\"\n        },\n        {\n          \"label\": \"Gaitu soinu efektuak\"\n        },\n        {\n          \"label\": \"Gaitu berriz saiatzeko botoia\"\n        },\n        {\n          \"label\": \"Gaitu erantzuna erakusteko botoia\"\n        },\n        {\n          \"label\": \"Gainditzeko ehunekoa\",\n          \"description\": \"Galdetegia gainditzeko beharrezkoa den puntuazio totalaren ehunekoa.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Lokalizatu aukera bakarreko multzoa\",\n      \"fields\": [\n        {\n          \"label\": \"\\\"Next\\\" botoiarentzako etiketa\",\n          \"default\": \"Hurrengo galdera\"\n        },\n        {\n          \"label\": \"\\\"Show solution\\\" botoiarentzako etiketa\",\n          \"default\": \"Erakutsi erantzuna\"\n        },\n        {\n          \"label\": \"\\\"Retry\\\" botoiarentzako etiketa\",\n          \"default\": \"Berriz saiatu\"\n        },\n        {\n          \"label\": \"Erantzuna erakusteko ikuspegiaren izenburua\",\n          \"default\": \"Soluzioen zerrenda\"\n        },\n        {\n          \"label\": \"Erantzun zuzenetarako irakurgailuaren testua\",\n          \"default\": \"Zuzena!\"\n        },\n        {\n          \"label\": \"Erantzun okerretarako irakurgailuaren testua\",\n          \"default\": \"Erantzun okerra!\"\n        },\n        {\n          \"label\": \"\\\"mute\\\" botoiaren etiketa, feedback-etako soinua desgaitzeko\",\n          \"default\": \"Mututu feedback-etako soinua\"\n        },\n        {\n          \"label\": \"\\\"Close\\\" botoiaren etiketa\",\n          \"default\": \"Itxi\"\n        },\n        {\n          \"label\": \"Diapositiba zenbakiaren testua\",\n          \"description\": \"Oraingo diapositiba eta diapositiba kopuru osoaren berri ematen du, aldagaiak dira :num and :total\",\n          \"default\": \"Diapositiba :num / :total\"\n        },\n        {\n          \"label\": \"Puntuazio barraren testu adierazpena irakurgailua erabiltzen dutenentzat\",\n          \"default\": \":total puntutik :num lortu dituzu\"\n        },\n        {\n          \"label\": \"Galdera zenbakiaren testua erantzunen zerrendan\",\n          \"description\": \"Oraingo galderaren erantzunen zerrendako indizea erakusten du, aldagaiak :num dira\",\n          \"default\": \":num. galdera\"\n        },\n        {\n          \"label\": \"\\\"Erakutsi erantzun zuzena\\\" botoiaren laguntza-teknologientzako etiketa\",\n          \"default\": \"Erakutsi erantzun zuzena. Zereginaren erantzun zuzena markatuko da.\"\n        },\n        {\n          \"label\": \"\\\"Berriz saiatu\\\" botoiaren laguntza-teknologientzako etiketa\",\n          \"default\": \"Zeregina berriz egiten saiatu. Berrabiarazi erantzun guztiak eta hasi zeregina berriz.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(656,36,'fa','{\n  \"semantics\": [\n    {\n      \"label\": \"فهرست سؤالات\",\n      \"entity\": \"سؤال\",\n      \"widgets\": [\n        {\n          \"label\": \"پیش‌فرض\"\n        },\n        {\n          \"label\": \"متنی\"\n        }\n      ],\n      \"field\": {\n        \"label\": \"سؤال و بدیل‌ها\",\n        \"fields\": [\n          {\n            \"label\": \"سؤال\"\n          },\n          {\n            \"label\": \"بدیل‌ها - اولین بدیل صحیح است.\",\n            \"entity\": \"پاسخ\",\n            \"field\": {\n              \"label\": \"بدیل\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"بازخورد سراسری\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"پیش‌فرض\"\n            }\n          ],\n          \"label\": \"برای هر بازه نمره، بازخورد سفارشی ایجاد کنید\",\n          \"description\": \"روی دکمه «افزودن بازه» کلیک کنید تا هر تعداد بازه که نیاز دارید اضافه کنید. مثال: ۰ - ۲۰ ٪ نمره بد، ۲۱ - ۹۱٪ نمره متوسط، ۹۱ - ۱۰۰ ٪ نمره عالی!\",\n          \"entity\": \"بازه\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"بازه نمره\"\n              },\n              {},\n              {\n                \"label\": \"بازخورد برای بازه نمره تعریف شده\",\n                \"placeholder\": \"بازخورد را پر کنید\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"تنظیمات رفتاری\",\n      \"fields\": [\n        {\n          \"label\": \"ادامه خودکار\",\n          \"description\": \"به طور خودکار وقتی بدیل انتخاب شد به سؤال بعد برو\"\n        },\n        {\n          \"label\": \"وقفه پس از پاسخ صحیح\",\n          \"description\": \"مقدار به میلی‌ثانیه\"\n        },\n        {\n          \"label\": \"وقفه پس از پاسخ غلط\",\n          \"description\": \"مقدار به میلی‌ثانیه\"\n        },\n        {\n          \"label\": \"فعال‌سازی افکت صدا\"\n        },\n        {\n          \"label\": \"فعال‌سازی دکمه تلاش مجدد\"\n        },\n        {\n          \"label\": \"فعال‌سازی دکمه نمایش پاسخ صحیح\"\n        },\n        {\n          \"label\": \"درصد قبولی\",\n          \"description\": \"درصد از نمره کل مورد نیاز برای قبولی در آزمون.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"بومی سازی مجموعه سؤال تک گزینه‌ای\",\n      \"fields\": [\n        {\n          \"label\": \"برچسب دکمه «بعدی»\",\n          \"default\": \"سؤال بعدی\"\n        },\n        {\n          \"label\": \"برچسب دکمه «نمایش پاسخ صحیح»\",\n          \"default\": \"نمایش پاسخ صحیح\"\n        },\n        {\n          \"label\": \"برچسب دکمه «تلاش مجدد»\",\n          \"default\": \"تلاش مجدد\"\n        },\n        {\n          \"label\": \"عنوان پنجره نمایش پاسخ صحیح\",\n          \"default\": \"فهرست پاسخ صحیح\"\n        },\n        {\n          \"label\": \"متن پاسخ صحیح برای تبدیل به گفتار\",\n          \"default\": \"صحیح!\"\n        },\n        {\n          \"label\": \"متن پاسخ غلط برای تبدیل به گفتار\",\n          \"default\": \"غلط!\"\n        },\n        {\n          \"label\": \"برچسب دکمه «بی‌صدا»، برای غیرفعال کردن صدای بازخورد\",\n          \"default\": \"خاموش کردن صدای بازخورد\"\n        },\n        {\n          \"label\": \"برچسب دکمه «بستن»\",\n          \"default\": \"بستن\"\n        },\n        {\n          \"label\": \"متن شماره اسلاید\",\n          \"description\": \"اسلاید جاری و تعداد کل اسلایدها را اعلام می‌کند، متغیرها ‎:num و ‎:total هستند\",\n          \"default\": \"اسلاید ‎:num از ‎:total\"\n        },\n        {\n          \"label\": \"نمایش متنی نوار نمره برای کسانی که از مبدل متن به گفتار استفاده می‌کنند\",\n          \"default\": \"شما از ‎:total امتیاز، ‎:num امتیاز دریافت کردید\"\n        },\n        {\n          \"label\": \"\",\n          \"description\": \"\",\n          \"default\": \"\"\n        },\n        {\n          \"label\": \"توصیف تکنولوژی کمکی برای دکمه «نمایش پاسخ صحیح»\",\n          \"default\": \"پاسخ صحیح را نشان بده. تکلیف با پاسخ صحیح آن علامت‌گذاری می‌شود.\"\n        },\n        {\n          \"label\": \"توصیف تکنولوژی کمکی برای دکمه «تلاش مجدد»\",\n          \"default\": \"تلاش مجدد. تنظیم مجدد همه پاسخ‌ها و شروع دوباره تکلیف.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(657,36,'fi','{\n  \"semantics\": [\n    {\n      \"label\": \"Kysymyslista\",\n      \"entity\": \"Kysymys\",\n      \"widgets\": [\n        {\n          \"label\": \"Default\"\n        },\n        {\n          \"label\": \"Tekstimuotoinen\"\n        }\n      ],\n      \"field\": {\n        \"label\": \"Kysymys ja vaihtoehdot\",\n        \"fields\": [\n          {\n            \"label\": \"Kysymys\"\n          },\n          {\n            \"label\": \"Vaihtoehdot, ensimmäinen vaihtoehto on oikein.\",\n            \"entity\": \"Vaihtoehto\",\n            \"field\": {\n              \"label\": \"Vaihtoehto\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Yleinen palaute\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Oletus\"\n            }\n          ],\n          \"label\": \"Määritä muokattu palaute pisterajojen mukaan.\",\n          \"description\": \"Klikkaa \\\"Lisää alue\\\" painiketta lisätäksesi niin monta pisterajaa kuin tarvit. Esimerkiksi: 0-20% Huono tulos, 21-91% Kelpo tulos, 91-100% Mahtava tulos!\",\n          \"entity\": \"alue\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"Pisteraja\"\n              },\n              {},\n              {\n                \"label\": \"Palaute määritellylle pisterajalle\",\n                \"placeholder\": \"Kirjoita palaute\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Yleisasetukset\",\n      \"fields\": [\n        {\n          \"label\": \"Jatka automaattisestiAuto continue\",\n          \"description\": \"Jatka automaattisesti seuraavaan kysymykseen kun henkilö on tehnyt valinnan.\"\n        },\n        {\n          \"label\": \"Tauko oikean vastauksen jälkeen\",\n          \"description\": \"Arvo millisekunneissa\"\n        },\n        {\n          \"label\": \"Tauko väärän vastauksen jälkeen\",\n          \"description\": \"Arvo millisekunneissa\"\n        },\n        {\n          \"label\": \"Salli ääniefektit\"\n        },\n        {\n          \"label\": \"Salli painike \\\"Yritä uudelleen\\\"\"\n        },\n        {\n          \"label\": \"Salli painike \\\"Katso vastaukset\\\"\"\n        },\n        {\n          \"label\": \"Läpäisyprosentti\",\n          \"description\": \"Kuinka monta prosenttia maksimipisteistä vaaditaan tehtävän läpäisyyn.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Muokkaa käännöksiä\",\n      \"fields\": [\n        {\n          \"label\": \"Teksti \\\"Next\\\" painikkeelle\",\n          \"default\": \"Seuraava kysymys\"\n        },\n        {\n          \"label\": \"Painikkeen \\\"Katso vastaus\\\" nimi\",\n          \"default\": \"Katso vastaus\"\n        },\n        {\n          \"label\": \"Painikkeen \\\"Yritä uudelleen\\\" nimi\",\n          \"default\": \"Yritä uudelleen\"\n        },\n        {\n          \"label\": \"Sivun \\\"Oikea vastaus\\\" otsikko\",\n          \"default\": \"Oikea vastaus\"\n        },\n        {\n          \"label\": \"Ruudunlukijan palaute oikeasta vastauksesta\",\n          \"default\": \"Oikein!\"\n        },\n        {\n          \"label\": \"Ruudunlukijan palaute väärästä vastauksesta\",\n          \"default\": \"Väärin!\"\n        },\n        {\n          \"label\": \"Painikkeen \\\"Mykistä äänipalaute\\\" nimi\",\n          \"default\": \"Mykistä äänipalaute\"\n        },\n        {\n          \"label\": \"Painikkeen \\\"Sulje\\\" nimi\",\n          \"default\": \"Sulje\"\n        },\n        {\n          \"label\": \"Sivun numero\",\n          \"description\": \"Näyttää sivunumeron ja sivujen kokonaismäärän, käyttävissä olevat muuttujat ovat :num ja :total\",\n          \"default\": \"Sivu :num/:total\"\n        },\n        {\n          \"label\": \"Tekstimuotoinen esitys yhteenvedon pisteistä niille jotka käyttävät ruudunlukijasovellusta\",\n          \"default\": \"Sait :num pistettä :total pisteestä\"\n        },\n        {\n          \"label\": \"Label for the question number in the solution list\",\n          \"description\": \"Announces current question index in solution list, variables are :num\",\n          \"default\": \"Question :num\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n          \"default\": \"Show the solution. The task will be marked with its correct solution.\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n          \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n        }\n      ]\n    }\n  ]\n}'),
(658,36,'fr','{\n  \"semantics\": [\n    {\n      \"label\": \"Liste des questions\",\n      \"entity\": \"question\",\n      \"widgets\": [\n        {\n          \"label\": \"Default\"\n        },\n        {\n          \"label\": \"Textual\"\n        }\n      ],\n      \"field\": {\n        \"label\": \"Question et réponses possibles\",\n        \"fields\": [\n          {\n            \"label\": \"Question\"\n          },\n          {\n            \"label\": \"Réponses possibles - la première de la liste est celle qui est juste.\",\n            \"entity\": \"réponse\",\n            \"field\": {\n              \"label\": \"Réponse possible\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Opacité des étiquettes\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Par défaut\"\n            }\n          ],\n          \"label\": \"Définissez le feedback pour chaque intervalle de score\",\n          \"description\": \"Cliquez le bouton \\\"Ajouter Intervalle\\\"  pour ajouter autant d\'intervalles que vous le souhaitez. Exemple : 0-20% Mauvais score, 21-91% Score moyen, 91-100% Score excellent!\",\n          \"entity\": \"intervalle\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"Intervalle de score\"\n              },\n              {},\n              {\n                \"label\": \"Feedback pour l\'intervalle de score défini\",\n                \"placeholder\": \"Remplir le feedback\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Options générales\",\n      \"fields\": [\n        {\n          \"label\": \"Continuer automatiquement\",\n          \"description\": \"Aller automatiquement vers la question suivante quand cette option est séléctionnée\"\n        },\n        {\n          \"label\": \"Temps de pause en cas de réponse correcte\",\n          \"description\": \"En millisecondes\"\n        },\n        {\n          \"label\": \"Temps de pause en cas de réponse incorrecte\",\n          \"description\": \"En millisecondes\"\n        },\n        {\n          \"label\": \"Activer les effets sonores\"\n        },\n        {\n          \"label\": \"Activer le bouton \\\"Recommencer\\\"\"\n        },\n        {\n          \"label\": \"Activer le bouton \\\"Voir la correction\\\"\"\n        },\n        {\n          \"label\": \"Pourcentage de réussite\",\n          \"description\": \"Pourcentage exigé pour considérer que le quiz est réussi.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Interface de la série de questions à choix unique\",\n      \"fields\": [\n        {\n          \"label\": \"Texte pour le bouton \\\"Suivant\\\"\",\n          \"default\": \"Question suivante\"\n        },\n        {\n          \"label\": \"Texte pour le bouton \\\"Voir la solution\\\"\",\n          \"default\": \"Voir la solution\"\n        },\n        {\n          \"label\": \"Texte pour le mode \\\"Correction\\\"\",\n          \"default\": \"Correction\"\n        },\n        {\n          \"label\": \"Texte pour le bouton \\\"Recommencer\\\"\",\n          \"default\": \"Recommencer\"\n        },\n        {\n          \"label\": \"Texte exprimé par la synthèse vocale en cas de réponse correcte\",\n          \"default\": \"Correct !\"\n        },\n        {\n          \"label\": \"Texte exprimé par la synthèse vocale en cas de réponse incorrecte\",\n          \"default\": \"Incorrect !\"\n        },\n        {\n          \"label\": \"Étiquette pour le bouton \\\"Muet\\\", pour désactiver la rétroaction sonore\",\n          \"default\": \"Couper les retours sons\"\n        },\n        {\n          \"label\": \"Étiquette pour le bouton \\\"Fermer\\\"\",\n          \"default\": \"Fermer\"\n        },\n        {\n          \"label\": \"Texte du numéro de diapositive\",\n          \"description\": \"Annonce la diapositive actuelle et le nombre total de diapositives, les variables sont :num et :total\",\n          \"default\": \"Diapositive :num sur :total\"\n        },\n        {\n          \"label\": \"Représentation textuelle du panneau du score pour les utilisateurs de la synthèse vocale\",\n          \"default\": \"Vous avez :num points sur un total de :total\"\n        },\n        {\n          \"label\": \"Label for the question number in the solution list\",\n          \"description\": \"Announces current question index in solution list, variables are :num\",\n          \"default\": \"Question :num\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Show Solution\\\" button\",\n          \"default\": \"Show the solution. The task will be marked with its correct solution.\"\n        },\n        {\n          \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n          \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n        }\n      ]\n    }\n  ]\n}'),
(659,36,'gl','{\n  \"semantics\": [\n    {\n      \"label\": \"Lista de preguntas\",\n      \"entity\": \"pregunta\",\n      \"widgets\": [\n        {\n          \"label\": \"Por defecto\"\n        },\n        {\n          \"label\": \"Textual\"\n        }\n      ],\n      \"field\": {\n        \"label\": \"Preguntas &amp; alternativas\",\n        \"fields\": [\n          {\n            \"label\": \"Pregunta\"\n          },\n          {\n            \"label\": \"Alternativas - a primeira alternativa é a correcta.\",\n            \"entity\": \"resposta\",\n            \"field\": {\n              \"label\": \"Alternativa\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Retroalimentación xeral\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Por defecto\"\n            }\n          ],\n          \"label\": \"Definir retroalimentación personalizada para calquera rango de puntuación\",\n          \"description\": \"Preme o botón \\\"Engadir rango\\\" para engadir os rangos que precises. Exemplo: 0-20% Puntuación mala, 21-91% Puntuacion media, 91-100% Puntuación xenial!\",\n          \"entity\": \"rango\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"Rango de puntuación\"\n              },\n              {},\n              {\n                \"label\": \"Retroalimentación para o rango de puntuación definido\",\n                \"placeholder\": \"Escribe a túa retroalimentación\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Configuración do comportamento\",\n      \"fields\": [\n        {\n          \"label\": \"Continuar automaticamente\",\n          \"description\": \"Ir á seguinte pregunta automaticamente cando se selecciona unha alternativa\"\n        },\n        {\n          \"label\": \"Tempo límite para respostas correctas\",\n          \"description\": \"Valor en milisegundos\"\n        },\n        {\n          \"label\": \"Tempo límite para respostas incorrectas\",\n          \"description\": \"Valor en milisegundos\"\n        },\n        {\n          \"label\": \"Activar efectos de son\"\n        },\n        {\n          \"label\": \"Activar botón reintentar\"\n        },\n        {\n          \"label\": \"Activar botón amosar solución\"\n        },\n        {\n          \"label\": \"Porcentaxe para aprobar\",\n          \"description\": \"Porcentaxe da puntuación total requirida para aprobar a actividade.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Adaptación local do grupo de escolla simple\",\n      \"fields\": [\n        {\n          \"label\": \"Etiqueta para o botón \\\"Seguinte\\\"\",\n          \"default\": \"Seguinte pregunta\"\n        },\n        {\n          \"label\": \"Etiqueta para o botón \\\"Amosar solución\\\"\",\n          \"default\": \"Amosar solución\"\n        },\n        {\n          \"label\": \"Etiqueta para o botón \\\"Reintentar\\\"\",\n          \"default\": \"Reintentar\"\n        },\n        {\n          \"label\": \"Título para a pantalla amosar solución\",\n          \"default\": \"Lista da solución\"\n        },\n        {\n          \"label\": \"Texto para resposta correcta para o lector de pantalla\",\n          \"default\": \"Correcto!\"\n        },\n        {\n          \"label\": \"Texto para resposta incorrecta para o lector de pantalla\",\n          \"default\": \"Incorrecto!\"\n        },\n        {\n          \"label\": \"Etiqueta para o botón \\\"Silenciar\\\", que desactiva o son de retroalimentación\",\n          \"default\": \"Silenciar son de retroalimentación\"\n        },\n        {\n          \"label\": \"Etiqueta para o botón \\\"Pechar\\\"\",\n          \"default\": \"Pechar\"\n        },\n        {\n          \"label\": \"Texto para o número de diapositiva\",\n          \"description\": \"Anuncia a diapositiva actual e o total de diapositivas, as variables son :num e :total\",\n          \"default\": \"Diapositiva :num de :total\"\n        },\n        {\n          \"label\": \"Representación textual da barra de puntuación cando se está a usar un lector de pantalla\",\n          \"default\": \"Conseguiches :num puntos de :total\"\n        },\n        {\n          \"label\": \"Etiqueta para o número de pregunta na lista de solucións\",\n          \"description\": \"Anuncia o número de índice da pregunta actual na lista de solucións, a variable é :num\",\n          \"default\": \"Pregunta :num\"\n        },\n        {\n          \"label\": \"Descrición para as tecnoloxías de asistencia do botón \\\"Amosar solución\\\"\",\n          \"default\": \"Amosar a solución. A tarefa marcarase coa solución correcta.\"\n        },\n        {\n          \"label\": \"Descrición para as tecnoloxías de asistencia do botón \\\"Reintentar\\\"\",\n          \"default\": \"Reintenta a tarefa. Borras todas as respostas e empeza a tarefa de novo.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(660,36,'it','{\n  \"semantics\": [\n    {\n      \"label\": \"Elenco delle domande\",\n      \"entity\": \"domanda\",\n      \"widgets\": [\n        {\n          \"label\": \"Predefinito\"\n        },\n        {\n          \"label\": \"Testuale\"\n        }\n      ],\n      \"field\": {\n        \"label\": \"Domande e alternative\",\n        \"fields\": [\n          {\n            \"label\": \"Domanda\"\n          },\n          {\n            \"label\": \"Alternative - La prima alternativa è quella giusta\",\n            \"entity\": \"risposta\",\n            \"field\": {\n              \"label\": \"Alternativa\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Feedback generale\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Predefinito\"\n            }\n          ],\n          \"label\": \"Definisci un feedback personalizzato per ogni intervallo di punteggio\",\n          \"description\": \"Clicca sul pulsante \\\"Aggiungi intervallo\\\" per aggiungere gli intervalli che ti servono. Per esempio: 0-20%, Punteggio scarso; 21-90%, Punteggio medio; 91-100% Punteggio ottimo!\",\n          \"entity\": \"intervallo\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"Intervallo di punteggio\"\n              },\n              {},\n              {\n                \"label\": \"Feedback per un intervallo di punteggio definito\",\n                \"placeholder\": \"Compila il feedback\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Impostazioni di esecuzione\",\n      \"fields\": [\n        {\n          \"label\": \"Prosecuzione automatica\",\n          \"description\": \"Vai automaticamente alla domanda che segue quando è selezionata l\'alternativa\"\n        },\n        {\n          \"label\": \"Timeout sulle risposte corrette\",\n          \"description\": \"Valore in millisecondi\"