(791,47,'ar','{\n  \"semantics\": [\n    {\n      \"label\":\"نص السؤال\",\n      \"description\":\"السؤال الذي يحدده المستخدم يعتمد على.\"\n    },\n    {\n      \"label\":\"الخيارات\",\n      \"entity\":\"choice\",\n      \"field\":{\n        \"fields\":[\n          {\n            \"label\":\"نص الخيار\",\n            \"description\":\"اللافتة التي سيتم عرضها على زر الخيار.\"\n          },\n          {\n            \"label\":\"اذهب الى\",\n            \"description\":\"الوقت المطلوب الذي سيتم نقل المستخدم إليه عند الضغط على زر الخيار. أدخل رمز الوقت بالشكل M: SS.\"\n          },\n          {\n            \"label\":\"نص اذا تم الاختيار\",\n            \"description\":\"نص التأكيد الاختياري الذي سيتم عرضه بعد أن يقوم المستخدم بالضغط على زر الاختيار.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\":\"لافتة زر المتابعة\",\n      \"default\":\"Continue\"\n    }\n  ]\n}\n'),
(792,47,'bg','{\n  \"semantics\": [\n    {\n      \"label\": \"Текст на въпроса\",\n      \"description\": \"Въпросът, според който потребителят ще направи избор.\"\n    },\n    {\n      \"label\": \"Възможности\",\n      \"entity\": \"избор\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Текст за избор\",\n            \"description\": \"Етикетът ще се появи при избор на бутона.\"\n          },\n          {\n            \"label\": \"Отиди на\",\n            \"description\": \"Целевото време, през което потребителят ще бъде отнесен при натискане на бутона за избор. Въведете времеви код във формат M: SS.\"\n          },\n          {\n            \"label\": \"Ако е избран текст\",\n            \"description\": \"Незадължителен текст за потвърждение, който ще се покаже, след като потребителят е натиснал бутона за избор.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"етикет на бутона за продължение\",\n      \"default\": \"Продължи\"\n    }\n  ]\n}\n'),
(793,47,'bs','{\n  \"semantics\": [\n    {\n      \"label\": \"Tekst pitanja\",\n      \"description\": \"Pitanje na temelju kojeg će korinik odabrati.\"\n    },\n    {\n      \"label\": \"Opcije\",\n      \"entity\": \"opcija\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Tekst opcije\",\n            \"description\": \"Tekst koji će stajati na dugmetu za opcije.\"\n          },\n          {\n            \"label\": \"Idi na\",\n            \"description\": \"Ciljano vrijeme koje će korisnik koristiti kada klikne na dugme za opcije. Unesite vrijeme u formatu M:SS.\"\n          },\n          {\n            \"label\": \"Tekst uvjetnog izbora\",\n            \"description\": \"Tekst koji će se pojaviti kada korisnik klikne na dugme za opcije. Nije obavezno.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Oznaka za dugme za nastavak\",\n      \"default\": \"Nastavi\"\n    }\n  ]\n}'),
(794,47,'ca','{\n  \"semantics\": [\n    {\n      \"label\": \"Text de la pregunta\",\n      \"description\": \"Pregunta en què l’usuari es basarà per fer la selecció.\"\n    },\n    {\n      \"label\": \"Opcions\",\n      \"entity\": \"elecció\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Text del botó de l’opció\",\n            \"description\": \"L’etiqueta que es mostrarà al botó de selecció.\"\n          },\n          {\n            \"label\": \"Ves a\",\n            \"description\": \"Temps objectiu en el qual se situarà l’usuari en prémer el botó de selecció. Introduïu el codi de temps en format M:SS.\"\n          },\n          {\n            \"label\": \"Text per quan es fa la selecció\",\n            \"description\": \"Un text de confirmació opcional es mostrarà després que l’usuari hagi premut el botó d’elecció.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Etiqueta del botó de continuar\",\n      \"default\": \"Continua\"\n    }\n  ]\n}'),
(795,47,'cs','{\n  \"semantics\": [\n    {\n      \"label\": \"Text otázky\",\n      \"description\": \"Otázka, na základě které se uživatel rozhodne.\"\n    },\n    {\n      \"label\": \"Volby\",\n      \"entity\": \"volba\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Text volby\",\n            \"description\": \"Popisek, který se zobrazí na tlačítku volby.\"\n          },\n          {\n            \"label\": \"Přejít na\",\n            \"description\": \"Cílový čas, na který přejde uživatel po stisknutí tlačítka. Zadejte časový kód ve formátu M:SS.\"\n          },\n          {\n            \"label\": \"Pokud zvolený text\",\n            \"description\": \"Volitelný potvrzovací text, který se zobrazí poté, co uživatel stiskne tlačítko volby.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Popisek tlačítka Pokračovat\",\n      \"default\": \"Pokračovat\"\n    }\n  ]\n}\n'),
