(811,47,'nb','{\n  \"semantics\": [\n    {\n      \"label\": \"Spørsmålstekst\",\n      \"description\": \"Spørsmålet som brukeren blir stilt.\"\n    },\n    {\n      \"label\": \"Alternativer\",\n      \"entity\": \"alternativ\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Alternativ tekst\",\n            \"description\": \"Etiketten som vil vises på alternativ knappen.\"\n          },\n          {\n            \"label\": \"Gå til\",\n            \"description\": \"Tidskoden brukeren vil flyttes til når knappen er trykket. Tidskoden må være på formatet M:SS.\"\n          },\n          {\n            \"label\": \"Valgt tekst\",\n            \"description\": \"En valgfri bekreftelsestekst som vises etter brukeren har gjort et valg.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Tekst på fortsett-knapp\",\n      \"default\": \"Fortsett\"\n    }\n  ]\n}\n'),
(812,47,'nl','{\n  \"semantics\": [\n    {\n      \"label\": \"Vraagtekst\",\n      \"description\": \"De vraag waarmee de gebruiker een keuze moet maken.\"\n    },\n    {\n      \"label\": \"Keuzes\",\n      \"entity\": \"choice\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Keuzetekst\",\n            \"description\": \"Het label dat wordt getoond op de keuze-knop.\"\n          },\n          {\n            \"label\": \"Ga naar\",\n            \"description\": \"Het doeltijdstip waar naartoe de gebruiker wordt gebracht wanneer op de keuze-knop wordt geklikt. Voer tijdcode in, in de opmaak M:SS.\"\n          },\n          {\n            \"label\": \"Indien gekozen tekst\",\n            \"description\": \"Een optionele bevestigingstekst die wordt getoond nadat de gebruiker op de keuze-knop heeft geklikt.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Doorgaan-knoplabel\",\n      \"default\": \"Doorgaan\"\n    }\n  ]\n}\n'),
(813,47,'nn','{\n  \"semantics\": [\n    {\n      \"label\": \"Question Text\",\n      \"description\": \"The question that the user will make a choice based upon.\"\n    },\n    {\n      \"label\": \"Choices\",\n      \"entity\": \"choice\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Choice Text\",\n            \"description\": \"The label that will displayed on the choice button.\"\n          },\n          {\n            \"label\": \"Go To\",\n            \"description\": \"The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS.\"\n          },\n          {\n            \"label\": \"If Chosen Text\",\n            \"description\": \"An optional confirmation text that will be displayed after the user has pressed the choice button.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Continue Button Label\",\n      \"default\": \"Hald fram\"\n    }\n  ]\n}\n'),
