(815,47,'pt-br','{\n  \"semantics\": [\n    {\n      \"label\": \"Texto da questão\",\n      \"description\": \"A questão em que o usuário se baseará para escolher uma opção.\"\n    },\n    {\n      \"label\": \"Opções\",\n      \"entity\": \"choice\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Texto da opção\",\n            \"description\": \"O rótulo exibido no botão da opção.\"\n          },\n          {\n            \"label\": \"Ir para\",\n            \"description\": \"O tempo-alvo em que o usuário será redirecionado quando pressionar o botão da opção. Insira o tempo em formato M:SS.\"\n          },\n          {\n            \"label\": \"Texto Se Escolhido\",\n            \"description\": \"Um texto de confirmação opcional que será exibido após o usuário ter pressionado o botão da opção.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Rótulo do botão de continuar\",\n      \"default\": \"Continuar\"\n    }\n  ]\n}\n'),
