(818,47,'ru','{\n  \"semantics\": [\n    {\n      \"label\": \"Текст вопроса\",\n      \"description\": \"Вопрос о том, что пользователь сделает выбор на основе.\"\n    },\n    {\n      \"label\": \"Выбор\",\n      \"entity\": \"выбор\",\n      \"field\": {\n        \"fields\": [\n          {\n            \"label\": \"Текст выбора\",\n            \"description\": \"Надпись, которая будет отображаться на кнопке выбора.\"\n          },\n          {\n            \"label\": \"Перейти к\",\n            \"description\": \"Целевое время, на которое пользователь будет направлен после нажатия кнопки выбора. Введите таймкод в формате M:SS.\"\n          },\n          {\n            \"label\": \"Если выбран текст\",\n            \"description\": \"Дополнительный текст подтверждения, который будет отображаться после нажатия пользователем кнопки выбора.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Надпись кнопки продолжения\",\n      \"default\": \"Продолжить\"\n    }\n  ]\n}\n'),
