(963,54,'af','{\n  \"semantics\": [\n    {\n      \"label\": \"Questionnaire elements\",\n      \"widgets\": [\n        {\n          \"label\": \"Default\"\n        }\n      ],\n      \"entity\": \"element\",\n      \"field\": {\n        \"label\": \"Choose library\",\n        \"fields\": [\n          {\n            \"label\": \"Library\",\n            \"description\": \"Choose a library\"\n          },\n          {\n            \"label\": \"Required field\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Success screen options\",\n      \"fields\": [\n        {\n          \"label\": \"Enable success screen\"\n        },\n        {\n          \"label\": \"Add success screen image\",\n          \"fields\": [\n            {\n              \"label\": \"Replace success icon with image\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Text to display on submit\",\n          \"default\": \"You have completed the questionnaire.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"UI Elements\",\n      \"fields\": [\n        {\n          \"label\": \"Button labels\",\n          \"fields\": [\n            {\n              \"label\": \"Previous button label\",\n              \"default\": \"Back\"\n            },\n            {\n              \"label\": \"Continue button label\",\n              \"default\": \"Continue\"\n            },\n            {\n              \"label\": \"Next button label\",\n              \"default\": \"Next\"\n            },\n            {\n              \"label\": \"Submit button label\",\n              \"default\": \"Submit\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Accessibility\",\n          \"fields\": [\n            {\n              \"label\": \"Required message exit button label\",\n              \"default\": \"Close error message\"\n            },\n            {\n              \"label\": \"Progress bar text\",\n              \"default\": \"Question %current of %max\",\n              \"description\": \"Used to tell assistive technologies what question it is. Variables: [ %current, %max ]\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Required message\",\n          \"default\": \"This question requires an answer\",\n          \"description\": \"Will display if this field is unanswered and required by a wrapper content type\"\n        },\n        {\n          \"label\": \"Required symbol text\",\n          \"default\": \"required\",\n          \"description\": \"Text that will accompany an asterisk to signal that a question is required\"\n        },\n        {\n          \"label\": \"Title for the submit screen\",\n          \"default\": \"You successfully answered all of the questions\"\n        },\n        {\n          \"label\": \"Subtitle for the submit screen\",\n          \"default\": \"Click below to submit your answers\"\n        }\n      ]\n    }\n  ]\n}'),
(964,54,'ar','{\n  \"semantics\": [\n    {\n      \"label\":\"عناصر الاستبيان\",\n      \"widgets\":[\n        {\n          \"label\":\"افتراضي\"\n        }\n      ],\n      \"entity\":\"element\",\n      \"field\":{\n        \"label\":\"اختر المكتبة\",\n        \"fields\":[\n          {\n            \"label\":\"مكتبة\",\n            \"description\":\"اختر مكتبة\"\n          },\n          {\n            \"label\":\"حقل مطلوب\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\":\"خيارات شاشة النجاح\",\n      \"fields\":[\n        {\n          \"label\":\"تمكين شاشة النجاح\"\n        },\n        {\n          \"label\":\"أضف صورة شاشة النجاح\",\n          \"fields\":[\n            {\n              \"label\":\"استبدال ايقونة النجاح مع الصوورة\"\n            }\n          ]\n        },\n        {\n          \"label\":\"النص الذي سيتم عرضه عند الإرسال\",\n          \"default\":\"You have completed the questionnaire.\"\n        }\n      ]\n    },\n    {\n      \"label\":\"UI عناصر\",\n      \"fields\":[\n        {\n          \"label\": \"Button labels\",\n          \"fields\": [\n            {\n              \"label\":\"تسمية الزر السابق\",\n              \"default\":\"Back\"\n            },\n            {\n              \"label\":\"تسمية زر المتابعة\",\n              \"default\":\"Continue\"\n            },\n            {\n              \"label\":\"تسمية الزر التالي\",\n              \"default\":\"Next\"\n            },\n            {\n              \"label\":\"تسمية زر الارسال\",\n              \"default\":\"Submit\"\n            }\n          ]\n        },\n        {\n          \"label\":\"إمكانية الوصول\",\n          \"fields\":[\n            {\n              \"label\":\"الرسالة المطلوبة لتسمية زر الخروج\",\n              \"default\":\"Close error message\"\n            },\n            {\n              \"label\":\"نص شريط الانجاز\",\n              \"default\":\"Question %current of %max\",\n              \"description\":\"Used to tell assistive technologies what question it is. Variables: [ %current, %max ]\"\n            }\n          ]\n        },\n        {\n          \"label\":\"الرسالة المطلوبة\",\n          \"default\":\"This question requires an answer\",\n          \"description\":\"سيظهر إذا كان هذا الحقل بدون إجابة ويتطلبه نوع محتوى المجمع\"\n        },\n        {\n          \"label\":\"نص رمز مطلوب\",\n          \"default\":\"required\",\n          \"description\":\"النص الذي سيصاحب علامة النجمة للإشارة إلى أن السؤال مطلوب\"\n        },\n        {\n          \"label\":\"عنوان شاشة التقديم\",\n          \"default\":\"You successfully answered all of the questions\"\n        },\n        {\n          \"label\":\"العنوان الفرعي لشاشة التقديم\",\n          \"default\":\"Click below to submit your answers\"\n        }\n      ]\n    }\n  ]\n}\n'),
(965,54,'bg','{\n  \"semantics\": [\n    {\n      \"label\": \"Елементи на въпросника\",\n      \"widgets\": [\n        {\n          \"label\": \"По подразбиране\"\n        }\n      ],\n      \"entity\": \"елемент\",\n      \"field\": {\n        \"label\": \"Избор на библиотека\",\n        \"fields\": [\n          {\n            \"label\": \"Библиотека\",\n            \"description\": \"Избери библиотека\"\n          },\n          {\n            \"label\": \"Задължително поле\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Настройки за екран за успех\",\n      \"fields\": [\n        {\n          \"label\": \"Разреши екран за успех\"\n        },\n        {\n          \"label\": \"Добави изображение за екран за успех\",\n          \"fields\": [\n            {\n              \"label\": \"Замени иконата с изображение\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Текст, който се показва при изпращане.\",\n          \"default\": \"Анкетата е завършена.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"UI Елементи\",\n      \"fields\": [\n        {\n          \"label\": \"Етикети за бутоните\",\n          \"fields\": [\n            {\n              \"label\": \"Етикет за бутон Предишен\",\n              \"default\": \"Предишен\"\n            },\n            {\n              \"label\": \"Етикет за бутон Продължи\",\n              \"default\": \"Продължи\"\n            },\n            {\n              \"label\": \"Етикет за бутон Следващ\",\n              \"default\": \"Следващ\"\n            },\n            {\n              \"label\": \"Етикет за бутон Изпрати\",\n              \"default\": \"Изпрати\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Достъпност\",\n          \"fields\": [\n            {\n              \"label\": \"Съобщение при натискане на бутон за изход\",\n              \"default\": \"Съобщение за грешка\"\n            },\n            {\n              \"label\": \"Текст за лентата с напредък\",\n              \"default\": \"Въпрос %current от %max\",\n              \"description\": \"Използва се, за да обясни на помощните технологии какъв въпрос е. Променливи: [ %current, %max ]\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Съобщение за въпрос изискващ задължителен отговор\",\n          \"default\": \"Този въпрос е задължителен за попълване\",\n          \"description\": \"Ще се показва, ако полето е непопълнено\"\n        },\n        {\n          \"label\": \"Текст за задължително поле\",\n          \"default\": \"задължително\",\n          \"description\": \"Текст, придружаващ звездичката, за да сигнализира, че въпросът е задължителен за попълване\"\n        },\n        {\n          \"label\": \"Заглавие за страницата след изпращане\",\n          \"default\": \"Вие отговорихте на всички въпроси\"\n        },\n        {\n          \"label\": \"Подзаглавие за страницата за изпращане\",\n          \"default\": \"Щракнете с мишката по-долу, за да изпратите вашите отговори\"\n        }\n      ]\n    }\n  ]\n}\n'),
(966,54,'bs','{\n  \"semantics\": [\n    {\n      \"label\": \"Questionnaire elements\",\n      \"widgets\": [\n        {\n          \"label\": \"Default\"\n        }\n      ],\n      \"entity\": \"element\",\n      \"field\": {\n        \"label\": \"Choose library\",\n        \"fields\": [\n          {\n            \"label\": \"Library\",\n            \"description\": \"Choose a library\"\n          },\n          {\n            \"label\": \"Required field\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Success screen options\",\n      \"fields\": [\n        {\n          \"label\": \"Enable success screen\"\n        },\n        {\n          \"label\": \"Add success screen image\",\n          \"fields\": [\n            {\n              \"label\": \"Replace success icon with image\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Text to display on submit\",\n          \"default\": \"You have completed the questionnaire.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"UI Elements\",\n      \"fields\": [\n        {\n          \"label\": \"Button labels\",\n          \"fields\": [\n            {\n              \"label\": \"Previous button label\",\n              \"default\": \"Back\"\n            },\n            {\n              \"label\": \"Continue button label\",\n              \"default\": \"Continue\"\n            },\n            {\n              \"label\": \"Next button label\",\n              \"default\": \"Next\"\n            },\n            {\n              \"label\": \"Submit button label\",\n              \"default\": \"Submit\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Accessibility\",\n          \"fields\": [\n            {\n              \"label\": \"Required message exit button label\",\n              \"default\": \"Close error message\"\n            },\n            {\n              \"label\": \"Progress bar text\",\n              \"default\": \"Question %current of