(968,54,'cs','{\n  \"semantics\": [\n    {\n      \"label\": \"Prvky dotazníku\",\n      \"widgets\": [\n        {\n          \"label\": \"Výchozí\"\n        }\n      ],\n      \"entity\": \"element\",\n      \"field\": {\n        \"label\": \"Vybrat knihovnu\",\n        \"fields\": [\n          {\n            \"label\": \"Knihovna\",\n            \"description\": \"Vyberte knihovnu\"\n          },\n          {\n            \"label\": \"Povinné pole\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Možnosti obrazovky úspěchu\",\n      \"fields\": [\n        {\n          \"label\": \"Povolit obrazovku úspěchu\"\n        },\n        {\n          \"label\": \"Přidat obrázek obrazovky úspěchu\",\n          \"fields\": [\n            {\n              \"label\": \"Nahradit ikonu úspěchu obrázkem\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Text, který se má zobrazit při odeslání\",\n          \"default\": \"Vyplnili jste dotazník.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Prvky uživatelského rozhraní\",\n      \"fields\": [\n        {\n          \"label\": \"Popisky tlačítka\",\n          \"fields\": [\n            {\n              \"label\": \"Popisek tlačítka Zpět\",\n              \"default\": \"Zpět\"\n            },\n            {\n              \"label\": \"Popisek tlačítka Pokračovat\",\n              \"default\": \"Pokračovat\"\n            },\n            {\n              \"label\": \"Popisek tlačítka Další\",\n              \"default\": \"Další\"\n            },\n            {\n              \"label\": \"Popisek tlačítka Odeslat\",\n              \"default\": \"Odeslat\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Přístupnost\",\n          \"fields\": [\n            {\n              \"label\": \"Popisek tlačítka zprávy požadované ukončení\",\n              \"default\": \"Zavřít chybové hlášení\"\n            },\n            {\n              \"label\": \"Text ukazate