(975,54,'et','{\n  \"semantics\": [\n    {\n      \"label\": \"Küsitluse elemendid\",\n      \"widgets\": [\n        {\n          \"label\": \"Vaikimisi\"\n        }\n      ],\n      \"entity\": \"element\",\n      \"field\": {\n        \"label\": \"Vali teek\",\n        \"fields\": [\n          {\n            \"label\": \"Teek\",\n            \"description\": \"Vali teek\"\n          },\n          {\n            \"label\": \"Nõutud väli\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Edukuva valikud\",\n      \"fields\": [\n        {\n          \"label\": \"Luba edukuva\"\n        },\n        {\n          \"label\": \"Lisa edukuva pilt\",\n          \"fields\": [\n            {\n              \"label\": \"Asenda eduikoon pildiga\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Tekst, mida näidata esitamisel\",\n          \"default\": \"Oled küsitluse täitnud.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Kasutajaliidese elemendid\",\n      \"fields\": [\n        {\n          \"label\": \"Nuppude sildid\",\n          \"fields\": [\n            {\n              \"label\": \"Eelmine nupu silt\",\n              \"default\": \"Tagasi\"\n            },\n            {\n              \"label\": \"Jätka nupu silt\",\n              \"default\": \"Jätka\"\n            },\n            {\n              \"label\": \"Järgmine nupu silt\",\n              \"default\": \"Järgmine\"\n            },\n            {\n              \"label\": \"Esita nupu silt\",\n              \"default\": \"Esita\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Puudega kasutaja\",\n          \"fields\": [\n            {\n              \"label\": \"Nõutud teade, välju nupu silt\",\n              \"default\": \"Sulge veateade\"\n            },\n            {\n              \"label\": \"Edenemisriba tekst\",\n              \"default\": \"Küsimus %current kokku %max küsimusest\",\n              \"description\": \"Kasutatakse assisteeriva tehnoloogiaga, et öelda, mis küsimusega on tegu. Muutujad: [ %current, %max ]\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Nõutud teade\",\n          \"default\": \"See küsimus vajab vastust\",\n          \"description\": \"Näidatakse, kui väli on täitmata, kuigi täitmine on nõutud ümbrise sisutüübi poolt\"\n        },\n        {\n          \"label\": \"Nõutud sümboli tekst\",\n          \"default\": \"nõutud\",\n          \"description\": \"Tekst, mis saadab tärni, osutamaks, et küsimus on nõutud\"\n        },\n        {\n          \"label\": \"Esita kuva pealkiri\",\n          \"default\": \"Oled edukalt vastanud kõigile küsimustele\"\n        },\n        {\n          \"label\": \"Esita kuva subtiiter\",\n          \"default\": \"Oma vastuste esitamiseks kliki allpool\"\n        }\n      ]\n    }\n  ]\n}'),
(976,54,'eu','{\n  \"semantics\": [\n    {\n      \"label\": \"Galdetegiaren elementuak\",\n      \"widgets\": [\n        {\n          \"label\": \"Lehenetsia\"\n        }\n      ],\n      \"entity\": \"elementua\",\n      \"field\": {\n        \"label\": \"Aukeratu liburutegia\",\n        \"fields\": [\n          {\n            \"label\": \"Liburutegia\",\n            \"description\": \"Aukeratu liburutegi bat\"\n          },\n          {\n            \"label\": \"Beharrezko eremua\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Arrakasta pantailaren aukerak\",\n      \"fields\": [\n        {\n          \"label\": \"Gaitu arrakasta pantaila\"\n        },\n        {\n          \"label\": \"Gehitu arrakasta pantailaren irudia\",\n          \"fields\": [\n            {\n              \"label\": \"Jarri irudia arrakasta ikonoaren ordez\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Bidalketan erakusteko testua\",\n          \"default\": \"Bukatu duzu galdetegia.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Interfazearen elementuak\",\n      \"fields\": [\n        {\n          \"label\": \"Botoien etiketak\",\n          \"fields\": [\n            {\n              \"label\": \"Aurrekoa botoiaren etiketa\",\n              \"default\": \"Aurrekoa\"\n            },\n            {\n              \"label\": \"Jarraitu botoiaren etiketa\",\n              \"default\": \"Jarraitu\"\n            },\n            {\n              \"label\": \"Hurrengoa botoiaren etiketa\",\n              \"default\": \"Hurrengoa\"\n            },\n            {\n              \"label\": \"Bidali botoiaren etiketa\",\n              \"default\": \"Bidali\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Erabilerraztasuna\",\n          \"fields\": [\n            {\n              \"label\": \"Beharrezko mezua irteera botoiaren etiketa\",\n              \"default\": \"Itxi errore mezua\"\n            },\n         