(977,54,'fi','{\n  \"semantics\": [\n    {\n      \"label\": \"Kyselyn osat\",\n      \"widgets\": [\n        {\n          \"label\": \"Oletus\"\n        }\n      ],\n      \"entity\": \"osa\",\n      \"field\": {\n        \"label\": \"Valitse tyyppi\",\n        \"fields\": [\n          {\n            \"label\": \"Tyyppi\",\n            \"description\": \"Valitse kyselyn tyyppi\"\n          },\n          {\n            \"label\": \"Vaadittu kenttä\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Päätösnäkymän valinnat\",\n      \"fields\": [\n        {\n          \"label\": \"Salli päätösnäkymä\"\n        },\n        {\n          \"label\": \"Päätösnäkymän kuva\",\n          \"fields\": [\n            {\n              \"label\": \"Vaihda ikonin tilalle kuva\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Teksti kyselyn lähdettyä eteenpäin\",\n          \"default\": \"Vastaukset lähetetty.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Käyttöliittymä\",\n      \"fields\": [\n        {\n          \"label\": \"Painikkeiden tekstit\",\n          \"fields\": [\n            {\n              \"label\": \"Palaa\",\n              \"default\": \"Palaa\"\n            },\n            {\n              \"label\": \"Jatka\",\n              \"default\": \"Jatka\"\n            },\n            {\n              \"label\": \"Seuraava\",\n              \"default\": \"Seuraava\"\n            },\n            {\n              \"label\": \"Lähetä\",\n              \"default\": \"Lähetä\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Esteettömyys\",\n          \"fields\": [\n            {\n              \"label\": \"Poistuminen virheilmoituksesta\",\n              \"default\": \"Sulje virheilmoitus\"\n            },\n            {\n              \"label\": \"Edistymistä kuvaava teksti\",\n              \"default\": \"Kysymys %current/%max\",\n              \"description\": \"Käytetään esteettömyysteknolo