(989,54,'pt-br','{\n  \"semantics\": [\n    {\n      \"label\": \"Elementos do questionário\",\n      \"widgets\": [\n        {\n          \"label\": \"Padrão\"\n        }\n      ],\n      \"entity\": \"element\",\n      \"field\": {\n        \"label\": \"Escolher biblioteca\",\n        \"fields\": [\n          {\n            \"label\": \"Biblioteca\",\n            \"description\": \"Escolha uma biblioteca\"\n          },\n          {\n            \"label\": \"Campo obrigatório\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Opções da tela de sucesso\",\n      \"fields\": [\n        {\n          \"label\": \"Habilitar tela de sucesso\"\n        },\n        {\n          \"label\": \"Adicionar imagem da tela de sucesso\",\n          \"fields\": [\n            {\n              \"label\": \"Substituir ícone de sucesso com uma imagem\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Texto a ser exibido na submissão\",\n          \"default\": \"Você completou o questionário.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Elementos de interface\",\n      \"fields\": [\n        {\n          \"label\": \"Rótulos de botões\",\n          \"fields\": [\n            {\n              \"label\": \"Rótulo de botão Anterior\",\n              \"default\": \"Voltar\"\n            },\n            {\n              \"label\": \"Rótulo de botão Continuar\",\n              \"default\": \"Continuar\"\n            },\n            {\n              \"label\": \"Rótulo do botão Próximo\",\n              \"default\": \"Próximo\"\n            },\n            {\n              \"label\": \"Rótulo do botão de submissão\",\n              \"default\": \"Submeter\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Acessibilidade\",\n          \"fields\": [\n            {\n              \"label\": \"Rótulo do botão de saída de mensagem obrigatória\",\n              \"default\": \"Mensagem de erro de saída\"\n            },\n            {\n              \"label\": \"Texto da barra de progresso\",\n              \"default\": \"Questão %current de %max\",\n              \"description\": \"Usada para informar a tecnologias assistivas em qual questão se encontra. Variáveis: [ %current, %max ]\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Mensagem obrigatória\",\n          \"default\": \"Esta questão requer uma resposta\",\n          \"description\": \"Será exibida se o campo de uma pergunta obrigatória não for preenchido\"\n        },\n        {\n          \"label\": \"Texto de símbolo de obrigatório\",\n          \"default\": \"obrigatório\",\n          \"description\": \"Texto que acompanhará o asterisco ao informar que a questão é obrigatória\"\n        },\n        {\n          \"label\": \"Título para a tela de submissão\",\n          \"default\": \"Você respondeu todas as questões com sucesso\"\n        },\n        {\n          \"label\": \"Legenda para a tela de submissão\",\n          \"default\": \"Clique abaixo para submeter suas respostas\"\n        }\n      ]\n    }\n  ]\n}\n'),
(990,54,'pt','{\n  \"semantics\": [\n    {\n      \"label\": \"Elementos do questionário\",\n      \"widgets\": [\n        {\n          \"label\": \"Predefinição\"\n        }\n      ],\n      \"entity\": \"elemento\",\n      \"field\": {\n        \"label\": \"Escolher biblioteca\",\n        \"fields\": [\n          {\n            \"label\": \"Biblioteca\",\n            \"description\": \"Escolha uma biblioteca\"\n          },\n          {\n            \"label\": \"Campo obrigatório\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Opções do ecrã de sucesso\",\n      \"fields\": [\n        {\n          \"label\": \"Ativar ecrã de sucesso\"\n        },\n        {\n          \"label\": \"Adicionar imagem do ecrã de sucesso\",\n          \"fields\": [\n            {\n              \"label\": \"Substituir ícone de sucesso por uma imagem\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Texto a ser exibido na submissão\",\n          \"default\": \"Completou o questionário.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Elementos de interface\",\n      \"fields\": [\n        {\n          \"label\": \"Etiquetas dos botões\",\n          \"fields\": [\n            {\n              \"label\": \"Etiqueta do botão Anterior\",\n              \"default\": \"Voltar\"\n            },\n            {\n              \"label\": \"Etiqueta do botão Continuar\",\n              \"default\": \"Continuar\"\n            },\n            {\n              \"label\": \"Etiqueta do botão Seguinte\",\n              \"default\": \"Seguinte\"\n            },\n            {\n              \"label\": \"Etiqueta do botão de submissão\",\n              \"default\": \"Submeter\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Acessibilidade\",\n          \"fields\": [\n            {\n              \"label\": \"Etiqueta do botão de saída da mensagem obrigatória\",\n              \"default\": \"Fechar mensagem de erro\"\n            },\n            {\n              \"label\": \"Texto da barra de progresso\",\n              \"default\": \"Pergunta %current de %max\",\n              \"description\": \"Usada para informar as tecnologias de apoio em que pergunta se encontra. Variáveis: [ %current, %max ]\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Mensagem obrigatória\",\n          \"default\": \"É obrigatório responder a esta pergunta\",\n          \"description\": \"Será exibida se o campo de uma pergunta obrigatória não for preenchido\"\n        },\n        {\n          \"label\": \"Texto do símbolo de obrigatório\",\n          \"default\": \"obrigatório\",\n          \"description\": \"Texto que acompanhará o asterisco para informar que a pergunta é obrigatória\"\n        },\n        {\n          \"label\": \"Título para o ecrã de submissão\",\n          \"default\": \"Respondeu as todas as perguntas com sucesso\"\n        },\n        {\n          \"label\": \"Sub-título para o ecrã de submissão\",\n          \"default\": \"Clique abaixo para submeter as suas respostas\"\n        }\n      ]\n    }\n  ]\n}\n'),
