(1000,54,'zh','{\n  \"semantics\": [\n    {\n      \"label\": \"調查表元件\",\n      \"widgets\": [\n        {\n          \"label\": \"預設\"\n        }\n      ],\n      \"entity\": \"元件\",\n      \"field\": {\n        \"label\": \"資源庫\",\n        \"fields\": [\n          {\n            \"label\": \"資源庫\",\n            \"description\": \"選擇一個資源庫\"\n          },\n          {\n            \"label\": \"必填項目\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"成功畫面設置\",\n      \"fields\": [\n        {\n          \"label\": \"啟用成功畫面\"\n        },\n        {\n          \"label\": \"添加成功畫面圖片\",\n          \"fields\": [\n            {\n              \"label\": \"用圖片來取代成功圖示\"\n            }\n          ]\n        },\n        {\n          \"label\": \"提交後訊息文字\",\n          \"default\": \"你已完成調查表！\"\n        }\n      ]\n    },\n    {\n      \"label\": \"介面相關設置\",\n      \"fields\": [\n        {\n          \"label\": \"按鈕顯示文字\",\n          \"fields\": [\n            {\n              \"label\": \"上一個按鈕的顯示文字\",\n              \"default\": \"上一個\"\n            },\n            {\n              \"label\": \"繼續按鈕的顯示文字\",\n              \"default\": \"繼續\"\n            },\n            {\n              \"label\": \"下一個按鈕的顯示文字\",\n              \"default\": \"下一個\"\n            },\n            {\n              \"label\": \"提交按鈕的顯示文字\",\n              \"default\": \"提交\"\n            }\n          ]\n        },\n        {\n          \"label\": \"無障礙設置\",\n          \"fields\": [\n            {\n              \"label\": \"報讀器上關閉錯誤訊息按鈕的文本\",\n              \"default\": \"關閉錯誤訊息\"\n            },\n            {\n              \"label\": \"報讀器上進度條的文本\",\n              \"default\": \"目前在第 %current 題，總共 %max 題\",\n              \"description\": \"用於報讀器的輔助文本，非顯示用。\"\n            }\n          ]\n        },\n        {\n          \"label\": \"必填項目的顯示訊息\",\n          \"default\": \"這個項目為必填，請務必作答。\",\n          \"description\": \"如果用戶沒有作答必填項目時會出現的訊息。\"\n        },\n        {\n          \"lab