(1070,56,'sv','{\n  \"semantics\": [\n    {\n      \"label\": \"Introduktionstext\",\n      \"default\": \"Välj det korrekta påståendet.\",\n      \"description\": \"Detta kommer visas överst i sammanfattningsuppgift.\"\n    },\n    {\n      \"widgets\": [\n        {\n          \"label\": \"Standard\"\n        },\n        {\n          \"label\": \"Textuell\"\n        }\n      ],\n      \"label\": \"Sammanfattning\",\n      \"entity\": \"påståenden\",\n      \"field\": {\n        \"label\": \"Påståenden\",\n        \"fields\": [\n          {\n            \"label\": \"Påståenden till sammanfattningsuppgift - första påståendet är det korrekta.\",\n            \"entity\": \"påstående\",\n            \"field\": {\n              \"label\": \"Påstående\"\n            }\n          },\n          {\n            \"label\": \"Tips\",\n            \"fields\": [\n              {\n                \"label\": \"Tipstext\"\n              }\n            ]\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Bakgrundsopacitet på flyttbara element\",\n      \"fields\": [\n        {\n          \"widgets\": [\n            {\n              \"label\": \"Standard\"\n            }\n          ],\n          \"label\": \"Definiera anpassad feedback för valfritt poängintervall\",\n          \"description\": \"Klicka på knappen \\\"Lägg till intervall\\\" för att lägga till så många intervall som du behöver. Exempel: 0-20% Underkänt, 21-91% Godkänt, 91-100% Mycket väl godkänt!\",\n          \"entity\": \"intervall\",\n          \"field\": {\n            \"fields\": [\n              {\n                \"label\": \"Poängintervall\"\n              },\n              {},\n              {\n                \"label\": \"Feedback för detta intervall\",\n                \"placeholder\": \"Skriv in feedback här\"\n              }\n            ]\n          }\n        }\n      ]\n    },\n    {\n      \"label\": \"Text som visas före antalet påståenden som är lösta i sammanfattningsuppgiften.\",\n      \"default\": \"Löst:\",\n      \"description\": \"Kommer visas ovanför påståendena. Exempel: \'Löst: 2/5\'\"\n    },\n    {\n      \"label\": \"Text som visas före antalet påståenden med fel i sammanfattningsuppgiften.\",\n      \"default\": \"Antal fel:\",\n      \"description\": \"Kommer visas över påståendena. Exempel: \'Antal fel: 4\'\"\n    },\n    {\n      \"label\": \"Rubrik över feedback\",\n      \"default\": \"Ditt resultat:\",\n      \"description\": \"Kommer visas över feedback på sammanfattningsuppgift.\"\n    },\n    {\n      \"label\": \"Etikett för korrekt svar\",\n      \"default\": \"Rätt\"\n    },\n    {\n      \"label\": \"Skärmläsartext för felaktigt svar\",\n      \"default\": \"Fel. Försök igen.\"\n    },\n    {\n      \"label\": \"Skärmläsaretikett för felaktigt svar\",\n      \"default\": \"Fel\"\n    },\n    {\n      \"label\": \"Etikett för lista med korrekta svar\",\n      \"default\": \"Rätta svar\"\n    },\n    {\n      \"label\": \"Etikett för knapp visa tips\",\n      \"default\": \"Visa tips\"\n    },\n    {\n      \"label\": \"Texten som läses upp när poängen presenteras för användare med skärmläsare\",\n      \"description\": \":num och :total är variabler som uppdateras automatiskt\",\n      \"default\": \"Du fick :num av :total points\"\n    },\n    {\n      \"label\": \"Text som används av skärmläsare för att kommunicera om framsteg\",\n      \"description\": \":num och :total är variabler som uppdateras automatiskt\",\n      \"default\": \"Framsteg :num av :total\"\n    }\n  ]\n}\n'),
