(1141,63,'ar','{\n  \"semantics\": [\n    {\n      \"label\": \"اسم الغرفة\",\n      \"description\": \"اسم المشارك\"\n    },\n    {\n      \"label\": \"ملء الحاوية\",\n      \"description\": \"جعل الغرفة تناسب الحاوية الخاصة بها بنسبة ١٠٠٪ ، و تجاوز عن الطول و العرض المحدد مع القيم\"\n    },\n    {\n      \"label\": \"الطول\",\n      \"description\": \"تعيين ارتفاع غرفة التداول او الحديث\"\n    },\n    {\n      \"label\": \"العرض\",\n      \"description\": \"تعيين عرض غرفة التداول او الحديث\"\n    }\n  ]\n}\n'),
(1142,63,'bs','{\n  \"semantics\": [\n    {\n      \"label\": \"Ime sobe\",\n      \"description\": \"Ime sobe za video-chat u appear.in \"\n    },\n    {\n      \"label\": \"Podesi kontejner\",\n      \"description\": \"Podesi tako da soba odgovara svome kontejneru. Ovo će poništiti visinu i pirinu podešenu na 100 %.\"\n    },\n    {\n      \"label\": \"Visina\",\n      \"description\": \"Odredi visinu sobe za video/audio chat\"\n    },\n    {\n      \"label\": \"Širina\",\n      \"description\": \"Odredi širinu sobe za video/audio chat\"\n    }\n  ]\n}\n'),
(1143,63,'de','{\n  \"semantics\": [\n    {\n      \"label\": \"Raumname\",\n      \"description\": \"Name des Raums\"\n    },\n    {\n      \"label\": \"An den Container anpassen\",\n      \"description\": \"Passt den Raum dem Container an, überschreibt jegliche Höhe und Breite mit 100 %.\"\n    },\n    {\n      \"label\": \"Höhe\",\n      \"description\": \"Setze die Höhe des Chatrooms\"\n    },\n    {\n      \"label\": \"Breite\",\n      \"description\": \"Setze die Breite des Chatrooms\"\n    }\n  ]\n}\n'),
(1144,63,'et','{\n  \"semantics\": [\n    {\n      \"label\": \"Vestluse nimi\",\n      \"description\": \"Appear.in vestluse nimi\"\n    },\n    {\n      \"label\": \"Sobita raami\",\n      \"description\": \"Täidab raami vestlusaknaga. Asendab vestlusakna kõrgus- ja laiusväärtused 100% väärtustega.\"\n    },\n    {\n      \"label\": \"Kõrgus\",\n      \"description\": \"Määra vestlusakna kõrgus\"\n    },\n    {\n      \"label\": \"Laius\",\n      \"description\": \"Määra vestlusakna laius\"\n    }\n  ]\n}\n');
