(1227,66,'ar','{\n  \"semantics\": [\n    {\n      \"fields\": [\n        {\n          \"field\": {\n            \"fields\": [\n              {\n                \"field\": {\n                  \"fields\": [\n                    {},\n                    {},\n                    {},\n                    {},\n                    {},\n                    {\n                      \"label\": \"التعليقات\",\n                      \"description\": \"يتم عرض التعليقات عندما يعرض المستخدم الإجابات المقترحة لكل الشرائح.\"\n                    },\n                    {\n                      \"label\": \"اعرض التعليقات دوماً\"\n                    },\n                    {\n                      \"label\": \"تعتيم الخلفية\"\n                    },\n                    {\n                      \"label\": \"عرض كزر\"\n                    },\n                    {\n                      \"label\": \"حجم الزر\",\n                      \"options\": [\n                        {\n                          \"label\": \"صغير\"\n                        },\n                        {\n                          \"label\": \"كبير\"\n                        }\n                      ]\n                    },\n                    {\n                      \"label\": \"العنوان\"\n                    },\n                    {\n                      \"label\": \"اذهب الى\",\n                      \"options\": [\n                        {\n                          \"label\": \"رقم شريحة محددة\"\n                        },\n                        {\n                          \"label\": \"الشريحة التالية\"\n                        },\n                        {\n                          \"label\": \"الشريحة السابقة\"\n                        }\n                      ]\n                    },\n                    {\n                      \"label\": \"رقم شريحة محددة\",\n                      \"description\": \"ينطبق فقط عندما يتم تحديد \\\"رقم شريحة محددة\\\".\"\n                    },\n                    {\n                      \"label\": \"غير مرئى\",\n                      \"description\": \"المؤشر الافتراضي ، بدون عنوان ولا يوجد مؤشر جدولة. تحذير: سيواجه المستخدمون ذوو الإعاقات أو الذين يستخدمون لوحة المفاتيح فقط مشكلة في استخدام هذا العنصر.\"\n                    }\n                  ]\n                }\n              },\n              {},\n              {\n                \"fields\": [\n                  {\n                    \"label\": \"الصورة\",\n                    \"description\": \"صورة الخلفية يجب ان تكون بنسبة 2:1 (عرض الى ارتفاع ) لتجنب التمدد ، سيتم عرض الصر عالية الدقةبشكل افضل على الشاشات الاكبر حجما.\"\n                  },\n                  {\n                    \"label\": \"اختر لونا\",\n                    \"default\": \"\"\n                  }\n                ]\n              }\n            ]\n          }\n        },\n        {},\n        {\n          \"label\": \"قائمة الكلمات الرئيسية\"\n        },\n        {\n          \"label\": \"اظهار دائما\"\n        },\n        {\n          \"label\": \"اخفاء تلقائي\"\n        },\n        {\n          \"label\": \"تعتيم\"\n        },\n        {\n          \"fields\": [\n            {\n              \"label\": \"الصورة\",\n              \"description\": \"صورة الخلفية يجب ان تكون بنسبة 2:1 (عرض الى ارتفاع ) لتجنب التمدد ، سيتم عرض الصر عالية الدقةبشكل افضل على الشاشات الاكبر حجما.\"\n            },\n            {\n              \"label\": \"اختر لونا\",\n              \"default\": \"\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"التمركز\",\n      \"fields\": [\n        {\n          \"label\": \"الترجمة من اجل \\\" الشريحة\\\"\",\n          \"default\": \"Slide\"\n        },\n        {\n          \"label\": \"الترجمة من اجل \\\" النتيجة\\\"\",\n          \"default\": \"Score\"\n        },\n        {\n          \"label\": \"الترجمة من اجل \\\" نتيجتك \\\"\",\n          \"default\": \"Your Score\"\n        },\n        {\n          \"label\": \"الترجمة من اجل \\\" اعلى نتيجة \\\"\",\n          \"default\": \"Max Score\"\n        },\n        {\n          \"label\": \"الترجمة من اجل \\\" المجموع \\\"\",\n          \"default\": \"Total\"\n        },\n        {\n          \"label\": \"الترجمة من اجل \\\" مجموع النقاط \\\"\",\n          \"default\": \"Total Score\"\n        },\n        {\n          \"label\": \"عنوان زر عرض الحلول\",\n          \"default\": \"Show solutions\"\n        },\n        {\n          \"label\": \"نص زر اعادة المحاولة \",\n          \"default\": \"Retry\"\n        },\n        {\n          \"label\": \"نص زر تصدير النص\",\n          \"default\": \"Export text\"\n        },\n        {\n          \"label\": \"عنوان زر اخفاء قائمة الكلمات الرئيسية\",\n          \"default\": \"Hide keywords list\"\n        },\n        {\n          \"label\": \"عنوان زر اظهار قائمة الكلمات الرئيسية\",\n          \"default\": \"Show keywords list\"\n        },\n        {\n          \"label\": \"لافتة ملء الشاشة\",\n          \"default\": \"Fullscreen\"\n        },\n        {\n          \"label\": \"لافتة الخروج من وضع ملء الشاشة\",\n          \"default\": \"Exit fullscreen\"\n        },\n        {\n          \"label\": \"لافتة الشريحة السابقة\",\n          \"default\": \"Previous slide\"\n        },\n        {\n          \"label\": \"لافتة الشريحة التالية\",\n          \"default\": \"Next slide\"\n        },\n        {\n          \"label\": \"لافتة الشريحة الحالية\",\n          \"default\": \"Current slide\"\n        },\n        {\n          \"label\": \"لافتة آخر شريحة\",\n          \"default\": \"Last slide\"\n        },\n        {\n          \"label\": \"نص الخروج من وضع الحل\",\n          \"default\": \"Exit solution mode\"\n        },\n        {\n          \"label\": \"نص وضع الحل\",\n          \"default\": \"Solution Mode\"\n        },\n        {\n          \"label\": \"النص عندما يكون هناك عدة مهام في نفس الصفحة\",\n          \"default\": \"Multiple tasks\"\n        },\n        {\n          \"label\": \"نص رسالة ال