(1244,66,'ja','{\n  \"semantics\": [\n    {\n      \"fields\": [\n        {\n          \"field\": {\n            \"fields\": [\n              {\n                \"field\": {\n                  \"fields\": [\n                    {},\n                    {},\n                    {},\n                    {},\n                    {},\n                    {\n                      \"label\": \"コメント\",\n                      \"description\": \"このコメントは、ユーザーがすべてのスライドの推奨回答を表示したときに表示されます。\"\n                    },\n                    {\n                      \"label\": \"常にコメントを表示\"\n                    },\n                    {\n                      \"label\": \"背景の不透明度\"\n                    },\n                    {\n                      \"label\": \"ボタンとして表示\"\n                    },\n                    {\n                      \"label\": \"Button size\",\n                      \"options\": [\n                        {\n                          \"label\": \"Small\"\n                        },\n                        {\n                          \"label\": \"Big\"\n                        }\n                      ]\n                    },\n                    {\n                      \"label\": \"タイトル\"\n                    },\n                    {\n                      \"label\": \"行先スライド\",\n                      \"options\": [\n                        {\n                          \"label\": \"指定スライド\"\n                        },\n                        {\n                          \"label\": \"次のスライド\"\n                        },\n                        {\n                          \"label\": \"前のスライド\"\n                        }\n                      ]\n                    },\n                    {\n                      \"label\": \"スライド番号を指定\",\n                      \"description\": \"Only applicable when \'Specific slide number\' is selected\"\n                    },\n                    {\n                      \"label\": \"非表示\",\n                      