(1443,76,'ko','{\n  \"semantics\": [\n    {\n      \"label\": \"Image Hotspot Question Editor\",\n      \"fields\": [\n        {\n          \"label\": \"Background image\",\n          \"fields\": [\n            {\n              \"label\": \"Background image\",\n              \"description\": \"Select an image to use as background the image hotspot question.\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Hotspots\",\n          \"description\": \"Drag and drop the desired figure from the toolbar to create a new hotspot. Double-click to edit an existing hotspot. Drag the hotspot to move it. Pull the resize handler in the lower right corner to resize.\",\n          \"fields\": [\n            {\n              \"label\": \"Task description\",\n              \"description\": \"Instructions to the user.\"\n            },\n            {\n              \"label\": \"Hotspot\",\n              \"entity\": \"Hotspot\",\n              \"field\": {\n                \"label\": \"Hotspot\",\n                \"fields\": [\n                  {\n                    \"label\": \"userSettings\",\n                    \"fields\": [\n                      {\n                        \"label\": \"Correct\",\n                        \"description\": \"There can be multiple correct hotspots. However, the user gets correct/incorrect feedback immediately after first click.\"\n                      },\n                      {\n                        \"label\": \"Feedback\"\n                      }\n                    ]\n                  },\n                  {\n                    \"label\": \"computedSettings\"\n                  }\n                ]\n              }\n            },\n            {\n              \"label\": \"Feedback if the user selects an empty spot:\",\n              \"placeholder\": \"You didn\'t locate any hotspots, try again!\"\n            },\n            {\n              \"label\": \"Show feedback as a popup\"\n            },\n            {\n              \"label\": \"Localization\",\n              \"fields\": [\n                {\n                  \"label\": \"Retry button text\",\n                  \"default\": \"Retry\"\n                },\n                {\n                  \"label\": \"Close button text\",\n                  \"default\": \"Close\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n      \"default\": \"You got :num out of :total points\"\n    },\n    {\n      \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n      \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n    }\n  ]\n}'),
(1444,76,'nb','{\n  \"semantics\": [\n    {\n      \"label\": \"Oppgaveinnstillinger.\",\n      \"fields\": [\n        {\n          \"label\": \"Bakgrunnsbilde\",\n          \"fields\": [\n            {\n              \"label\": \"Bakgrunnsbilde\",\n              \"description\": \"Velg et bilde som bakgrunn til oppgaven.\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Målfelt\",\n          \"description\": \"Dra og slipp en figur for å lage et nytt hotspot. Dobbel-klikk en hotspot for å velge innstillinger. Dra en hotspot for å bevege den. Dra nede til høyre på hotspoten for å endre størrelsen.\",\n          \"fields\": [\n            {\n              \"label\": \"Oppgavebeskrivelse\",\n              \"description\": \"Instruksjoner om hvordan man skal løse oppgaven.\"\n            },\n            {\n              \"label\": \"Målfelt\",\n              \"entity\": \"Målfelt\",\n              \"field\": {\n                \"label\": \"Målfelt\",\n                \"fields\": [\n                  {\n                    \"label\": \"Brukerinnstillinger\",\n                    \"fields\": [\n                      {\n                        \"label\": \"Riktig\",\n                        \"description\": \"Det kan være flere riktige målfelt. Brukeren får umiddelbar tilbakemelding ved avgitt svar.\"\n                      },\n                      {\n                        \"label\": \"Tilbakemelding\"\n                      }\n                    ]\n                  },\n                  {\n                    \"label\": \"Kalkulerte innstillinger\"\n                  }\n                ]\n              }\n            },\n            {\n              \"label\": \"Tilbakemelding når brukeren velger ikke treffer noen målfelt:\",\n              \"placeholder\": \"Du traff ingen målfelt, prøv igjen!\"\n            },\n            {\n              \"label\": \"Show feedback as a popup\"\n            },\n            {\n              \"label\": \"Localization\",\n              \"fields\": [\n                {\n                  \"label\": \"Retry button text\",\n                  \"default\": \"Retry\"\n                },\n                {\n                  \"label\": \"Close button text\",\n                  \"default\": \"Close\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Textual representation of the score bar for those using a readspeaker\",\n      \"default\": \"You got :num out of :total points\"\n    },\n    {\n      \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n      \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n    }\n  ]\n}'),
(1445,76,'nl','{\n  \"semantics\": [\n    {\n      \"label\": \"Editor van de afbeeldingshotspotvraag\",\n      \"fields\": [\n        {\n          \"label\": \"Achtergrondafbeelding\",\n          \"fields\": [\n            {\n              \"label\": \"Achtergrondafbeelding\",\n              \"description\": \"Selecteer een afbeelding die dient als achtergrond voor de hotspotvraag.\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Hotspots\",\n          \"description\": \"Plaats en sleep het gewenste figuur vanaf de werkbalk om een nieuwe hotspot te maken. Dubbelklik om een bestaande hotspot te bewerken. Sleep de hotspot om deze te verplaatsen. Trek aan de handgreep in de rechte benedenhoek van het figuur om het formaat te wijzigen.\",\n          \"fields\": [\n            {\n              \"label\": \"Taakomschrijving\",\n              \"description\": \"Instructies voor de gebruiker.\"\n            },\n            {\n              \"label\": \"Hotspot\",\n              \"entity\": \"Hotspot\",\n              \"field\": {\n                \"label\": \"Hotspot\",\n                \"fields\": [\n                  {\n                    \"label\": \"Gebruikersinstellingen\",\n                    \"fields\": [\n                      {\n                        \"label\": \"Juist\",\n                        \"description\": \"Er kunnen veel juiste hotspots zijn. Echter, de gebruiker krijgt direct feedback (juist/ onjuist) na de eerste klik.\"\n                      },\n                      {\n                        \"label\": \"Feedback\"\n                      }\n                    ]\n                  },\n                  {\n                    \"label\": \"Berekende instellingen\"\n                  }\n                ]\n              }\n            },\n            {\n              \"label\": \"Feedback als de gebruiker een lege hotspot selecteert:\",\n              \"placeholder\": \"Je hebt geen hotspot geselecteerd, probeer het opnieuw!\"\n            },\n            {\n              \"label\": \"Toon feedback als een pop-up\"\n            },\n            {\n              \"label\": \"Instellingen\",\n              \"fields\": [\n                {\n                  \"label\": \"Tekst opnieuw-knop\",\n                  \"default\": \"Opnieuw\"\n                },\n                {\n                  \"label\": \"Tekst sluit-knop\",\n                  \"default\": \"Sluit\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Tekstuele weergave van de scorebalk voor wie een readspeaker gebruikt\",\n      \"default\": \"Je hebt :num van de :total points\"\n    },\n    {\n      \"label\": \"Ondersteunende technologie beschrijving voor \\\"Opnieuw\\\" knop\",\n      \"default\": \"Probeer de taak opnieuw. Reset alle antwoorden en start de taak opnieuw.\"\n    }\n  ]\n}\n'),
