(1448,76,'pt-br','{\n  \"semantics\": [\n    {\n      \"label\": \"Editor de questões de pontos de acessos em imagens\",\n      \"fields\": [\n        {\n          \"label\": \"Imagem de fundo\",\n          \"fields\": [\n            {\n              \"label\": \"Imagem de fundo\",\n              \"description\": \"Seleciona uma imagem para ser usada como plano de fundo para a questão de pontos de acesso em imagem.\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Pontos de acesso\",\n          \"description\": \"Arraste e solte a figura desejada da barra de ferramentas para criar um novo ponto de acesso. Clique duas vezes para editar um ponto de acesso existente. Arraste o ponto de acesso para movê-lo. Arraste o redimensionador no canto direito inferior para redimensionar.\",\n          \"fields\": [\n            {\n              \"label\": \"Descrição da tarefa\",\n              \"description\": \"isntruções para o usuário.\"\n            },\n            {\n              \"label\": \"Ponto de acesso\",\n              \"entity\": \"Hotspot\",\n              \"field\": {\n                \"label\": \"Ponto de acesso\",\n                \"fields\": [\n                  {\n                    \"label\": \"Configurações de usuário\",\n                    \"fields\": [\n                      {\n                        \"label\": \"Correto\",\n                        \"description\": \"Pode haver múltiplos pontos de acesso corretos. Entretanto, o usuário recebe o feedback de correto/incorreto imediatamente após o primeiro clique.\"\n                      },\n                      {\n                        \"label\": \"Feedback\"\n                      }\n                    ]\n                  },\n                  {\n                    \"label\": \"Configurações calculadas\"\n                  }\n                ]\n              }\n            },\n            {\n              \"label\": \"Feedback se o usuário selecionar um ponto vazio:\",\n              \"placeholder\": \"Você não localizou nenhum ponto de acesso, tente novamente!\"\n            },\n            {\n              \"label\": \"Mostrar feedback como um pop-up\"\n            },\n            {\n              \"label\": \"Localização\",\n              \"fields\": [\n                {\n                  \"label\": \"Texto do botão Tentar novamente\",\n                  \"default\": \"Tentar novamente\"\n                },\n                {\n                  \"label\": \"Texto do botão Fechar\",\n                  \"default\": \"Fechar\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Representação textual da barra de pontuação para aqueles que usam leitores de telas\",\n      \"default\": \"Você marcou :num out de :total pontos\"\n    },\n    {\n      \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n      \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n    }\n  ]\n}'),
(1449,76,'pt','{\n  \"semantics\": [\n    {\n      \"label\": \"Editor de questão para Hotspot de Imagem\",\n      \"fields\": [\n        {\n          \"label\": \"Imagem de fundo\",\n          \"fields\": [\n            {\n              \"label\": \"Imagem de fundo\",\n              \"description\": \"Escolha uma imagem para utilizar como fundo da sua questão de hotspot de imagem.\"\n            }\n          ]\n        },\n        {\n          \"label\": \"Hotspots\",\n          \"description\": \"Arraste e large a figura desejada para o novo hotspot da barra de ferramentas. Duplo-clique sobre um hotspot existente para editar. Arraste o hotspot para o posicionar. Puxe a pega no canto inferior direito para redimensionar.\",\n          \"fields\": [\n            {\n              \"label\": \"Descrição da atividade\",\n              \"description\": \"Instruções para o utilizador.\"\n            },\n            {\n              \"label\": \"Hotspot\",\n              \"entity\": \"Hotspot\",\n              \"field\": {\n                \"label\": \"Hotspot\",\n                \"fields\": [\n                  {\n                    \"label\": \"userSettings\",\n                    \"fields\": [\n                      {\n                        \"label\": \"Correto\",\n                        \"description\": \"Podem existir múltiplos hotspots corretos. Posto isto, o utilizar recebe feedback correto/incorreto imediatamente após o primeiro clique.\"\n                      },\n                      {\n                        \"label\": \"Feedback\"\n                      }\n                    ]\n                  },\n                  {\n                    \"label\": \"computedSettings\"\n                  }\n                ]\n              }\n            },\n            {\n              \"label\": \"Feedback se o utilizador selecionar um ponto sem hotspot:\",\n              \"placeholder\": \"Hotspot não encontrado. Tente de novo!\"\n            },\n            {\n              \"label\": \"Mostrar feedback numa caixa popup\"\n            },\n            {\n              \"label\": \"Localização\",\n              \"fields\": [\n                {\n                  \"label\": \"Texto do botão de repetir\",\n                  \"default\": \"Repetir\"\n                },\n                {\n                  \"label\": \"Texto do botão de fechar\",\n                  \"default\": \"Fechar\"\n                }\n              ]\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Representação textual da barra de resultados para utilizadores de leitor de ecrã\",\n      \"default\": \"Conseguiu :num pontos de um total de :total\"\n    },\n    {\n      \"label\": \"Assistive technology description for \\\"Retry\\\" button\",\n      \"default\": \"Retry the task. Reset all responses and start the task over again.\"\n    }\n  ]\n}'),
