(1721,88,'et','{\n  \"semantics\": [\n    {\n      \"label\": \"Kirjeldus\",\n      \"description\": \"Eesmärkide hindamise lehekülje kirjeldus.\",\n      \"default\": \"Hinda eesmärgid, mis valisid eesmärkide lehel.\"\n    },\n    {\n      \"label\": \"Madala tulemuse tekst\",\n      \"description\": \"Kõige hullema tulemuse tekst.\",\n      \"default\": \"Õppisid natuke\"\n    },\n    {\n      \"label\": \"Keskmise tulemuse tekst\",\n      \"description\": \"Keskmise tulemuse tekst.\",\n      \"default\": \"Õppisid midagi\"\n    },\n    {\n      \"label\": \"Kõrge tulemuse tekst\",\n      \"description\": \"Suurepärase tulemuse tekst.\",\n      \"default\": \"Õppisid palju\"\n    },\n    {\n      \"label\": \"Ilma eesmärkideta tekst\",\n      \"description\": \"Tagasiside tekst, kui eesmärke ei ole loodud.\",\n      \"default\": \"Sa ei ole veel ühtki eesmärki valinud.\"\n    },\n    {\n      \"label\": \"Abiteksti silt\",\n      \"description\": \"Silt täiendav abistava teabe näitamiseks kasutajale.\",\n      \"default\": \"Rohkem teavet\"\n    },\n    {\n      \"label\": \"Sisesta täiendav abiteave\",\n      \"description\": \"Siin saad sisestada kasutaja jaoks täiendava abiteabe.\"\n    }\n  ]\n}'),
(1722,88,'eu','{\n  \"semantics\": [\n    {\n      \"label\": \"Deskribapena\",\n      \"description\": \"Helburuen ebaluazio orriaren deskripzioa.\",\n      \"default\": \"Kalifikatu helburuen orrian aukeratu dituzun helburuakR.\"\n    },\n    {\n      \"label\": \"Kalifikazio baxuaren testua\",\n      \"description\": \"Kalifikazio baxuenaren testua.\",\n      \"default\": \"Gutxi ikasi duzu\"\n    },\n    {\n      \"label\": \"Tarteko kalifikazioaren testua\",\n      \"description\": \"Tarteko kalifikazioaren testua.\",\n      \"default\": \"Zerbait ikasi duzu\"\n    },\n    {\n      \"label\": \"Kalifikazio altuaren testua\",\n      \"description\": \"Kalifikazio onaren testua.\",\n      \"default\": \"Pila bat ikasi duzu\"\n    },\n    {\n      \"label\": \"Helbururik ez testua\",\n      \"description\": \"Helbururik ez dagoenerako feedbacka.\",\n      \"default\": \"Oraindik ez duzu helbururik aukeratu.\"\n    },\n    {\n      \"label\": \"Laguntza testuaren etiketa\",\n      \"description\": \"Erabiltzailearentzako informazio gehigarria bistaratzeko etiketa.\",\n      \"default\": \"Informazio gehiago\"\n    },\n    {\n      \"label\": \"Osatu laguntzako informazio gehigarria\",\n      \"description\": \"Bertan zeuk osa dezakezu erabiltzailearentzat lagungarria den informazioa.\"\n    }\n  ]\n}\n'),
(1723,88,'fi','{\n  \"semantics\": [\n    {\n      \"label\": \"Kuvaus\",\n      \"description\": \"Kuvaus tai ohje tekijälle jälkiarviointiin.\",\n      \"default\": \"Arvioi tavoitesivulla valitsemasi tavoitteet.\"\n    },\n    {\n      \"label\": \"Huonoimman arvionnin teksti\",\n      \"description\": \"Teksti huonoimmalle arvioinnille.\",\n      \"default\": \"Opin vähän\"\n    },\n    {\n      \"label\": \"Keskimääräisen arvioinnin teksti\",\n      \"description\": \"Teksti keskimääräiselle arvioinnille.\",\n      \"default\": \"Opin jotain\"\n    },\n    {\n      \"label\": \"Parhaimman arvioinnin teksti\",\n      \"description\": \"Teksti parhaimmalla arvioinnille.\",\n      \"default\": \"Opin paljon\"\n    },\n    {\n      \"label\": \"Tekstiä, kun ei tavoitteita\",\n      \"description\": \"Palaute, kun yhtään tavoitetta ei ole valittu.\",\n      \"default\": \"Et ole valinnut yhtään tavoitetta vielä.\"\n    },\n    {\n      \"label\": \"Teksti osoittamaan lisätietoa\",\n      \"description\": \"Lisätietoa ilmaiseva teksti käyttäjälle.\",\n      \"default\": \"Lisää tietoa\"\n    },\n    {\n      \"label\": \"Lisätietoteksti\",\n      \"description\": \"Tähän voit täyttää tekstiä lisätietona käyttäjälle.\"\n    }\n  ]\n}'),
(1724,88,'fr','{\n  \"semantics\": [\n    {\n      \"label\": \"Description\",\n      \"description\": \"Description de la page d\'évaluation des objectifs.\",\n      \"default\": \"Evaluer les objectifs que vous avez choisis dans la page des objectifs.\"\n    },\n    {\n      \"label\": \"Texte pour une notation insuffisante\",\n      \"description\": \"Entrez ici le texte pour une notation insuffisante.\",\n      \"default\": \"Désolé, vous n\'avez pas encore assimilé suffisamment de notions, nous vous encourageons à poursuivre vos efforts.\"\n    },\n    {\n      \"label\": \"Texte pour une notation moyenne\",\n      \"description\": \"Entrez ici le texte pour une notation moyenne.\",\n      \"default\": \"Bravo pour vos efforts, vous avez acquis certaines notions, mais vous pouvez encore progresser.\"\n    },\n    {\n      \"label\": \"Texte pour une bonne notation\",\n      \"description\": \"Entrez ici le texte pour une bonne notation.\",\n      \"default\": \"Félicitations, vous avez assimilé toutes les notions.\"\n    },\n    {\n      \"label\": \"Texte quand il n\'y a aucun objectif\",\n      \"description\": \"Entrez ici le texte de feedback quand aucun objectif n\'a été défini.\",\n      \"default\": \"Vous n\'avez encore choisi aucun objectif.\"\n    },\n    {\n      \"label\": \"Titre du texte d\'aide\",\n      \"description\": \"Titre pour afficher l\'information complémentaire utile à l\'utilisateur.\",\n      \"default\": \"En savoir plus\"\n    },\n    {\n      \"label\": \"Complétez l\'information supplémentaire utile\",\n      \"description\": \"Ici vous pouvez saisir l\'information complémentaire utile pour l\'utilisateur.\"\n    }\n  ]\n}'),
(1725,88,'it','{\n  \"semantics\": [\n    {\n      \"label\": \"Descrizione\",\n      \"description\": \"Descrizione della pagina di valutazione degli obiettivi\",\n      \"default\": \"Valuta gli obiettivi che hai scelto nella pagina degli obiettivi\"\n    },\n    {\n      \"label\": \"Testo per bassa valutazione\",\n      \"description\": \"Testo per la peggior valutazione\",\n      \"default\": \"Apprendimento scarso\"\n    },\n    {\n      \"label\": \"Testo per mediocre valutazione\",\n      \"description\": \"Testo per media valutazione\",\n      \"default\": \"Apprendimento moderato\"\n    },\n    {\n      \"label\": \"Testo per alta valutazione\",\n      \"description\": \"Testo per eccezionale valutazione\",\n      \"default\": \"Apprendimento notevole\"\n    },\n    {\n      \"label\": \"Nessun obiettivo di testo\",\n      \"description\": \"Testo del feedback quando nessun obiettivo è stato creato\",\n      \"default\": \"Non hai ancora scelto nessun obiettivo\"\n    },\n    {\n      \"label\": \"Etichetta per testo di aiuto\",\n      \"description\": \"Etichetta per mostrare ulteriori informazioni di aiuto all\'utente\",\n      \"default\": \"Ulteriori informazioni\"\n    },\n    {\n      \"label\": \"Aggiungi ulteriori informazioni di aiuto\",\n      \"description\": \"Qui puoi aggiungere ulteriori informazioni di aiuto per l\'utente\"\n    }\n  ]\n}\n'),
(1726,88,'km','  \n{\n  \"semantics\": [\n    {\n      \"label\": \"Description\",\n      \"description\": \"Description of the goals assessment page.\",\n      \"default\": \"វាយតម្លៃគោលដៅដែលអ្នកបានជ្រើសរើសក្នុងទំព័រគោលដៅ។\"\n    },\n    {\n      \"label\": \"Low rating text\",\n      \"description\": \"Text for worst rating.\",\n      \"default\": \"បានរៀនតិចតួច\"\n    },\n    {\n      \"label\": \"Medium rating text\",\n      \"description\": \"Text for middle rating.\",\n      \"default\": \"បានរៀនខ្លះ\"\n    },\n    {\n      \"label\": \"High rating text\",\n      \"description\": \"Text for great rating.\",\n      \"default\": \"បានរៀនច្រើន\"\n    },\n    {\n      \"label\": \"No goals text\",\n      \"description\": \"Feedback text when no goals have been created.\",\n      \"default\": \"អ្នកមិនទាន់បានជ្រើសរើសគោលដៅណានៅឡើយទេ។\"\n    },\n    {\n      \"label\": \"Label for help text\",\n      \"description\": \"Label for showing additional helpful information to the user.\",\n      \"default\": \"ព័ត៌មានបន្ថែម\"\n    },\n    {\n      \"label\": \"Fill in additional help information\",\n      \"description\": \"Here you can fill in additional helpful information for the user.\"\n    }\n  ]\n}\n'),
(1727,88,'ko','{\n  \"semantics\": [\n    {\n      \"label\": \"설명\",\n      \"description\": \"목표 평가 페이지 설명.\",\n      \"default\": \"목표 페이지에서 선택한 목표를 평가하십시오.\"\n    },\n    {\n      \"label\": \"낮은 평가 텍스트\",\n      \"description\": \"낮은 평가 텍스트.\",\n      \"default\": \"학습이 부족합니다.\"\n    },\n    {\n      \"label\": \"평균적인 평가 텍스트\",\n      \"description\": \"평균적인 평가에 대한 텍스트.\",\n      \"default\": \"학습이 어느 정도 이루어졌습니다.\"\n    },\n    {\n      \"label\": \"높은 평가 텍스트\",\n      \"description\": \"높은 평가에 대한 텍스트.\",\n      \"default\": \"훌륭히 학습하였습니다.\"\n    },\n    {\n      \"label\": \"목표 없음 텍스트\",\n      \"description\": \"목표가 설정되지 않았을 때 피드백 텍스트.\",\n      \"default\": \"아직 어떤 목표도 선택하지 않았습니다.\"\n    },\n    {\n      \"label\": \"도움말 텍스트\",\n      \"description\": \"사용자에게 유용한 정보를 추가적으로 보여주기 위한 라벨.\",\n      \"default\": \"추가 정보\"\n    },\n    {\n      \"label\": \"추가 도움말 정보 입력\",\n      \"description\": \"여기에 사용자를 위한 추가 유용한 정보를 기입할 수 있습니다.\"\n    }\n  ]\n}\n'),
(1728,88,'nb','{\n  \"semantics\": [\n    {\n      \"label\": \"Beskrivelse av måloppnåelsessiden\",\n      \"description\": \"Beskriv aktivitetene brukeren skal gjennomføre på måloppnåelsessiden.\",\n      \"default\": \"Vurder hvilken grad av oppnåelse du har hatt på målene du valgte på målsiden.\"\n    },\n    {\n      \"label\": \"Lav måloppnåelses-tekst\",\n      \"description\": \"Tekst for verst måloppnåelse.\",\n      \"default\": \"Kan litt\"\n    },\n    {\n      \"label\": \"Middels måloppnåelses-tekst\",\n      \"description\": \"Tekst for middels måloppnåelse.\",\n      \"default\": \"Kan noe\"\n    },\n    {\n      \"label\": \"Høy måloppnåelses-tekst\",\n      \"description\": \"Tekst for høy måloppnåelse.\",\n      \"default\": \"Kan mye\"\n    },\n    {\n      \"label\": \"Ingen mål valgt tekst\",\n      \"description\": \"Tekst som vises når ingen mål har blitt satt opp på målsiden.\",\n      \"default\": \"Du har ikke valgt noen mål ennå.\"\n    },\n    {\n      \"label\": \"Tekst for \\\"Hjelpetekst\\\"-knapp\",\n      \"description\": \"Tekst som vil vises på \\\"HjelpeTekst\\\"-knapp som vil vises tilleggsinformasjon til brukeren.\",\n      \"default\": \"Mer informasjon\"\n    },\n    {\n      \"label\": \"Fyll inn tilleggsinformasjon om utførelse til brukeren\",\n      \"description\": \"Her kan du fylle inn ekstra nyttig informasjon om hvordan brukeren skal bruke denne siden.\"\n    }\n  ]\n}'),
(1729,88,'nl','{\n  \"semantics\": [\n    {\n      \"label\": \"Omschrijving\",\n      \"description\": \"Omschrijving van de beoordeling van de doelstellingenpagina\",\n      \"default\": \"Waardeer de doelstellingen die je gekozen hebt op de doelstellingenpagina.\"\n    },\n    {\n      \"label\": \"Tekst lage waardering\",\n      \"description\": \"Tekst voor de laagste waardering.\",\n      \"default\": \"Weinig geleerd\"\n    },\n    {\n      \"label\": \"Tekst gemiddelde waardering\",\n      \"description\": \"Tekst voor de gemiddelde waardering.\",\n      \"default\": \"Redelijk wat geleerd\"\n    },\n    {\n      \"label\": \"Tekst hoge waardering\",\n      \"description\": \"Tekst voor de hoogste waardering.\",\n      \"default\": \"Veel geleerd\"\n    },\n    {\n      \"label\": \"Tekst geen doelstellingen\",\n      \"description\": \"Feedback tekst als er geen doelstellingen zijn gekozen.\",\n      \"default\": \"Je hebt nog geen doelstellingen gekozen.\"\n    },\n    {\n      \"label\": \"Label voor de help tekst\",\n      \"description\": \"Label om aanvullende nuttige informatie aan de gebruiker te tonen.\",\n      \"default\": \"Meer informatie\"\n    },\n    {\n      \"label\": \"Vul aanvullende help informatie in\",\n      \"description\": \"Hier kun je aanvullende nuttige informatie invullen voor de gebruiker.\"\n    }\n  ]\n}'),
(1730,88,'nn','{\n  \"semantics\": [\n    {\n      \"label\": \"Skildring av sida med måloppnåing\",\n      \"description\": \"Skildre aktivitetane brukaren skal gjennomføre på sida for måloppnåing.\",\n      \"default\": \"Vurder kva grad av oppnåing du har hatt på måla du valde på målsida.\"\n    },\n    {\n      \"label\": \"Låg måloppnåings-tekst\",\n      \"description\": \"Tekst for verst måloppnåing.\",\n      \"default\": \"Kan litt\"\n    },\n    {\n      \"label\": \"Middels måloppnåelses-tekst\",\n      \"description\": \"Tekst for middels måloppnåing.\",\n      \"default\": \"Kan noko\"\n    },\n    {\n      \"label\": \"Høg måloppnåings-tekst\",\n      \"description\": \"Tekst for høg måloppnåing.\",\n      \"default\": \"Kan mykje\"\n    },\n    {\n      \"label\": \"Ingen mål vald tekst\",\n      \"description\": \"Tekst som vert vist om ingen mål har blitt satt opp på målsida.\",\n      \"default\": \"Du har ikkje valgt mål enno.\"\n    },\n    {\n      \"label\": \"Tekst for \\\"Hjelpetekst\\\"-knapp\",\n      \"description\": \"Tekst som vil visast på \\\"HjelpeTekst\\\"-knapp som vil visa tilleggs-infomasjon til brukaren.\",\n      \"default\": \"Meir informasjon\"\n    },\n    {\n      \"label\": \"Fyll inn tilleggsinformasjon om utføring til brukaren\",\n      \"description\": \"Her kan du fylla inn ekstra nyttig informasjon om korleis brukaren skal nytte denne sida.\"\n    }\n  ]\n}'),
(1731,88,'pt-br','{\n  \"semantics\": [\n    {\n      \"label\": \"Descrição\",\n      \"description\": \"Descrição da página de avaliação de objetivos.\",\n      \"default\": \"Avalie os objetivos que você escolheu na página de objetivos.\"\n    },\n    {\n      \"label\": \"Texto para classificação baixa\",\n      \"description\": \"Texto para a pior classificação.\",\n      \"default\": \"Aprendi pouco\"\n    },\n    {\n      \"label\": \"Texto para classificação mediana\",\n      \"description\": \"Texto para classificação mediana.\",\n      \"default\": \"Aprendi algumas coisas\"\n    },\n    {\n      \"label\": \"Texto para classificação alta\",\n      \"description\": \"Texto para ótima classificação.\",\n      \"default\": \"Aprendi muito\"\n    },\n    {\n      \"label\": \"Texto para nenhum objetivo\",\n      \"description\": \"Texto de feedback para quando nenhum objetivo tiver sido criado.\",\n      \"default\": \"Você ainda não escolheu nenhum objetivo.\"\n    },\n    {\n      \"label\": \"Texto do rótulo de ajuda\",\n      \"description\": \"Rótulo para mostrar informações úteis adicionas ao usuário.\",\n      \"default\": \"Mias informações\"\n    },\n    {\n      \"label\": \"Preencha as informações adicionais de ajuda\",\n      \"description\": \"Aqui você pode inserir informações úteis adicionais para o usuário.\"\n    }\n  ]\n}\n'),
(1732,88,'sl','{\n  \"semantics\": [\n    {\n      \"label\": \"Opis\",\n      \"description\": \"Navodilo udeležencem za delo na strani za vrednotenje ciljev.\",\n      \"default\": \"Ovrednoti dodane cilje.\"\n    },\n    {\n      \"label\": \"Najnižja ocena cilja\",\n      \"description\": \"Besedilo za vrednotenje najnižje ocene.\",\n      \"default\": \"Ni doseženo\"\n    },\n    {\n      \"label\": \"Srednja ocena cilja\",\n      \"description\": \"Besedilo za vrednotenje srednje ocene.\",\n      \"default\": \"Delno doseženo\"\n    },\n    {\n      \"label\": \"Najvišja ocena cilja\",\n      \"description\": \"Besedilo za vrednotenje najvišje ocene.\",\n      \"default\": \"Doseženo\"\n    },\n    {\n      \"label\": \"Ni ciljev\",\n      \"description\": \"Besedilo za povratne informacije udeležencu, ko cilji nisi bili ustvarjeni.\",\n      \"default\": \"Ni izbranih ciljev.\"\n    },\n    {\n      \"label\": \"Naslov za dodatne informacije\",\n      \"description\": \"Besedilo se prikaže kot povezava, ki vodi do dodatnih informacij za udeležence.\",\n      \"default\": \"Več informacij\"\n    },\n    {\n      \"label\": \"Vsebina dodatnih informacij\",\n      \"description\": \"Besedilo se udeležencem prikaže v pogovornem oknu.\"\n    }\n  ]\n}\n'),
