(1871,92,'sr','{\n  \"semantics\": [\n    {\n      \"widgets\": [\n        {\n          \"label\": \"Уобичајено\"\n        }\n      ],\n      \"label\": \"Картице\",\n      \"entity\": \"card\",\n      \"field\": {\n        \"label\": \"Картица\",\n        \"fields\": [\n          {\n            \"label\": \"Слика\"\n          },\n          {\n            \"label\": \"Алтернативни текст за слику\",\n            \"description\": \"Опишите шта се може видети на фотографији. Текст читају алати за претварање текста у говор који су потребни корисницима са оштећеним видом.\"\n          },\n          {\n            \"label\": \"Аудио запис\",\n            \"description\": \"Опционални звук који се чује када се картица окрене.\"\n          },\n          {\n            \"label\": \"Упарене слике\",\n            \"description\": \"Опционална слика за упоређивање уместо да користите две картице са истом сликом.\"\n          },\n          {\n            \"label\": \"Алтернативни текст за подударање слике\",\n            \"description\": \"пишите шта се може видети на фотографији. Текст читају алати за претварање текста у говор који су потребни корисницима са оштећеним видом.\"\n          },\n          {\n            \"label\": \"Подударање аудио записа\",\n            \"description\": \"Опционални звук који се чује када се окрене друга карта.\"\n          },\n          {\n            \"label\": \"Опис\",\n            \"description\": \"Необавезни кратак текст који ће се појавити када се пронађу две одговарајуће картице.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Поставке понашања\",\n      \"description\": \"Ове опције ће вам омогућити да контролишете понашање игре.\",\n      \"fields\": [\n        {\n          \"label\": \"Позиција карте у квадрат\",\n          \"description\": \"Покушаће да усклади број колона и редова приликом полагања карата. Након тога, картице ће се скалирати тако да одговарају контејнеру.\"\n        },\n        {\n          \"label\": \"Број карата које треба користити\",\n          \"description\": \"Ако ово поставите на број већи од 2, игра ће изабрати случајне карте са листе карата.\"\n        },\n        {\n          \"label\": \"Додај дугме за поновни покушај када се игра заврши\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Погледај и осети\",\n      \"description\": \"Контролишите визуелне елементе игре.\",\n      \"fields\": [\n        {\n          \"label\": \"Боја теме\",\n          \"description\": \"Одаберите боју да бисте креирали тему за своју игру.\"\n        },\n        {\n          \"label\": \"Полеђина карте\",\n          \"description\": \"Користите прилагођену полеђину за картице.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Локализација\",\n      \"fields\": [\n        {\n          \"label\": \"Текст окрета картице\",\n          \"default\": \"Окретање карата\"\n        },\n        {\n          \"label\": \"Текст утрошеног времена\",\n          \"default\": \"Утрошено време\"\n        },\n        {\n          \"label\": \"Текст повратне информације\",\n          \"default\": \"Одлично!\"\n        },\n        {\n          \"label\": \"Текст дугмета Покушај поново\",\n          \"default\": \"Покушај поново?\"\n        },\n        {\n          \"label\": \"Наслов дугмета Затвори\",\n          \"default\": \"Затвори\"\n        },\n        {\n          \"label\": \"Наслов Игре\",\n          \"default\": \"Игра Меморија\"\n        },\n        {\n          \"label\": \"Game instructions\",\n          \"default\": \"Use arrow keys left and right to navigate cards. Use space or enter key to turn card.\"\n        },\n        {\n          \"label\": \"Текст завршетка игре\",\n          \"default\": \"Све карте су пронађене.\"\n        },\n        {\n          \"label\": \"Ознака за индексирање картица\",\n          \"description\": \"%num and %total are placeholders and will be replaced with the respective values for the card.\",\n          \"default\": \"Картица %num од %total:\"\n        },\n        {\n          \"label\": \"Наслов Неокренуте картице\",\n          \"default\": \"Неокренуте. Click to turn.\"\n        },\n        {\n          \"label\": \"Card turned label\",\n          \"default\": \"Turned.\"\n        },\n        {\n          \"label\": \"Наслов Картице се подударају\",\n          \"default\": \"Подударају се картице.\"\n        },\n        {\n          \"label\": \"Card matched announcement\",\n          \"default\": \"Your cards match!\"\n        },\n        {\n          \"label\": \"Card not matched announcement\",\n          \"default\": \"Your chosen cards do not match. Turn other cards to try again.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(1872,92,'sv','{\n  \"semantics\": [\n    {\n      \"widgets\": [\n        {\n          \"label\": \"Default\"\n        }\n      ],\n      \"label\": \"Kort\",\n      \"entity\": \"kort\",\n      \"field\": {\n        \"label\": \"Kort\",\n        \"fields\": [\n          {\n            \"label\": \"Image\"\n          },\n          {\n            \"label\": \"Alternativ text för bild\",\n            \"description\": \"Beskriv vad bilden föreställer. Texten används av tillgänglighetshjälpmedel.\"\n          },\n          {\n            \"label\": \"Ljudspår\",\n            \"description\": \"Ett valfritt ljud som spelas upp när kortet vänds.\"\n          },\n          {\n            \"label\": \"Matchande bild\",\n            \"description\": \"En valfri bild som matchar, istället för att använda två kort med samma bild.\"\n          },\n          {\n            \"label\": \"Alternativ text för matchande bild\",\n            \"description\": \"Beskriv vad som finns i bilden. Används av tillgänglighetshjälpmedel.\"\n          },\n          {\n            \"label\": \"Matchande ljudspår\",\n            \"description\": \"Ett valfritt ljud som spelas upp när det andra kortet vänds.\"\n          },\n          {\n            \"label\": \"Description\",\n            \"description\": \"En valfri kort text som poppar upp när två matchande kort hittas.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Beteende-inställningar\",\n      \"description\": \"Dessa inställningar avgör hur spelet beter sig.\",\n      \"fields\": [\n        {\n          \"label\": \"Positionera korten kvadratiskt\",\n          \"description\": \"Kommer försöka matcha antalet kolumner och rader när korten placeras ut. Efteråt, så kommer korten att skalas för att passa in i behållaren.\"\n        },\n        {\n          \"label\": \"Antal kort att använda\",\n          \"description\": \"Om du väljer ett större tal än 2, så väljs kort slumpmässigt från listan över kort.\"\n        },\n        {\n          \"label\": \"Lägg till knapp för att försöka igen, när spelet är slut\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Utseende\",\n      \"description\": \"Ställ in hur spelet ska se ut.\",\n      \"fields\": [\n        {\n          \"label\": \"Theme Color\",\n          \"description\": \"Välj en färg för att skapa ett tema för ditt kortspel.\"\n        },\n        {\n          \"label\": \"Baksida på kort\",\n          \"description\": \"Använd en anpassad baksida på dina kort.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Lokalisering\",\n      \"fields\": [\n        {\n          \"label\": \"Text när kort vänds\",\n          \"default\": \"Kort du har vänt\"\n        },\n        {\n          \"label\": \"Text för förbrukad tid\",\n          \"default\": \"Tid förbrukad\"\n        },\n        {\n          \"label\": \"Feedbacktext\",\n          \"default\": \"Bra jobbat!\"\n        },\n        {\n          \"label\": \"Knapptext för Försök igen\",\n          \"default\": \"Försök igen?\"\n        },\n        {\n          \"label\": \"Knapptext för Stäng\",\n          \"default\": \"Stäng\"\n        },\n        {\n          \"label\": \"Speletikett\",\n          \"default\": \"Memory-spel. Hitta de matchande korten.\"\n        },\n        {\n          \"label\": \"Text för Spel avslutat\",\n          \"default\": \"Alla korten har hittats.\"\n        },\n        {\n          \"label\": \"Text för kort-indexering\",\n          \"default\": \"Kort %num:\"\n        },\n        {\n          \"label\": \"Text för Ej vänt kort\",\n          \"description\": \"%num and %total are placeholders and will be replaced with the respective values for the card.\",\n          \"default\": \"Ej vänt.\"\n        },\n        {\n          \"label\": \"Text för matchande kort\",\n          \"default\": \"Matchning hittad.\"\n        },\n        {\n          \"label\": \"Card turned label\",\n          \"default\": \"Turned.\"\n        },\n        {\n          \"label\": \"Card matched label\",\n          \"default\": \"Match found.\"\n        },\n        {\n          \"label\": \"Card matched announcement\",\n          \"default\": \"Your cards match!\"\n        },\n        {\n          \"label\": \"Card not matched announcement\",\n          \"default\": \"Your chosen cards do not match. Turn other cards to try again.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(1873,92,'sw','{\n  \"semantics\": [\n    {\n      \"widgets\": [\n        {\n          \"label\": \"Chaguo-msingi\"\n        }\n      ],\n      \"label\": \"Kadi\",\n      \"entity\": \"kadi\",\n      \"field\": {\n        \"label\": \"Kadi\",\n        \"fields\": [\n          {\n            \"label\": \"Picha\"\n          },\n          {\n            \"label\": \"Maandishi mbadala ya picha\",\n            \"description\": \"Eleza kinachoweza kuonekana kwenye picha. Maandishi yanasomwa kutumia zana za kubadilisha maandishi-hadi-hotuba zinazohitajika na watumiaji wenye matatizo ya kuona.\"\n          },\n          {\n            \"label\": \"Wimbo wa Sauti\",\n            \"description\": \"Sauti ya hiari inayocheza kadi inapowashwa.\"\n          },\n          {\n            \"label\": \"Picha inayolingana\",\n            \"description\": \"Picha ya hiari ya kulinganisha dhidi yake badala ya kutumia kadi mbili zilizo na picha sawa.\"\n          },\n          {\n            \"label\": \"Maandishi mbadala ya picha inayolingana\",\n            \"description\": \"Eleza kinachoweza kuonekana kwenye picha. Maandishi yanasomwa kutumia zana za kubadilisha maandishi-hadi-hotuba zinazohitajika na watumiaji wenye matatizo ya kuona.\"\n          },\n          {\n            \"label\": \"Wimbo wa sauti inayolingana\",\n            \"description\": \"Sauti ya hiari inayocheza kadi ya pili inapowashwa.\"\n          },\n          {\n            \"label\": \"Maelezo\",\n            \"description\": \"Maandishi mafupi ya hiari yatakayotokea wakati kadi mbili zinazolingana zitakapopatikana.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Mipangilio ya tabia\",\n      \"description\": \"Chaguzi hizi zitakuwezesha kudhibiti jinsi mchezo unavyofanya.\",\n      \"fields\": [\n        {\n          \"label\": \"Weka kadi katika mpangilio wa mraba\",\n          \"description\": \"Itajaribu kulinganisha idadi ya safu wima na safu mlalo wakati wa kuweka kadi. Baadaye, kadi zitapimwa ili kutoshea chombo.\"\n        },\n        {\n          \"label\": \"Idadi ya kadi za kutumia\",\n          \"description\": \"Kuweka nambari hii kuwa kubwa kuliko 2 kutafanya mchezo kuchagua kadi kibahati nasibu kutoka kwenye orodha ya kadi.\"\n        },\n        {\n          \"label\": \"Ongeza kitufe cha jaribu tena mchezo unapokwisha\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Tazama na uhisi\",\n      \"description\": \"Thibiti taswira za mchezo.\",\n      \"fields\": [\n        {\n          \"label\": \"Rangi ya mandhari\",\n          \"description\": \"Chagua rangi ili kuunda mandhari ya mchezo wa kadi yako.\"\n        },\n        {\n          \"label\": \"Kadi Nyuma\",\n          \"description\": \"Tumia urejeshi maalum kwa kadi zako.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Ujanibishaji\",\n      \"fields\": [\n        {\n          \"label\": \"Kadi hubadilisha maandishi\",\n          \"default\": \"Kadi hubadilisha\"\n        },\n        {\n          \"label\": \"Muda uliotumika kwa maandishi\",\n          \"default\": \"Muda uliotumika\"\n        },\n        {\n          \"label\": \"Maandishi ya maoni\",\n          \"default\": \"Kazi nzuri!\"\n        },\n        {\n          \"label\": \"Maandishi ya kitufe cha jaribu tena\",\n          \"default\": \"Jaribu tena?\"\n        },\n        {\n          \"label\": \"Lebo ya kitufe cha kufunga\",\n          \"default\": \"Funga\"\n        },\n        {\n          \"label\": \"Lebo ya mchezo\",\n          \"default\": \"Mchezo wa Kumbukizi. Tafuta kadi zinazolingana.\"\n        },\n        {\n          \"label\": \"Game instructions\",\n          \"default\": \"Use arrow keys left and right to navigate cards. Use space or enter key to turn card.\"\n        },\n        {\n          \"label\": \"Lebo ya mchezo umekwisha\",\n          \"default\": \"Kadi zote zimepatikana.\"\n        },\n        {\n          \"label\": \"Lebo ya kuorodhesha kadi\",\n          \"description\": \"%num and %total are placeholders and will be replaced with the respective values for the card.\",\n          \"default\": \"Kadi %num/%total:\"\n        },\n        {\n          \"label\": \"Lebo ya kadi ambayo haijageuzwa\",\n          \"default\": \"Haijageuzwa. Click to turn.\"\n        },\n        {\n          \"label\": \"Card turned label\",\n          \"default\": \"Turned.\"\n        },\n        {\n          \"label\": \"Lebo inayolingana na kadi\",\n          \"default\": \"Inayolingana imepatikana.\"\n        },\n        {\n          \"label\": \"Card matched announcement\",\n          \"default\": \"Your cards match!\"\n        },\n        {\n          \"label\": \"Card not matched announcement\",\n          \"default\": \"Your chosen cards do not match. Turn other cards to try again.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(1874,92,'th','{\n  \"semantics\": [\n    {\n      \"widgets\": [\n        {\n          \"label\": \"ค่าเริ่มต้น\"\n        }\n      ],\n      \"label\": \"การ์ด\",\n      \"entity\": \"card\",\n      \"field\": {\n        \"label\": \"การ์ด\",\n        \"fields\": [\n          {\n            \"label\": \"รูปภาพ\"\n          },\n          {\n            \"label\": \"ข้อความสำหรับรูปภาพทางเลือก\",\n            \"description\": \"อธิบายสิ่งที่เห็นในรูปภาพ เป็นข้อความที่อ่านโดยเครื่องมือ Text-to-Speech ที่ใช้โดยผู้ใช้ที่มีปัญหาทางสายตา\"\n          },\n          {\n            \"label\": \"เสียงติดตาม\",\n            \"description\": \"เสียงที่เล่นเมื่อเปิดการ์ด\"\n          },\n          {\n            \"label\": \"รูปภาพที่ใช้ในการจับคู่\",\n            \"description\": \"รูปภาพทางเลือกที่ใช้ในการจับคู่แทนการใช้การ์ดสองใบที่มีรูปภาพเดียวกัน\"\n          },\n          {\n            \"label\": \"ข้อความสำหรับรูปภาพที่ใช้ในการจับคู่\",\n            \"description\": \"อธิบายสิ่งที่เห็นในรูปภาพ เป็นข้อความที่อ่านโดยเครื่องมือ Text-to-Speech ที่ใช้โดยผู้ใช้ที่มีปัญหาทางสายตา\"\n          },\n          {\n            \"label\": \"เสียงติดตามที่ใช้ในการจับคู่\",\n            \"description\": \"เสียงที่เล่นเมื่อเปิดการ์ดคู่ที่สอง\"\n          },\n          {\n            \"label\": \"คำอธิบาย\",\n            \"description\": \"ข้อความสั้นที่จะปรากฏขึ้นเมื่อค้นพบการ์ดที่จับคู่\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"การตั้งค่าพฤติกรรม\",\n      \"description\": \"ตัวเลือกเหล่านี้จะช่วยคุมพฤติกรรมของเกม\",\n      \"fields\": [\n        {\n          \"label\": \"จัดตำแหน่งการ์ดในรูปสี่เหลี่ยม\",\n          \"description\": \"จะพยายามจับจำนวนคอลัมน์และแถวเมื่อจัดการ์ด หลังจากนั้นการ์ดจะถูกปรับขนาดให้พอดีกับคอนเทนเนอร์\"\n        },\n        {\n          \"label\": \"จำนวนการ์ดที่ใช้\",\n          \"description\": \"ตั้งค่าเป็นจำนวนมากกว่า 2 จะทำให้เกมเลือกการ์ดแบบสุ่มจากรายการการ์ด\"\n        },\n        {\n          \"label\": \"เพิ่มปุ่มสำหรับลองใหม่เมื่อเกมสิ้นสุดลง\"\n        }\n      ]\n    },\n    {\n      \"label\": \"การมองเห็นและการรับรู้\",\n      \"description\": \"ควบคุมการแสดงผลของเกม\",\n      \"fields\": [\n        {\n          \"label\": \"สีธีม\",\n          \"description\": \"เลือกสีเพื่อสร้างธีมสำหรับเกมการ์ดของคุณ\"\n        },\n        {\n          \"label\": \"หลังการ์ด\",\n          \"description\": \"ใช้หลังการ์ดที่กำหนดเองสำหรับการ์ดของคุณ\"\n        }\n      ]\n    },\n    {\n      \"label\": \"การแปลภาษา\",\n      \"fields\": [\n        {\n          \"label\": \"ข้อความการเปลี่ยนการ์ด\",\n          \"default\": \"การ์ดที่เปลี่ยน\"\n        },\n        {\n          \"label\": \"ข้อความเวลาที่ใช้\",\n          \"default\": \"เวลาที่ใช้\"\n        },\n        {\n          \"label\": \"ข้อความผลตอบรับ\",\n          \"default\": \"งานดี!\"\n        },\n        {\n          \"label\": \"ข้อความปุ่มลองใหม่\",\n          \"default\": \"ลองอีกครั้ง?\"\n        },\n        {\n          \"label\": \"ป้ายปุ่มปิด\",\n          \"default\": \"ปิด\"\n        },\n        {\n          \"label\": \"ป้ายเกม\",\n          \"default\": \"เกมเมมโมรี: ค้นหาการ์ดที่จับคู่กัน\"\n        },\n        {\n          \"label\": \"คำแนะนำเกม\",\n          \"default\": \"ใช้ปุ่มลูกศรซ้ายและขวาเพื่อนำทางการ์ด ใช้ปุ่มสเปซหรือปุ่มเอ็นเตอร์เพื่อเปิดการ์ด\"\n        },\n        {\n          \"label\": \"ป้ายเกมเสร็จสิ้น\",\n          \"default\": \"ค้นพบการ์ดทั้งหมดแล้ว\"\n        },\n        {\n          \"label\": \"ป้ายดัชนีการ์ด\",\n          \"description\": \"%num และ %total เป็นตัวยึดสถานะและจะถูกแทนที่ด้วยค่าที่เกี่ยวข้องสำหรับการ์ด\",\n          \"default\": \"การ์ดที่ %num จากทั้งหมด:\"\n        },\n        {\n          \"label\": \"ป้ายการ์ดที่ยังไม่เปิด\",\n          \"default\": \"ยังไม่เปิด คลิกเพื่อเปิด\"\n        },\n        {\n          \"label\": \"ป้ายการ์ดที่เปิด\",\n          \"default\": \"เปิดแล้ว\"\n        },\n        {\n          \"label\": \"ป้ายการ์ดที่จับคู่\",\n          \"default\": \"พบการจับคู่\"\n        },\n        {\n          \"label\": \"ประกาศการ์ดที่จับคู่\",\n          \"default\": \"การ์ดของคุณตรงกัน!\"\n        },\n        {\n          \"label\": \"ประกาศการ์ดที่ไม่ตรงกัน\",\n          \"default\": \"การ์ดที่คุณเลือกไม่ตรงกัน ลองเปิดการ์ดอื่นเพื่อลองอีกครั้ง\"\n        }\n      ]\n    }\n  ]\n}\n'),
(1875,92,'tr','{\n  \"semantics\": [\n    {\n      \"widgets\": [\n        {\n          \"label\": \"Varsayılan\"\n        }\n      ],\n      \"label\": \"Kartlar\",\n      \"entity\": \"kart\",\n      \"field\": {\n        \"label\": \"kart\",\n        \"fields\": [\n          {\n            \"label\": \"Resim\"\n          },\n          {\n            \"label\": \"Resim için alt metin\",\n            \"description\": \"Resimde neler göründüğünü açıklayın. Alt  metin, görme engelli kullanıcıların resim için ihtiyaç duyduğu açıklamadır. Yardımcı teknolojiler ile okunur.\"\n          },\n          {\n            \"label\": \"Müzik Parçası\",\n            \"description\": \"Kart döndürüldüğünde çalınması istenen ses (isteğe bağlı).\"\n          },\n          {\n            \"label\": \"Eşleştirilen Resim\",\n            \"description\": \"Aynı görüntüye sahip iki kart kullanmak yerine eşleştirilecek farklı bir resim seçebilirsiniz (isteğe bağlı).\"\n          },\n          {\n            \"label\": \"Eşleştirilen resim için alt metin\",\n            \"description\": \"Resimde neler göründüğünü açıklayın. Alt  metin, görme engelli kullanıcıların resim için ihtiyaç duyduğu açıklamadır. Yardımcı teknolojiler ile okunur.\"\n          },\n          {\n            \"label\": \"Eşleştirilen için müzik parçası\",\n            \"description\": \"İkinci kart döndürüldüğünde çalınması istenen ses (isteğe bağlı).\"\n          },\n          {\n            \"label\": \"Açıklama\",\n            \"description\": \"Kartlar eşleştiğinde açılır kutuda kısa metin (isteğe bağlı).\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Etkinlik ayarları\",\n      \"description\": \"Bu seçenekler aktivitenin çalışma şeklini denetlemenize izin verir.\",\n      \"fields\": [\n        {\n          \"label\": \"Kartları kare şeklinde yerleştirin.\",\n          \"description\": \"Kartları yerleştirirken satır ve sütun sayısını eşitlenmeye çalışılacaktır. Daha sonra kartlar çerçeveye sığacak şekilde ölçeklendirilecektir.\"\n        },\n        {\n          \"label\": \"Kullanılacak kart sayısı\",\n          \"description\": \"İkiden büyük bir sayı girerek, oyunda kart havuzundan belirttiğiniz sayıda rastgele kartlar kullanabilirsiniz.\"\n        },\n        {\n          \"label\": \"Oyun bittiğinde yeniden başlatmak için bir buton ekleyin\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Görünüm ve doku\",\n      \"description\": \"Oyunun görselliğini değiştirin.\",\n      \"fields\": [\n        {\n          \"label\": \"Tema rengi\",\n          \"description\": \"Kart oyunu teması için bir renk seçiniz.\"\n        },\n        {\n          \"label\": \"Kart Görünümü\",\n          \"description\": \"Kart arkası için bir görünüm seçin.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Yerelleştirme\",\n      \"fields\": [\n        {\n          \"label\": \"Kart döndürme metni\",\n          \"default\": \"Kart dönüşleri\"\n        },\n        {\n          \"label\": \"Geçen süre metni\",\n          \"default\": \"Geçen süre\"\n        },\n        {\n          \"label\": \"Geri bildirim meni\",\n          \"default\": \"İyi oyundu!\"\n        },\n        {\n          \"label\": \"Tekrar\",\n          \"default\": \"Tekrar denemek ister misiniz?\"\n        },\n        {\n          \"label\": \"Kapatma butonu etiketi\",\n          \"default\": \"Kapat\"\n        },\n        {\n          \"label\": \"Oyun Başlığı\",\n          \"default\": \"Hazfıza oyunu. Kartları eşleştirin.\"\n        },\n        {\n          \"label\": \"Game instructions\",\n          \"default\": \"Use arrow keys left and right to navigate cards. Use space or enter key to turn card.\"\n        },\n        {\n          \"label\": \"Oyun bitti etiketi\",\n          \"default\": \"Tüm kartlar eşleştirildi.\"\n        },\n        {\n          \"label\": \"Kart sıra etiketi\",\n          \"description\": \"%num and %total are placeholders and will be replaced with the respective values for the card.\",\n          \"default\": \"Kart %num/%total:\"\n        },\n        {\n          \"label\": \"Kart döndürülmemiş etiketi\",\n          \"default\": \"Döndürülmedi. Click to turn.\"\n        },\n        {\n          \"label\": \"Card turned label\",\n          \"default\": \"Turned.\"\n        },\n        {\n          \"label\": \"Kart eşleşme etiketi\",\n          \"default\": \"Eşleştirildi.\"\n        },\n        {\n          \"label\": \"Card matched announcement\",\n          \"default\": \"Your cards match!\"\n        },\n        {\n          \"label\": \"Card not matched announcement\",\n          \"default\": \"Your chosen cards do not match. Turn other cards to try again.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(1876,92,'uk','{\n  \"semantics\": [\n    {\n      \"widgets\": [\n        {\n          \"label\": \"По умовчанню\"\n        }\n      ],\n      \"label\": \"Карточки\",\n      \"entity\": \"карточка\",\n      \"field\": {\n        \"label\": \"Карточка\",\n        \"fields\": [\n          {\n            \"label\": \"Зображення\"\n          },\n          {\n            \"label\": \"Альтернативний текст для зображення\",\n            \"description\": \"Опишіть, що видно на фото. Текст читаеться за допомогою інструментів перетворення тексту в мову, необхідну користувачам з порушенням зору.\"\n          },\n          {\n            \"label\": \"Звукова доріжка\",\n            \"description\": \"Додатковий звук, який відтворюється при повороті карточки.\"\n          },\n          {\n            \"label\": \"Відповідне зображення\",\n            \"description\": \"Необов\'язкове зображення для співставлення замість використання двох карточок з однаковими зображеннями.\"\n          },\n          {\n            \"label\": \"Альтернативний текст для відповідного зображення\",\n            \"description\": \"Опишіть, що видно на фото. Текст читаеться за допомогою інструментів перетворення тексту в мову, необхідну користувачам з порушенням зору.\"\n          },\n          {\n            \"label\": \"Відповідна звукова доріжка\",\n            \"description\": \"Додатковий звук, який відтворюється при повороті карточки.\"\n          },\n          {\n            \"label\": \"Опис\",\n            \"description\": \"Додатковий короткий текст, який появиться після того, як знайдено дві відповідні карточки.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Настройки поведінки\",\n      \"description\": \"Ці параметри дозволять вам контролювати поведінку гри.\",\n      \"fields\": [\n        {\n          \"label\": \"Розміщення карточки на площадці\",\n          \"description\": \"Постарайтеся співставити кількість стовпчиків і рядків при разкладанні карточок. Після чого карточки будуть масштабуватися до разміру контейнера.\"\n        },\n        {\n          \"label\": \"Кількість карточок для використання\",\n          \"description\": \"Якщо встановити значення більше 2, гра будет обирати випадкові карточки із списку.\"\n        },\n        {\n          \"label\": \"Добавити кнопку для повтору, коли гра закінчена\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Дивитися і відчувати\",\n      \"description\": \"Керування візуальними ефектами гри.\",\n      \"fields\": [\n        {\n          \"label\": \"Колір теми\",\n          \"description\": \"Оберіть колір, щоб створити тему для своеї карточної гри.\"\n        },\n        {\n          \"label\": \"Зворотня сторона карточки\",\n          \"description\": \"Використання довільної сорочки для своїх карточок.\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Локалізація\",\n      \"fields\": [\n        {\n          \"label\": \"Текст перевернутої карточки\",\n          \"default\": \"Карточка перевернута\"\n        },\n        {\n          \"label\": \"Текст витраченого часу\",\n          \"default\": \"Витречено часу\"\n        },\n        {\n          \"label\": \"Текст зворотнього зв\'зку\",\n          \"default\": \"Гарна робота!\"\n        },\n        {\n          \"label\": \"Текст кнопки повтору\",\n          \"default\": \"Спробувати ще раз?\"\n        },\n        {\n          \"label\": \"Надпис кнопки закриття\",\n          \"default\": \"Закрить\"\n        },\n        {\n          \"label\": \"Надпис гри\",\n          \"default\": \"Гра на запам\'ятовування. Знайди відповідні карточки.\"\n        },\n        {\n          \"label\": \"Game instructions\",\n          \"default\": \"Use arrow keys left and right to navigate cards. Use space or enter key to turn card.\"\n        },\n        {\n          \"label\": \"Надпис завершення гри\",\n          \"default\": \"Всі карточки були знайдені.\"\n        },\n        {\n          \"label\": \"Надпис номера карточки\",\n          \"description\": \"%num and %total are placeholders and will be replaced with the respective values for the card.\",\n          \"default\": \"Карточка %num/%total:\"\n        },\n        {\n          \"label\": \"Надпис неперевернутої карточки\",\n          \"default\": \"Неперевернута. Click to turn.\"\n        },\n        {\n          \"label\": \"Card turned label\",\n          \"default\": \"Turned.\"\n        },\n        {\n          \"label\": \"Надпис відповідної карточки\",\n          \"default\": \"Відповідність знайдено.\"\n        },\n        {\n          \"label\": \"Card matched announcement\",\n          \"default\": \"Your cards match!\"\n        },\n        {\n          \"label\": \"Card not matched announcement\",\n          \"default\": \"Your chosen cards do not match. Turn other cards to try again.\"\n        }\n      ]\n    }\n  ]\n}\n'),
(1877,92,'vi','{\n  \"semantics\": [\n    {\n      \"widgets\": [\n        {\n          \"label\": \"Default\"\n        }\n      ],\n      \"label\": \"Cards\",\n      \"entity\": \"card\",\n      \"field\": {\n        \"label\": \"Card\",\n        \"fields\": [\n          {\n            \"label\": \"Image\"\n          },\n          {\n            \"label\": \"Alternative text for Image\",\n            \"description\": \"Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users.\"\n          },\n          {\n            \"label\": \"Audio Track\",\n            \"description\": \"An optional sound that plays when the card is turned.\"\n          },\n          {\n            \"label\": \"Matching Image\",\n            \"description\": \"An optional image to match against instead of using two cards with the same image.\"\n          },\n          {\n            \"label\": \"Alternative text for Matching Image\",\n            \"description\": \"Describe what can be seen in the photo. The text is read by text-to-speech tools needed by visually impaired users.\"\n          },\n          {\n            \"label\": \"Matching Audio Track\",\n            \"description\": \"An optional sound that plays when the second card is turned.\"\n          },\n          {\n            \"label\": \"Description\",\n            \"description\": \"An optional short text that will pop up once the two matching cards are found.\"\n          }\n        ]\n      }\n    },\n    {\n      \"label\": \"Behavioural settings\",\n      \"description\": \"These options will let you control how the game behaves.\",\n      \"fields\": [\n        {\n          \"label\": \"Position the cards in a square\",\n          \"description\": \"Will try to match the number of columns and rows when laying out the cards. Afterward, the cards will be scaled to fit the container.\"\n        },\n        {\n          \"label\": \"Number of cards to use\",\n          