(1931,94,'et','{\n  \"semantics\": [\n    {\n      \"label\": \"Sisendvälja kirjeldus\",\n      \"description\": \"Kasutajalt oodatava sisendi kirjeldus.\"\n    },\n    {\n      \"label\": \"Kohahoidja tekst\",\n      \"description\": \"Kohahoidja tekst kasutaja jaoks.\"\n    },\n    {\n      \"label\": \"Suurim tekstipikkus\",\n      \"description\": \"Teksti suurim märkide hulk.\"\n    },\n    {\n      \"label\": \"Sisendvälja suurus\",\n      \"description\": \"Sisendvälja suurus ridades.\",\n      \"options\": [\n        {\n          \"label\": \"1 rida\"\n        },\n        {\n          \"label\": \"3 rida\"\n        },\n        {\n          \"label\": \"10 rida\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Nõutud väli\",\n      \"description\": \"Märgi, et muuta väli nõutud väljaks - kasutaja peab dokumendi eksportimiseks vastama kõik nõutud väljad selleks.\"\n    },\n    {\n      \"label\": \"Allesjäänud märke\",\n      \"default\": \"Allesjäänud märke: @chars\",\n      \"description\": \"Allesjäänud märkide arvu teade. Kasutada saab muutujat @chars, mis asendatakse vastava arvuga.\"\n    }\n  ]\n}'),
(1932,94,'eu','{\n  \"semantics\": [\n    {\n      \"label\": \"Sarrera-eremuaren deskribapena\",\n      \"description\": \"Erabiltzaileak idatzi beharrekoaren deskribapena.\"\n    },\n    {\n      \"label\": \"Leku-markaren testua\",\n      \"description\": \"Erabiltzailearentzako kokapen-testua.\"\n    },\n    {\n      \"label\": \"Testuaren gehienezko luzera\",\n      \"description\": \"Testuaren gehienezko karaktere-kopurua.\"\n    },\n    {\n      \"label\": \"Sarrera-eremuaren tamaina\",\n      \"description\": \"Testuak bete dezakeen gehienezko lerro-kopurua.\",\n      \"options\": [\n        {\n          \"label\": \"lerro 1\"\n        },\n        {\n          \"label\": \"3 lerro\"\n        },\n        {\n          \"label\": \"10 lerro\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Beharrezko eremua\",\n      \"description\": \"Aukera ezazu eremua derrigorrezkoa izan dadin. Erabiltzaileak derrigorrezko eremu guztiak bete beharko ditu dokumentua esportatu ahal izateko.\"\n    },\n    {\n      \"label\": \"Gertatzen den karaktere-kopurua\",\n      \"default\": \"Geratzen den karaktere-kopurua: @chars\",\n      \"description\": \"Geratzen den karaktere-kopururako mezua. Dagokion zenbakiarekin ordezkatuko den @chars erabil dezakezu.\"\n    }\n  ]\n}\n'),
(1933,94,'fi','{\n  \"semantics\": [\n    {\n      \"label\": \"Syöttökentän kuvaus\",\n      \"description\": \"Kuvaus mitä käyttäjän tulisi syöttää kenttään.\"\n    },\n    {\n      \"label\": \"Väliaikaisteksti\",\n      \"description\": \"Väliaikaisteksti käyttäjälle\"\n    },\n    {\n      \"label\": \"Tekstin maksimipituus\",\n      \"description\": \"Tekstin maksimimerkkimäärä\"\n    },\n    {\n      \"label\": \"Syöttökentän koko\",\n      \"description\": \"Kuinka suuri kenttä on johon käyttäjä voi kirjoittaa riveissä.\",\n      \"options\": [\n        {\n          \"label\": \"1 rivi\"\n        },\n        {\n          \"label\": \"3 riviä\"\n        },\n        {\n          \"label\": \"10 riviä\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Pakollinen kenttä\",\n      \"description\": \"Valitse tehdäksesi tästä kentästä pakollisen täyttää. Käyttäjän on täytettävä kaikki kentät ennen kuin hän voi ottaa dokumentin ulos.\"\n    },\n    {\n      \"label\": \"Jäljellä oleva merkkimäärä\",\n      \"default\": \"Merkkejä jäljellä: @chars\",\n      \"description\": \"Viesti joka näytetään jäljellä oleville merkeille. Voit käyttää muuttujaa @chars joka korvataan jäljellä olevien merkkien lukumäärällä.\"\n    }\n  ]\n}\n'),
(1934,94,'fr','{\n  \"semantics\": [\n    {\n      \"label\": \"Description du champ de saisie\",\n      \"description\": \"Description de l\'information que l\'utilisateur doit saisir.\"\n    },\n    {\n      \"label\": \"Texte de l\'espace réservé\",\n      \"description\": \"Un texte de l\'espace réservé pour l\'utilisateur.\"\n    },\n    {\n      \"label\": \"Taille du champ de saisie\",\n      \"description\": \"La taille du champ de saisie en nombre de lignes qu\'il peut contenir.\"\n    },\n    {\n      \"label\": \"Champ requis\",\n      \"description\": \"Cocher pour indiquer que ce champ est requis. L\'utilisateur doit compléter tous les champs requis pour être en mesure d\'exporter le document.\",\n      \"options\": [\n        {\n          \"label\": \"1 line\"\n        },\n        {\n          \"label\": \"3 lines\"\n        },\n        {\n          \"label\": \"10 lines\"\n        }\n      ]\n    },\n    {\n      \"label\": \"Required field\",\n      \"description\": \"Check to make this field required, the user must answer all required fields to be able to export a document.\"\n    },\n    {\n      \"label\": \"Remaining characters\",\n      \"default\": \"Remaining characters: @chars\",\n      \"description\": \"Message for remaining characters. You can use @chars which will be replaced by the corresponding number.\"\n    }\n  ]\n}'),
